function searchKey(value){return String(value).toLocaleLowerCase('tr-TR').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/ı/g,'i').replace(/[^a-z0-9]+/g,' ').trim()}

const items=[{"id":"new1","name":"Salât-ı Fâtih","aliases":"Salâtü’l-Fâtih; Salât-ı Fethiye","arabic":"اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ الْفَاتِحِ لِمَا أُغْلِقَ، وَالْخَاتِمِ لِمَا سَبَقَ، نَاصِرِ الْحَقِّ بِالْحَقِّ، وَالْهَادِي إِلَى صِرَاطِكَ الْمُسْتَقِيمِ، وَعَلَى آلِهِ حَقَّ قَدْرِهِ وَمِقْدَارِهِ الْعَظِيمِ.","latin":"Allahümme salli alâ seyyidinâ Muhammedin, el-Fâtihi limâ uğlika, ve’l-hâtimi limâ sebeka, nâsıri’l-hakkı bi’l-hakkı, ve’l-hâdî ilâ sırâtike’l-müstekîmi, ve alâ âlihî hakka kadrihî ve mikdârihî’l-azîm.","meaning":"Allah’ım! Kapalı olanı açan, kendisinden önce geçenlerin sonuncusu olan, hakkı hak ile destekleyen ve Senin dosdoğru yoluna yönelten Efendimiz Muhammed’e; onun ailesine, kendisinin yüce değerine ve büyüklüğüne yaraşır ölçüde salât eyle.","cat":"new","note":"Muhammed el-Bekrî’ye nispet edilen sözde, bu salavatı ömründe bir defa okuyup cehenneme giren kişinin Allah Teâlâ huzurunda kendisinden hesap sorabileceği şeklinde kuvvetli bir fazilet ifadesi nakledilir. Bu, evliya sözü olarak aktarılır.","source":"Yûsuf en-Nebhânî, Efdalü’s-Salavât, 50. salavat; Abdürrahman el-Küzberî’nin Bedîrî el-Kudsî’ye verdiği icazet sonundaki nakil.","arabicDraft":false},{"id":"koleksiyon146","name":"Salât-ı Yâkûtiye","aliases":"Orijinal liste: 146","arabic":"بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ. إِنَّ اللَّهَ وَمَلَائِكَتَهُ يُصَلُّونَ عَلَى النَّبِيِّ يَا أَيُّهَا الَّذِينَ آمَنُوا صَلُّوا عَلَيْهِ وَسَلِّمُوا تَسْلِيمًا.\nاللَّهُمَّ صَلِّ وَسَلِّمْ عَلَى مَنْ جَعَلْتَهُ سَبَبًا لِانْشِقَاقِ أَسْرَارِكَ الْجَبَرُوتِيَّةِ وَانْفِلَاقِ أَنْوَارِكَ الرَّحْمَانِيَّةِ فَصَارَ نَائِبًا عَنِ الْحَضْرَةِ الرَّبَّانِيَّةِ وَخَلِيفَةَ أَسْرَارِكَ الذَّاتِيَّةِ فَهُوَ يَاقُوتَةُ أَحَدِيَّةِ ذَاتِكَ الصَّمَدِيَّةِ وَعَيْنُ مَظْهَرِ صِفَاتِكَ الْأَزَلِيَّةِ فَبِكَ مِنْكَ صَارَ حِجَابًا عَنْكَ وَسِرًّا مِنْ أَسْرَارِ غَيْبِكَ حُجِبْتَ بِهِ عَنْ كَثِيرٍ مِنْ خَلْقِكَ فَهُوَ الْكَنْزُ الْمُطَلْسَمُ وَالْبَحْرُ الزَّاخِرُ الْمُطَمْطَمُ.\nفَنَسْأَلُكَ اللَّهُمَّ بِجَاهِهِ لَدَيْكَ وَبِكَرَامَتِهِ عَلَيْكَ أَنْ تَعْمُرَ قَوَالِبَنَا بِأَفْعَالِهِ وَأَسْمَاعَنَا بِأَقْوَالِهِ وَقُلُوبَنَا بِأَنْوَارِهِ وَأَرْوَاحَنَا بِأَسْرَارِهِ وَأَشْبَاحَنَا بِأَحْوَالِهِ وَسَرَائِرَنَا بِمُعَامَلَتِهِ وَبَوَاطِنَنَا بِمُشَاهَدَتِهِ وَأَبْصَارَنَا بِأَنْوَارِ مُحَيَّا جَمَالِهِ وَخَوَاتِمَ أَعْمَالِنَا فِي مَرْضَاتِهِ حَتَّى نَشْهَدَكَ بِهِ وَهُوَ بِكَ فَأَكُونَ نَائِبًا عَنِ الْحَضْرَتَيْنِ بِالْحَضْرَتَيْنِ وَأَدُلَّ بِهَا عَلَيْهِمَا.\nوَنَسْأَلُكَ اللَّهُمَّ أَنْ تُصَلِّيَ وَتُسَلِّمَ عَلَيْهِ صَلَاةً وَتَسْلِيمًا يَلِيقَانِ بِجَنَابِهِ وَعَظِيمِ قَدْرِهِ وَتَجْمَعَنِي بِهِمَا عَلَيْهِ وَتُقَرِّبَنِي بِخَالِصِ وُدِّهِمَا لَدَيْهِ وَتَنْفَحَنِي بِسَبَبِهِمَا نَفْحَةَ الْأَتْقِيَاءِ وَتَمْنَحَنِي مِنْهُمَا مِنْحَةَ الْأَصْفِيَاءِ لِأَنَّهُ السِّرُّ الْمَصُونُ وَالْجَوْهَرُ الْفَرْدُ الْمَكْنُونُ فَهُوَ الْيَاقُوتَةُ الْمُنْطَوِيَّةُ عَلَيْهَا أَصْدَافُ مَكْنُونَاتِكَ وَالْغَيْهُوبَةُ الْمُنْتَخَبُ مِنْهَا أَصْنَافُ مَعْلُومَاتِكَ فَكَانَ غَيْبًا مِنْ غَيْبِكَ وَبَدَلًا مِنْ سِرِّ رُبُوبِيَّتِكَ حَتَّى صَارَ بِذَلِكَ مَظْهَرًا نَسْتَدِلُّ بِهِ عَلَيْكَ وَكَيْفَ لَا يَكُونُ كَذَلِكَ وَقَدْ أَخْبَرْتَنَا بِذَلِكَ فِي مُحْكَمِ كِتَابِكَ بِقَوْلِكَ إِنَّ الَّذِينَ يُبَايِعُونَكَ إِنَّمَا يُبَايِعُونَ اللَّهَ فَقَدْ زَالَ عَنَّا بِذَلِكَ الرَّيْبُ وَحَصَلَ الِانْتِبَاهُ وَاجْعَلِ اللَّهُمَّ دَلَالَتَنَا عَلَيْكَ بِهِ وَمُعَامَلَتَنَا مَعَكَ مِنْ أَنْوَارِ مُتَابَعَتِهِ وَارْضَ اللَّهُمَّ عَلَى مَنْ جَعَلْتَهُمْ مَحَلًّا لِلِاقْتِدَاءِ وَصَيَّرْتَ قُلُوبَهُمْ دُرَرَ الْمَعَانِي فَجَعَلْتَ قَلَائِدَ التَّحْقِيقِ لِأَهْلِ الْمَبَانِي وَاخْتَرْتَهُمْ فِي سَابِقِ الِاقْتِدَارِ إِنَّهُمْ أَصْحَابُ نَبِيِّكَ الْمُخْتَارِ وَرَضِيتَهُمْ لِانْتِصَارِ دِينِكَ فَهُمُ السَّادَةُ الْأَخْيَارُ وَضَاعِفِ اللَّهُمَّ مَزِيدَ رِضْوَانِكَ عَلَيْهِمْ مَعَ الْآلِ وَالْعَشِيرَةِ وَالْمُقْتَفِينَ لِلْآثَارِ وَاغْفِرِ اللَّهُمَّ ذُنُوبَنَا وَوَالِدَيْنَا وَمَشَايِخِنَا وَإِخْوَانِنَا فِي اللَّهِ وَجَمِيعِ الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ وَالْمُسْلِمِينَ وَالْمُسْلِمَاتِ الْمُطِيعِينَ مِنْهُمْ وَأَهْلِ الْأَوْزَارِ.","latin":"Bismillâhirrahmânirrahîm. İnnallâhe ve melâiketehû yüsallûne alen-nebiyyi yâ eyyühellezîne âmenû sallû aleyhi ve sellimû teslîmâ.\nAllâhümme salli ve sellim alâ men cealtehû sebeben linşikâkı esrârikel-ceberûtiyyeti venfilâkı envâriker-rahmâniyyeti fe-sâra nâiben anil-hadratir-rabbâniyyeti ve halîfete esrârikez-zâtiyyeti fe-hüve yâkûtetü ehadiyyeti zâtikes-samediyyeti ve aynü mazheri sıfâtikel-ezeliyyeti fe-bike minke sâra hicâben anke ve sirran min esrâri ğaybike hucibte bihî an kesîrin min halkıke fe-hüvel-kenzül-mutalsemü vel-bahrüz-zâhirul-mutamtam.\nFe-nes’elükellâhümme bi-câhihî ledeyke ve bi-kerâmetihî aleyke en ta‘müra kavâlibenâ bi-ef‘âlihî ve esmâ‘anâ bi-akvâlihî ve kulûbenâ bi-envârihî ve ervâhanâ bi-esrârihî ve eşbâhanâ bi-ahvâlihî ve serâiranâ bi-muâmeletihî ve bevâtınenâ bi-müşâhedetihî ve ebsâranâ bi-envâri muhayyâ cemâlihî ve havâtime a‘mâlinâ fî merdâtihî hattâ neşhedeke bihî ve hüve bike fe-ekûne nâiben anil-hadrateyni bil-hadrateyni ve edülle bihâ aleyhimâ.\nVe nes’elükellâhümme en tusalliye ve tüsellime aleyhi salâten ve teslîmen yelîkâni bi-cenâbihî ve azîmi kadrihî ve tecmeanî bihimâ aleyhi ve tukarribenî bi-hâlisi vüddihimâ ledeyhi ve tenfehanî bi-sebebihimâ nefhatel-etkıyâi ve temnehanî minhümâ minhatel-asfiyâi li-ennehüs-sirrul-masûnü vel-cevherul-ferdül-meknûnü fe-hüvel-yâkûtetül-muntaviyetü aleyhâ esdâfü meknûnâtike vel-ğayhûbetül-müntehabü minhâ asnâfü ma‘lûmâtike fe-kâne ğayben min ğaybike ve bedelen min sirri rubûbiyyetike hattâ sâra bi-zâlike mazheran nestedillü bihî aleyke ve keyfe lâ yekûnü kezâlike ve kad ahbartenâ bi-zâlike fî muhkemi kitâbike bi-kavlike innellezîne yübâyiûneke innemâ yübâyiûnallâhe fe-kad zâle annâ bi-zâliker-raybü ve hasalel-intibâhü vec‘alillâhümme delâletenâ aleyke bihî ve muâmeletenâ meake min envâri mütâbe‘atihî varda Allâhümme alâ men cealtehüm mahallen lil-iktidâi ve sayyarte kulûbehüm düraral-meânî fe-cealte kalâidet-tahkîkı li-ehlil-mebânî vahtertehüm fî sâbikıl-iktidâri innehüm ashâbü nebiyyikel-muhtâri ve radîtehüm lintisâri dînike fe-hümüs-sâdetül-ahyâr. Ve dâifillâhümme mezîde rıdvânike aleyhim meal-âli vel-aşîrati vel-muktefîne lil-âsâri vağfirillâhümme zünûbenâ ve vâlideynâ ve meşâyihinâ ve ihvâninâ fillâhi ve cemîil-mü’minîne vel-mü’minâti vel-müslimîne vel-müslimâtil-mutîîne minhüm ve ehlil-evzâr.","meaning":"Rahmân ve Rahîm olan Allah’ın adıyla. Şüphesiz Allah ve melekleri Peygamber’e salât ederler. Ey iman edenler! Siz de ona salât edin ve tam bir teslimiyetle selâm verin.\nAllah’ım! Ceberûtî sırlarının açılmasına ve Rahmânî nurlarının ortaya çıkmasına vesile kıldığın zâta salât ve selâm eyle. O, Rabbânî huzurun temsilcisi ve zâtî sırlarının halifesi olmuştur. O, Samed olan zâtının birliğinin yakutu ve ezelî sıfatlarının görünme kaynağıdır. Seninle ve Senden, Sana bir perde ve gaybının sırlarından bir sır olmuştur; yaratılmışlarının çoğuna karşı onunla perdelendin. O, sırrı örtülü hazine ve engin, dalgalı denizdir.\nAllah’ım! Onun Senin katındaki makamı ve değeri hürmetine bedenlerimizi onun fiilleriyle, işitme duyularımızı onun sözleriyle, kalplerimizi onun nurlarıyla, ruhlarımızı onun sırlarıyla, varlığımızı onun hâlleriyle, gönlümüzün gizli yönlerini onun muamelesiyle, iç dünyamızı onun müşahedesiyle, gözlerimizi onun güzel yüzünün nurlarıyla ve amellerimizin sonlarını onun hoşnutluğuyla mamur etmeni diliyoruz. Öyle ki onunla Seni müşahede edelim; o da Seninle olsun. Böylece iki huzur vasıtasıyla iki huzurun temsilcisi olayım ve bununla ikisine rehberlik edeyim.\nAllah’ım! Ona, yüce huzuruna ve büyük değerine yaraşır salât ve selâm ihsan etmeni; bu salât ve selâmla beni onun üzerinde toplamanı, bunların halis sevgisiyle onun katına yaklaştırmanı, bunlar sebebiyle bana takvâ sahiplerinin esintisinden bir esinti ve seçkin kulların bağışından bir bağış lütfetmeni diliyorum. Çünkü o, korunmuş sır ve gizlenmiş eşsiz cevherdir. O, gizli hazinelerinin sedeflerinin içinde saklı bulunan yakut ve bildiklerinin çeşitlerinin içinden seçildiği derin gaybdır. Gaybından bir gayb ve rubûbiyet sırrından bir karşılık olmuş; böylece Sana kendisiyle delil getirdiğimiz bir görünme yeri hâline gelmiştir. Nasıl böyle olmasın ki Sen sağlam kitabında “Sana biat edenler ancak Allah’a biat etmektedirler.” buyurarak bunu bize bildirdin. Böylece şüphemiz giderildi ve uyanış gerçekleşti. Allah’ım! Onunla Sana rehberlik edişimizi ve Seninle muamelemizi ona uymanın nurlarından kıl. Kendilerini örnek alınacak kimseler kıldığın, kalplerini mana incilerine dönüştürdüğün ve hakikati gerçekleştirmenin gerdanlıklarını suret ehline lütfettiğin kimselerden razı ol. Onları ezelî kudretinde seçtin; onlar seçilmiş peygamberinin ashabıdır. Dininin yardımına onları layık gördün; onlar hayırlı efendilerdir. Allah’ım! Ailesi, yakınları ve onların izlerini takip edenlerle birlikte onlara olan rızanı kat kat artır. Bizim, anne babalarımızın, şeyhlerimizin, Allah yolundaki kardeşlerimizin ve bütün mümin erkeklerle kadınların, Müslüman erkeklerle kadınların; itaatkâr olanlarının da günah yükü taşıyanlarının da günahlarını bağışla.","cat":"derleme","note":"Muhammed el-Fâsî eş-Şâzelî’ye nispet edilir. Nebhânî, salavatı oluşturduktan sonra şeyhin Peygamber Efendimiz’i (sallallahu aleyhi ve sellem) gördüğünü ve kendisine “Bu, korunmuş sırdır” denildiğini aktarır. Sabah-akşam üçer defa okumaya ilişkin mânevî görüş müjdesi nakledilir.","source":"Nebhânî, Saâdetü’d-Dâreyn, 8. bölüm, 117; Wird: Salawāt al-Awliyā, Arapça nüsha, s. 16–18.","arabicDraft":false,"previousArabic":"بيسميللاهيرراهمانيرراهيم. ي̇نناللاها و مالايكاتاهو يوساللونا الاننابيي يا ايوهاللازينا امانو ساللو الايهي و سالليمو تاسليما. اللهم صل و سلم على مان جاالتاهو سابابان لينشيكاكا اسراريكال جاباروتيا وانفيلاكا انواريكار راهمانيا. فا سارا نايبان انيل هادراتير راببانيا و هاليفاتا اسراريكاز زاتيا. فا هووا ياكوتاتو اهادياتي زاتيكاس ساماديا و اينو مازهاري سافاتيكال ازاليا. و ناسالوكاللاهومما ب جاهيهي لادايكا و ب كاراماتيهي الايكا ان تامورا كاواليبانا ب افاليهي و اسماانا ب اكواليهي و كولوبانا ب انواريهي و ارواهانا ب اسراريهي. و ناسالوكاللاهومما ان توساللييا و توسالليما الايهي صلاة و تاسليمان ياليكاني ب جانابيهي و ازيمي كادريهي. واغفيريللاهومما زونوبانا و واليداينا و ماشاييهينا و يهوانينا فيللاه و جامييل مومينينا وال مومينات وال موسليمينا وال موسليمات.","submittedArabic":"بِسْمِ اللّٰهِ الرَّحْمٰنِ الرَّحِيمِ. اِنَّ اللّٰهَ وَمَلَائِكَتَهُ يُصَلُّونَ عَلَى النَّبِيِّ يَا اَيُّهَا الَّذِينَ اٰمَنُوا صَلُّوا عَلَيْهِ وَسَلِّمُوا تَسْلِيماً. اَللّٰهُمَّ صَلِّ وَسَلِّيمْ عَلٰى مَنْ جَعَلْتَهُ سَبَباً لِانْشِقَاقِ اَسْرَارِكَ الْجَبَرُوتِيَّةِ وَانْفِلَاقِ اَنْوَارِكَ الرَّحْمَانِيَّةِ. فَصَارَ نَائِباً عَنِ الْحَضْرَةِ الرَّبَّانِيَّةِ وَخَلِيفَةَ اَسْرَارِكَ الذَّاتِيَّةِ. فَهُوَ يَاقُوتَةُ اَحَدِيَّةِ ذَاتِكَ الصَّمَدِيَّةِ وَعَيْنُ مَظْهَرِ صِفَاتِكَ الْاَزَلِيَّةِ. وَنَسْاَلُكَ اللّٰهُمَّ بِجَاهِهِ لَدَيْكَ وَبِكَرَامَتِهِ عَلَيْكَ اَنْ تَعْمُرَ كَوَالِبَنَا بِاَفْعَالِهِ وَاَسْمَاعَنَا بِاَقْوَالِهِ وَقُلُوبَنَا بِاَنْوَارِهِ وَاَرْوَاحَنَا بِاَسْرَارِهِ. وَنَسْاَلُكَ اللّٰهُمَّ اَنْ تُصَلِّيَ وَتُسَلِّمَ عَلَيْهِ صَلَاةً وَتَسْلِيماً يَلِيقَانِ بِجَنَابِهِ وَعَظِيمِ قَدْرِهِ. وَاغْفِرِ اللّٰهُمَّ ذُنُوبَنَا وَوَالِدَيْنَا وَمَشَايِخِنَا وَاِخْوَانِنَا فِي اللّٰهِ وَجَمِيعِ الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ وَالْمُسْلِمِينَ وَالْمُسْلِمَاتِ.","source_note":"","displayNumber":7},{"id":"koleksiyon145","name":"Cevheretü’l-Kemâl","aliases":"Orijinal liste: 145","arabic":"بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ. اللَّهُمَّ صَلِّ وَسَلِّمْ عَلَى عَيْنِ الرَّحْمَةِ الرَّبَّانِيَّةِ وَالْيَاقُوتَةِ الْمُتَحَقِّقَةِ الْحَائِطَةِ بِمَرْكَزِ الْفُهُومِ وَالْمَعَانِي وَنُورِ الْأَكْوَانِ الْمُتَكَوِّنَةِ الْآدَمِيِّ صَاحِبِ الْحَقِّ الرَّبَّانِيِّ الْبَرْقِ الْأَسْطَعِ بِمُزْنِ الْأَرْيَاحِ الْمَالِئَةِ لِكُلِّ مُتَعَرِّضٍ مِنَ الْبُحُورِ وَالْأَوَانِي وَنُورِكَ اللَّامِعِ الَّذِي مَلَأْتَ بِهِ كَوْنَكَ الْحَائِطِ بِأَمْكِنَةِ الْمَكَانِ. اللَّهُمَّ صَلِّ وَسَلِّمْ عَلَى عَيْنِ الْحَقِّ الَّتِي تَتَجَلَّى مِنْهَا عُرُوشُ الْحَقَائِقِ عَيْنِ الْمَعَارِفِ الْأَقْدَمِ صِرَاطِكَ التَّامِّ الْأَقْوَمِ. اللَّهُمَّ صَلِّ وَسَلِّمْ عَلَى طَلْعَةِ الْحَقِّ بِالْحَقِّ الْكَنْزِ الْأَعْظَمِ إِفَاضَتِكَ مِنْكَ إِلَيْكَ إِحَاطَةِ النُّورِ الْمُطَلْسَمِ صَلَّى اللَّهُ عَلَيْهِ وَعَلَى آلِهِ صَلَاةً تُعَرِّفُنَا بِهَا إِيَّاهُ.","latin":"Bismillâhirrahmânirrahîm. Allâhümme salli ve sellim alâ aynir-rahmetir-rabbâniyyeti vel-yâkûtetil-mütehakkıkatil-hâitati bi-merkezil-fühûmi vel-meânî ve nûril-ekvânil-mütekevvinetil-âdemiyyi sâhibil-hakkır-rabbâniyyil-berkıl-esta‘i bi-müznil-eryâhil-mâlieti li-külli mütearridin minel-buhûri vel-evânî ve nûrikel-lâmiillezî mele’te bihî kevnekel-hâiti bi-emkinetil-mekân. Allâhümme salli ve sellim alâ aynil-hakkılletî tetecellâ minhâ urûşül-hakâikı aynil-meârifil-akdemi sırâtiket-tâmmil-akvem. Allâhümme salli ve sellim alâ tal‘atil-hakkı bil-hakkıl-kenzil-a‘zami ifâdatike minke ileyke ihâtatin-nûril-mutalsem. Sallallâhu aleyhi ve alâ âlihî salâten tüarrifünâ bihâ iyyâh.","meaning":"Rahmân ve Rahîm olan Allah’ın adıyla. Allah’ım! Rabbânî rahmetin kaynağına; kavrayışların ve manaların merkezini kuşatan hakikat yakutuna; meydana gelen âlemlerin nuruna, Rabbânî hakkın sahibi olan Âdemî zâta salât ve selâm eyle. O, kendisine yönelen bütün denizleri ve kapları dolduran rüzgâr bulutlarıyla çakan en parlak şimşek ve mekânların yerlerini kuşatan âlemini kendisiyle doldurduğun parlayan nurundur. Allah’ım! Hakikatlerin arşlarının kendisinden tecelli ettiği hakikat kaynağına, en kadîm mârifetlerin kaynağına, Senin eksiksiz ve dosdoğru yoluna salât ve selâm eyle. Allah’ım! Hak ile görünen hakikat tecellisine, en büyük hazineye, Senden Sana olan feyzine, sırrı örtülü nurun kuşatıcılığına salât ve selâm eyle. Allah ona ve ailesine, vesilesiyle kendisini bize tanıtacak bir salât ihsan eylesin.","cat":"derleme","note":"Ali Harâzim’in Cevâhirü’l-Meânî adlı eserinde Ahmed et-Ticânî’nin Peygamber Efendimizden uyanıklık hâlinde Cevheretü’l-Kemâl salavatını aldığı anlatılır. Yedi defa veya daha fazla okumaya ilişkin manevi buluşma nakli de aktarılır.","source":"Nebhânî, Saâdetü’d-Dâreyn, 8. bölüm, 112.","arabicDraft":false,"previousArabic":"بيسميللاهيرراهمانيرراهيم. اللهم صل و سلم على اينير راهماتير راببانياتي وال ياكوتاتيل موتاهاككاكاتيل هايتاتي ب ماركازيل فوهومي وال مااني و نوريل اكوانيل موتاكاوويناتيل اداميي ساهيبيل هاككار رابباني. اللهم صل و سلم على اينيل هاككاللاتي تاتاجاللا مينها وروشول هاكايك, اينيل مااريفيل اكوام. اللهم صل و سلم على تالاتيل الحق بيل هاككال كانزيل ازام. ساللاللاهو الايهي و على اليهي صلاة توارريفونا بيها ياه.","submittedArabic":"بِسْمِ اللّٰهِ الرَّحْمٰنِ الرَّحِيمِ. اَللّٰهُمَّ صَلِّ وَسَلِّيمْ عَلٰى عَيْنِ الرَّحْمَةِ الرَّبَّانِيَّةِ وَالْيَاقُوتَةِ الْمُتَحَقِّقَةِ الْحَائِطَةِ بِـمَرْكَزِ الْفُهُومِ وَالْمَعَانِي وَنُورِ الْاَكْوَانِ الْمُتَكَوِّنَةِ الْاٰدَمِيِّ صَاحِبِ الْحَقِّ الرَّبَّانِي. اَللّٰهُمَّ صَلِّ وَسَلِّيمْ عَلٰى عَيْنِ الْحَقِّ الَّتِي تَتَجَلّٰى مِنْهَا عُرُوشُ الْحَقَائِقِ، عَيْنِ الْمَعَارِفِ الْاَقْوَمِ. اَللّٰهُمَّ صَلِّ وَسَلِّيمْ عَلٰى طَلْعَةِ الْحَقِّ بِالْحَقِّ الْكَنْزِ الْاَعْظَمِ. صَلَّى اللّٰهُ عَلَيْهِ وَعَلٰى اٰلِهِ صَلَاةً تُعَرِّفُنَا بِهَا اِيَّاهُ.","source_note":"","displayNumber":80},{"id":"new2","name":"Salât-ı Tefriciye","aliases":"Salât-ı Nâriye; Salât-ı Kâmile; 4444 Salavatı","arabic":"اللَّهُمَّ صَلِّ صَلَاةً كَامِلَةً وَسَلِّمْ سَلَامًا تَامًّا عَلَى سَيِّدِنَا مُحَمَّدٍ الَّذِي تَنْحَلُّ بِهِ الْعُقَدُ وَتَنْفَرِجُ بِهِ الْكُرَبُ وَتُقْضَى بِهِ الْحَوَائِجُ وَتُنَالُ بِهِ الرَّغَائِبُ وَحُسْنُ الْخَوَاتِيمِ وَيُسْتَسْقَى الْغَمَامُ بِوَجْهِهِ الْكَرِيمِ وَعَلَى آلِهِ وَصَحْبِهِ فِي كُلِّ لَمْحَةٍ وَنَفَسٍ بِعَدَدِ كُلِّ مَعْلُومٍ لَكَ.","latin":"Allahümme salli salâten kâmileten ve sellim selâmen tâmmen alâ seyyidinâ Muhammedinillezî tenhallü bihil ukadü ve tenfericü bihil kürebü ve tukdâ bihil havâicü ve tünâlü bihir-regâibü ve hüsnül-havâtim ve yüsteskal gamâmu bi-vechihil kerîmi ve alâ âlihî ve sahbihî fî külli lemhatin ve nefesin bi-adedi külli ma’lûmin lek.","meaning":"Allah’ım! Efendimiz Muhammed’e (sallallahu aleyhi ve sellem), ailesine ve ashabına, her bakışta ve her nefeste, Senin bildiğin her şeyin sayısınca eksiksiz bir salât ve tam bir selâm eyle. Onun vesilesiyle düğümler çözülür, sıkıntılar açılır, ihtiyaçlar giderilir, arzulanan şeylere ve güzel sonlara erişilir; onun mübarek yüzü hürmetine bulutlardan yağmur istenir.","cat":"new","note":"Muhammed Hakkı en-Nâzilî, Kurtubî’ye nispetle şöyle nakleder: Her gün kırk, yüz veya daha fazla defa okumaya devam edenin üzüntü ve kederinin giderileceği, işinin kolaylaşacağı anlatılır. Mağrib ehlinin bir ihtiyaç yahut korku için toplanıp bu salavatı 4444 defa okudukları da aynı anlatımda yer alır.","source":"Nebhânî, Efdalü’s-Salavât, 63. salavat; Muhammed Hakkı en-Nâzilî, Hazînetü’l-Esrâr.","arabicDraft":false},{"id":"new3","name":"Salât-ı Münciye","aliases":"Salâten Tüncînâ; Kurtarıcı Salavat","arabic":"اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ وَعَلَى آلِ سَيِّدِنَا مُحَمَّدٍ صَلَاةً تُنْجِينَا بِهَا مِنْ جَمِيعِ الْأَهْوَالِ وَالْآفَاتِ، وَتَقْضِي لَنَا بِهَا جَمِيعَ الْحَاجَاتِ، وَتُطَهِّرُنَا بِهَا مِنْ جَمِيعِ السَّيِّئَاتِ، وَتَرْفَعُنَا بِهَا عِنْدَكَ أَعْلَى الدَّرَجَاتِ، وَتُبَلِّغُنَا بِهَا أَقْصَى الْغَايَاتِ مِنْ جَمِيعِ الْخَيْرَاتِ فِي الْحَيَاةِ وَبَعْدَ الْمَمَاتِ، إِنَّكَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ.","latin":"Allâhümme salli alâ seyyidinâ Muhammedin ve alâ âli seyyidinâ Muhammedin salâten tüncînâ bihâ min cemî’ıl-ehvâli ve’l-âfât. Ve takdî lenâ bihâ cemî’al-hâcât ve tütahhirunâ bihâ min cemî’ıs-seyyiât ve terfe’unâ bihâ indeke a‘led-derecât ve tübelliğunâ bihâ aksa’l-ğâyât min cemî’ıl-hayrâti fi’l-hayâti ve ba’de’l-memât. İnneke alâ külli şey’in kadîr.","meaning":"Allah’ım! Efendimiz Muhammed’e ve Efendimiz Muhammed’in ailesine öyle bir salât eyle ki onunla bizi bütün korkulardan ve afetlerden kurtarasın; bütün ihtiyaçlarımızı gideresin; bizi bütün kötülüklerden arındırasın; katında en yüksek derecelere yükseltesin; hayatta ve ölümden sonra bütün hayırların en son gayelerine ulaştırasın. Şüphesiz Sen her şeye kadirsin.","cat":"new","note":"Mûsâ ed-Darîr şöyle anlatır: “Denize açıldım. Üzerimize, yakalananların pek azının kurtulduğu bir rüzgâr çıktı. İnsanlar feryat ederken uykuya daldım. Rüyamda Peygamberimizi gördüm. Gemidekilere bu salavatı bin defa okumalarını söylememi buyurdu. Uyandım ve rüyayı yolculara anlattım. Üç yüz kadar okumuştuk ki Allah bizi sıkıntıdan kurtardı.”","source":"Nebhânî, Efdalü’s-Salavât, 26. salavat; Fâkihânî’nin Mûsâ ed-Darîr’den nakli; Saâdetü’d-Dâreyn’de Fâkihânî’nin el-Fecrü’l-Münîr’ine atıf.","arabicDraft":false},{"id":"new4","name":"Salât-ı Ümmiye","aliases":"Itrî Salavatı; Segâh Salavat","arabic":"اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ النَّبِيِّ الْأُمِّيِّ وَعَلَى آلِهِ وَصَحْبِهِ وَسَلِّمْ.","latin":"Allâhümme salli alâ seyyidinâ Muhammedini’n-nebiyyi’l-ümmiyyi ve alâ âlihî ve sahbihî ve sellim.","meaning":"Allah’ım! Ümmî peygamber Efendimiz Muhammed’e, ailesine ve ashabına salât ve selâm eyle.","cat":"new","note":"Şihâbüddin Ahmed el-Mellevî, Abdullah eş-Şerîf el-Alemî hakkında bu salavatın onun yolunun esası olduğunu; bu yolla kendisinin ve talebelerinin manevî makamlara eriştiğini nakleder. Günlük virdinin yirmi beş bin salavat olduğu aktarılır.","source":"Nebhânî, Saâdetü’d-Dâreyn fî’s-Salâti alâ Seyyidi’l-Kevneyn, 8. bölüm, 6. salavat; Mellevî derlemesi.","arabicDraft":false},{"id":"new5","name":"Salât-ı Kemâliye","aliases":"Salâtü’l-Kemâl; Kemâlât Salavatı; Eski liste 172 ile birleştirildi","arabic":"اللَّهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَى سَيِّدِنَا مُحَمَّدٍ وَعَلَى آلِهِ كَمَا لَا نِهَايَةَ لِكَمَالِكَ وَعَدَدَ كَمَالِهِ.","latin":"Allahümme salli ve sellim ve bârik alâ seyyidinâ Muhammedin ve alâ âlihî kemâ lâ nihâyete li-kemâlike ve adede kemâlihî.","meaning":"Allah’ım! Efendimiz Muhammed’e ve âline, Senin kemalinin sonu olmadığı gibi, onun kemalinin sayısınca salât, selâm ve bereket ihsan eyle.","cat":"new","note":"Ali eş-Şebramellisî, ilim öğrenirken bir mesele sebebiyle üzülüp iki gün yemek yiyemediğini anlatır. Yanına gelen bir zat, meşguliyete bağlanmama şartıyla kendisine bir fayda öğreteceğini söyler. Şebramellisî, bu zatın kendisine unutkanlık için bu salavatı öğrettiğini ve akşam ile yatsı arasında, belirli bir sayı gözetmeden okumasını söylediğini nakleder.","source":"Nebhânî, Saâdetü’d-Dâreyn, 8. bölüm, 95. salavat; Sâlim b. Ahmed eş-Şemmâ ve Abdullah b. Sâlim el-Basrî tercümeleri.","arabicDraft":false},{"id":"new6","name":"Salât-ı Kutbiyye","aliases":"Salâtü’l-Kutb; Kutubların Salavatı","arabic":"اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ فِي الْأَوَّلِينَ، وَصَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ فِي الْآخِرِينَ، وَصَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ فِي النَّبِيِّينَ، وَصَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ فِي الْمُرْسَلِينَ، وَصَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ فِي الْمَلَإِ الْأَعْلَى إِلَى يَوْمِ الدِّينِ.","latin":"Allahümme salli alâ seyyidinâ Muhammedin fil-evvelîn, ve salli alâ seyyidinâ Muhammedin fil-âhirîn, ve salli alâ seyyidinâ Muhammedin fin-nebiyyîn, ve salli alâ seyyidinâ Muhammedin fil-mürselîn, ve salli alâ seyyidinâ Muhammedin fil-meleil-a’lâ ilâ yevmid-dîn.","meaning":"Allah’ım! Öncekiler arasında Efendimiz Muhammed’e salât eyle. Sonrakiler arasında Efendimiz Muhammed’e salât eyle. Peygamberler arasında Efendimiz Muhammed’e salât eyle. Elçiler arasında Efendimiz Muhammed’e salât eyle. Din gününe kadar yüce toplulukta Efendimiz Muhammed’e salât eyle.","cat":"new","note":"Sa‘d b. Utârid’e nispet edilen sözde bu salavatın sabah ve akşam üçer defa okunmasının günahların bağışlanmasına, sevince, duanın kabulüne ve düşmana karşı yardıma vesile olacağı anlatılır.","source":"Nebhânî, Efdalü’s-Salavât, 15. salavat; Şücâî’den nakil.","arabicDraft":false},{"id":"koleksiyon1","name":"Kıyamet Günü Yakın Makam","aliases":"","arabic":"اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَأَنْزِلْهُ الْمَقْعَدَ الْمُقَرَّبَ عِنْدَكَ يَوْمَ الْقِيَامَةِ.","latin":"Allâhümme salli alâ Muhammedin ve enzilhül-mak‘adel-mukarrabe indeke yevmel-kıyâmeh.","meaning":"Allah’ım! Efendimiz Muhammed’e salât eyle ve kıyamet gününde onu katında yakın bir makama yerleştir.","cat":"derleme","note":"Rüveyfi‘ b. Sâbit el-Ensârî’den nakledilen rivayette, “Allah’ım, Muhammed’e salât eyle ve onu kıyamet günü katındaki yakın makama eriştir” diyen kişiye şefaatin gerekeceği anlatılır.","source":"Nebhânî, Saâdetü’d-Dâreyn, 8. bölüm, 1/38.","arabicDraft":false},{"id":"koleksiyon3","name":"Ezvâc ve Ehl-i Beyt Salavatı","aliases":"","arabic":"اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ النَّبِيِّ وَأَزْوَاجِهِ أُمَّهَاتِ الْمُؤْمِنِينَ وَذُرِّيَّتِهِ وَأَهْلِ بَيْتِهِ كَمَا صَلَّيْتَ عَلَى آلِ إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ.","latin":"Allâhümme salli alâ Muhammedinin-nebiyyi ve ezvâcihî ümmehâtil-mü’minîne ve zürriyyetihî ve ehli beytihî kemâ salleyte alâ âli İbrâhîm. İnneke hamîdün mecîd.","meaning":"Allah’ım! Peygamber Efendimiz Muhammed’e (sallallahu aleyhi ve sellem), müminlerin anneleri olan eşlerine, nesline ve Ehl-i Beyt’ine, İbrâhim’in ailesine salât ettiğin gibi salât eyle. Şüphesiz Sen övgüye layık ve şanı yüce olansın.","cat":"derleme","note":"Ebû Hüreyre’den nakledilen rivayette Peygamber Efendimize, müminlerin anneleri olan eşlerine, nesline ve Ehl-i Beyt’ine, İbrahim ailesine salât edildiği gibi salât edilmesi öğretilir.","source":"Ebû Dâvûd, 982.","arabicDraft":false},{"id":"koleksiyon4","name":"Abdike ve Resûlike","aliases":"","arabic":"اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ عَبْدِكَ وَنَبِيِّكَ وَرَسُولِكَ النَّبِيِّ الْأُمِّيِّ","latin":"Allâhümme salli alâ Muhammedin abdike ve nebiyyike ve resûliken-nebiyyil-ümmî.","meaning":"Allah’ım! Kulun, peygamberin, elçin ve ümmî peygamber olan Efendimiz Muhammed’e (sallallahu aleyhi ve sellem) salât eyle.","cat":"derleme","note":"Gazzâlî, cuma günü Peygamber Efendimize seksen defa salavat getirenin seksen yıllık günahının bağışlanacağına dair nakli aktarır. Nasıl salavat getirileceği sorulduğunda “Allahümme salli alâ Muhammedin abdike ve nebiyyike ve resûliken-nebiyyil-ümmî” lafzının öğretildiği belirtilir.","source":"Nebhânî, Saâdetü’d-Dâreyn, 8. bölüm, 6/16 ve Nebhânî, Efdalü’s-Salavât, 13 açıklaması.","arabicDraft":false},{"id":"koleksiyon5","name":"Müminlere Salavat","aliases":"","arabic":"اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ عَبْدِكَ وَرَسُولِكَ وَصَلِّ عَلَى الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ وَالْمُسْلِمِينَ وَالْمُسْلِمَاتِ","latin":"Allâhümme salli alâ Muhammedin abdike ve resûlike ve salli alel mü’minîne vel mü’minâti vel müslimîne vel müslimât.","meaning":"Allah’ım! Kulun ve elçin Efendimiz Muhammed’e, mümin erkeklere ve kadınlara, Müslüman erkeklere ve kadınlara salât eyle.","cat":"derleme","note":"Ebû Saîd el-Hudrî’den aktarılan rivayette, sadaka verecek bir şeyi olmayan Müslümanın duasında Peygamber Efendimize, mümin erkeklere ve kadınlara, Müslüman erkeklere ve kadınlara salât istemesi öğütlenir; bunun kendisi için arınma olacağı nakledilir.","source":"İbn Hibbân, Sahîh 903; Beyhakî, Şuabü’l-Îmân 1176; Sehâvî, el-Kavlü’l-Bedî‘.","arabicDraft":false},{"id":"koleksiyon6","name":"Emredildiği Gibi Salavat","aliases":"","arabic":"اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ النَّبِيِّ كَمَا أَمَرْتَنَا أَنْ نُصَلِّيَ عَلَيْهِ، وَصَلِّ عَلَى مُحَمَّدٍ النَّبِيِّ كَمَا يَنْبَغِي أَنْ يُصَلَّى عَلَيْهِ، وَصَلِّ عَلَى مُحَمَّدٍ بِعَدَدِ مَنْ صَلَّى عَلَيْهِ، وَصَلِّ عَلَى مُحَمَّدٍ النَّبِيِّ بِعَدَدِ مَنْ لَمْ يُصَلِّ عَلَيْهِ، وَصَلِّ عَلَى مُحَمَّدٍ النَّبِيِّ كَمَا تُحِبُّ أَنْ يُصَلَّى عَلَيْهِ.","latin":"Allâhümme salli alâ Muhammedinin-nebiyyi kemâ emertenâ en nusalliye aleyh. Ve salli alâ Muhammedinin-nebiyyi kemâ yenbeğî en yusallâ aleyh. Ve salli alâ Muhammedin bi-adedi men sallâ aleyh. Ve salli alâ Muhammedinin-nebiyyi bi-adedi men lem yusalli aleyh. Ve salli alâ Muhammedinin-nebiyyi kemâ tuhibbü en yusallâ aleyh.","meaning":"Allah’ım! Bize ona salât etmemizi emrettiğin gibi Peygamber Efendimiz Muhammed’e (sallallahu aleyhi ve sellem) salât eyle. Kendisine salât edilmesi gerektiği gibi ona salât eyle. Ona salât edenlerin sayısınca ona salât eyle. Ona salât etmeyenlerin sayısınca ona salât eyle. Kendisine nasıl salât edilmesini seviyorsan öyle salât eyle.","cat":"derleme","note":"","source":"Bursevî, Rûhu’l-Beyân, Ahzâb 33:56.","source_note":" Türkçe anlam, mevcut Latin okunuş üzerinden hazırlanmıştır; özgün nüsha karşılaştırması bekleniyor.","arabicDraft":false},{"id":"koleksiyon7","name":"Kemâ Hüve Ehlühû","aliases":"","arabic":"اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ كَمَا هُوَ أَهْلُهُ، اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ كَمَا تُحِبُّ وَتَرْضَى لَهُ","latin":"Allâhümme salli alâ Muhammedin kemâ hüve ehlühû, Allâhümme salli alâ Muhammedin kemâ tuhibbü ve terdâ lehû.","meaning":"Allah’ım! Peygamber Efendimiz Muhammed’e (sallallahu aleyhi ve sellem) onun layık olduğu şekilde salât eyle. Allah’ım! Peygamber Efendimiz Muhammed’e Senin sevdiğin ve onun hakkında razı olduğun şekilde salât eyle.","cat":"derleme","note":"Şemseddin es-Sehâvî’nin nakline göre, Peygamber Efendimiz (sallallahu aleyhi ve sellem) bir gün huzuruna gelen kişiyi kendisiyle Hz. Ebû Bekir’in arasına oturttu. Bu kişiye gösterilen özel ikram dikkat çekti. Kişi ayrıldıktan sonra bunun sebebi sorulunca Resûlullah, onun kendisine “Allahümme salli alâ Muhammedin kemâ tuhibbü ve terdâ lehû” diye salavat getirdiğini bildirdi.","source":"Şemseddin es-Sehâvî, el-Kavlü’l-Bedî‘ fi’s-Salâti ale’l-Habîbi’ş-Şefî‘, ilgili neşirde s.125; İbn Seb‘, eş-Şifâ ve Şerefü’l-Mustafâ’dan naklen.","arabicDraft":false},{"id":"koleksiyon8","name":"Ruhuna, Bedenine ve Kabrine","aliases":"","arabic":"اللَّهُمَّ صَلِّ عَلَى رُوحِ مُحَمَّدٍ فِي الْأَرْوَاحِ، وَصَلِّ عَلَى جَسَدِ مُحَمَّدٍ فِي الْأَجْسَادِ، وَصَلِّ عَلَى قَبْرِ مُحَمَّدٍ فِي الْقُبُورِ","latin":"Allâhümme salli alâ rûhi Muhammedin fil ervâh, Ve salli alâ cesedi Muhammedin fil ecsâd, Ve salli alâ kabri Muhammedin fil kubûr.","meaning":"Allah’ım! Ruhlar arasında Peygamber Efendimiz Muhammed’in (sallallahu aleyhi ve sellem) ruhuna, bedenler arasında bedenine, kabirler arasında kabrine salât eyle.","cat":"derleme","note":"Yûsuf en-Nebhânî kendi tecrübesini şöyle anlatır: “Uyumadan önce bu salavatı okuyup uyudum. Rüyamda onun mübarek yüzünü ayın içinde gördüm ve kendisine hitap ettim; sonra ayın içinde kayboldu.”","source":"Nebhânî, Efdalü’s-Salavât, 6. salavat.","arabicDraft":false},{"id":"koleksiyon10","name":"Harem ve Ramazan Duası","aliases":"","arabic":"اللَّهُمَّ رَبَّ الْحِلِّ وَالْحَرَامِ، وَرَبَّ الْبَلَدِ الْحَرَامِ، وَرَبَّ الرُّكْنِ وَالْمَقَامِ، وَرَبَّ الْمَشْعَرِ الْحَرَامِ، بِحَقِّ كُلِّ آيَةٍ أَنْزَلْتَهَا فِي شَهْرِ رَمَضَانَ، بَلِّغْ رُوحَ مُحَمَّدٍ مِنِّي تَحِيَّةً وَسَلَامًا.","latin":"Allâhümme rabbel-hilli vel-harâmi ve rabbel-beledil-harâmi ve rabber-rükni vel-makâmi ve rabbel-meş‘aril-harâm. Bi-hakkı külli âyetin enzeltehâ fî şehri Ramadân, belliğ rûha Muhammedin minnî tahiyyeten ve selâmâ.","meaning":"Allah’ım! Harem dışının ve Harem’in, mukaddes beldenin, Rükn’ün ve Makâm’ın, Meş‘ar-i Harâm’ın Rabbi! Ramazan ayında indirdiğin her âyet hürmetine Peygamber Efendimiz Muhammed’in (sallallahu aleyhi ve sellem) ruhuna benden bir hürmet ve selâm ulaştır.","cat":"derleme","note":"","source":"Ebû’ş-Şeyh, Tabakātü’l-Muhaddisîn; Makrîzî, İmtâu’l-Esmâ‘, ilgili rivayet.","source_note":" Türkçe anlam, mevcut Latin okunuş üzerinden hazırlanmıştır; özgün nüsha karşılaştırması bekleniyor.","arabicDraft":false},{"id":"koleksiyon11","name":"Seyyidinâ Muhammed ve Âlihi","aliases":"","arabic":"اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ وَعَلَى آلِهِ وَسَلِّمْ","latin":"Allâhümme salli alâ seyyidinâ Muhammedin ve alâ âlihî ve sellim.","meaning":"Allah’ım! Efendimiz Muhammed’e ve ailesine salât eyle ve selâm ver.","cat":"derleme","note":"","source":"Nebhânî, Saâdetü’d-Dâreyn, 8. bölüm, 6/14.","source_note":"| Editoryal çalışma: Latin harfli okunuş esas alınarak Arapça metin hizalandı; özgün Arapça nüshayla doğrulama bekleniyor.","arabicDraft":false},{"id":"koleksiyon14","name":"Bütün Yaratılmışların Salavatı","aliases":"","arabic":"صَلَوَاتُ اللَّهِ وَمَلَائِكَتِهِ وَأَنْبِيَائِهِ وَرُسُلِهِ وَجَمِيعِ خَلْقِهِ عَلَى سَيِّدِنَا مُحَمَّدٍ وَعَلَى آلِهِ وَعَلَيْهِ وَعَلَيْهِمُ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ","latin":"Salavâtullâhi ve melâiketihî ve enbiyâihî ve rüsülihî ve cemîi halkıhî alâ seyyidinâ Muhammedin ve alâ âlihî ve aleyhi ve aleyhimüs-selâmü ve rahmetullâhi ve berekâtüh.","meaning":"Allah’ın, meleklerinin, peygamberlerinin, elçilerinin ve bütün yaratılmışlarının salâtı Efendimiz Muhammed’e (sallallahu aleyhi ve sellem) ve ailesine olsun. Ona ve ailesine selâm, Allah’ın rahmeti ve bereketleri olsun.","cat":"derleme","note":"","source":"Nebhânî, Saâdetü’d-Dâreyn, 8. bölüm, 10: selâm lafzı.","arabicDraft":false},{"id":"koleksiyon17","name":"Şefaat-i Kübrâ","aliases":"","arabic":"اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ وَتَقَبَّلْ شَفَاعَتَهُ الْكُبْرَى وَارْفَعْ دَرَجَتَهُ الْعُلْيَا وَآتِهِ سُؤْلَهُ فِي الْآخِرَةِ وَالْأُولَى كَمَا آتَيْتَ إِبْرَاهِيمَ وَمُوسَى.","latin":"Allâhümme salli alâ seyyidinâ Muhammedin ve tekabbel şefâatehül-kübrâ verfa‘ derecetehül-ulyâ ve âtihî sü’lehû fil-âhireti vel-ûlâ kemâ âteyte İbrâhîme ve Mûsâ.","meaning":"Allah’ım! Efendimiz Muhammed’e salât eyle; onun büyük şefaatini kabul et, yüce derecesini yükselt, İbrahim’e ve Musa’ya verdiğin gibi ona da ahirette ve dünyada istediğini ver.","cat":"derleme","note":"Sehâvî, Abdullah b. Abbas’ın Peygamber Efendimize salavat getirirken, onun büyük şefaatinin kabulünü ve derecesinin yükseltilmesini dilediği, ayrıca İbrahim ve Musa peygamberlere ihsan edildiği gibi ona da dünya ve ahirette muradının verilmesini istediği sözünü aktarır. Bu, sahâbî sözü olarak nakledilir.","source":"Sehâvî, el-Kavlü’l-Bedî‘, s.122; Abd b. Humeyd, Abdürrezzâk ve İsmâil el-Kādî’ye atıf.","source_note":"| Editoryal çalışma: Latin harfli okunuş esas alınarak Arapça metin hizalandı; özgün Arapça nüshayla doğrulama bekleniyor.","arabicDraft":false},{"id":"koleksiyon19","name":"Aile, Ashap ve Ümmet","aliases":"","arabic":"اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِهِ وَأَصْحَابِهِ وَأَوْلَادِهِ وَأَزْوَاجِهِ وَذُرِّيَّتِهِ وَأَهْلِ بَيْتِهِ وَأَصْهَارِهِ وَأَنْصَارِهِ وَأَشْيَاعِهِ وَمُحِبِّيهِ وَأُمَّتِهِ وَعَلَيْنَا مَعَهُمْ أَجْمَعِينَ يَا أَرْحَمَ الرَّاحِمِينَ.","latin":"Allâhümme salli alâ Muhammedin ve alâ âlihî ve ashâbihî ve evlâdihî ve ezvâcihî ve zürriyyetihî ve ehli beytihî ve ashârihî ve ensârihî ve eşyâihî ve muhibbîhi ve ümmetihî ve aleynâ meahüm ecmaîn. Yâ Erhamer-râhimîn.","meaning":"Allah’ım! Efendimiz Muhammed’e (sallallahu aleyhi ve sellem), ailesine, ashabına, çocuklarına, eşlerine, nesline, Ehl-i Beyt’ine, hısımlarına, yardımcılarına, taraftarlarına, onu sevenlere, ümmetine ve onlarla birlikte hepimize salât eyle. Ey merhametlilerin en merhametlisi!","cat":"derleme","note":"Hasan-ı Basrî’ye nispet edilen sözde, Peygamber Efendimizin havuzundan dolu kadehle içmek isteyenin ona, âline, ashabına, çocuklarına, eşlerine, nesline, Ehl-i Beyt’ine, yakınlarına, yardımcılarına, sevenlerine ve ümmetine salât etmesi tavsiye edilir.","source":"Nebhânî, Efdalü’s-Salavât, 22.","source_note":"| Editoryal çalışma: Latin harfli okunuş esas alınarak Arapça metin hizalandı; özgün Arapça nüshayla doğrulama bekleniyor.","arabicDraft":false},{"id":"koleksiyon20","name":"Zâkirler ve Gafiller","aliases":"","arabic":"اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ كُلَّمَا ذَكَرَهُ الذَّاكِرُونَ وَغَفَلَ عَنْ ذِكْرِهِ الْغَافِلُونَ","latin":"Allâhümme salli alâ seyyidinâ Muhammedin küllemâ zekerehüzzâkirûne ve ğafele an zikrihil ğâfilûn.","meaning":"Allah’ım! Onu ananlar her andığında ve gafiller onu anmaktan her gafil kaldığında Efendimiz Muhammed’e salât eyle.","cat":"derleme","note":"","source":"Nebhânî, Saâdetü’d-Dâreyn, 8. bölüm, 5/3.","arabicDraft":false},{"id":"koleksiyon24","name":"Adede Mâ Halakte","aliases":"","arabic":"اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ وَآلِهِ عَدَدَ مَا خَلَقْتَ، اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ وَآلِهِ مِلْءَ مَا خَلَقْتَ، اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ وَآلِهِ عَدَدَ كُلِّ شَيْءٍ، اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ وَآلِهِ مِلْءَ كُلِّ شَيْءٍ، اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ وَآلِهِ عَدَدَ مَا أَحْصَى كِتَابُكَ، اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ وَآلِهِ مِلْءَ مَا أَحْصَى كِتَابُكَ، اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ وَآلِهِ عَدَدَ مَا أَحَاطَ بِهِ عِلْمُكَ، اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ وَآلِهِ مِلْءَ مَا أَحَاطَ بِهِ عِلْمُكَ.","latin":"Allâhümme salli alâ seyyidinâ Muhammedin ve âlihi adede mâ halakte, Allâhümme salli alâ seyyidinâ Muhammedin ve âlihi mil’e mâ halakte, Allâhümme salli alâ seyyidinâ Muhammedin ve âlihi adede külli şey’in, Allâhümme salli alâ seyyidinâ Muhammedin ve âlihi mil’e külli şey’in, Allâhümme salli alâ seyyidinâ Muhammedin ve âlihi adede mâ ahsâ kitâbüke, Allâhümme salli alâ seyyidinâ Muhammedin ve âlihi mil’e mâ ahsâ kitâbüke, Allâhümme salli alâ seyyidinâ Muhammedin ve âlihi adede mâ ahâta bihî ılmüke, Allâhümme salli alâ seyyidinâ Muhammedin ve âlihi mil’e mâ ahâta bihî ılmüke.","meaning":"Allah’ım! Yarattıklarının sayısınca Efendimiz Muhammed’e ve ailesine salât eyle. Yarattıklarını dolduracak kadar ona ve ailesine salât eyle. Her şeyin sayısınca salât eyle. Her şeyi dolduracak kadar salât eyle. Kitabının sayıp kaydettiklerinin sayısınca salât eyle. Kitabının sayıp kaydettiklerini dolduracak kadar salât eyle. İlminin kuşattıklarının sayısınca salât eyle. İlminin kuşattıklarını dolduracak kadar salât eyle.","cat":"derleme","note":"","source":"Bursevî, Rûhu’l-Beyân, Ahzâb 33:56; Wird: Salawāt al-Awliyā, Arapça nüsha, s. 11.","source_note":" Türkçe anlam, mevcut Latin okunuş üzerinden hazırlanmıştır; özgün nüsha karşılaştırması bekleniyor.","arabicDraft":false},{"id":"koleksiyon25","name":"Meydanil İhsân","aliases":"","arabic":"اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ مُطْلِقِ عِنَانِ الْإِيمَانِ فِي مَيْدَانِ الْإِحْسَانِ وَمُرْسِلِ رِيَاحِ الْكَرَمِ إِلَى رَوْضِ الْجِنَانِ وَعَلَى آلِ سَيِّدِنَا مُحَمَّدٍ وَسَلِّمْ.","latin":"Allâhümme salli alâ seyyidinâ Muhammedin mutlikı inânil-îmâni fî meydânil-ihsâni ve mürsili riyâhil-keremi ilâ ravdil-cinâni ve alâ âli seyyidinâ Muhammedin ve sellim.","meaning":"Allah’ım! İman atının dizginlerini ihsan meydanında serbest bırakan, kerem rüzgârlarını cennet bahçesine gönderen Efendimiz Muhammed’e (sallallahu aleyhi ve sellem) ve onun ailesine salât ve selâm eyle.","cat":"derleme","note":"","source":"Wird: Salawāt al-Awliyā, Arapça nüsha, s. 11.","arabicDraft":false},{"id":"koleksiyon31","name":"Evvelîn ve Âhirîn","aliases":"","arabic":"اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ فِي الْأَوَّلِينَ وَالْآخِرِينَ وَفِي الْمَلَإِ الْأَعْلَى إِلَى يَوْمِ الدِّينِ.","latin":"Allâhümme salli alâ Muhammedin ve alâ âli Muhammedin fil-evvelîne vel-âhirîne ve fil-meleil-a‘lâ ilâ yevmid-dîn.","meaning":"Allah’ım! Öncekiler ve sonrakiler arasında, din gününe kadar yüce toplulukta Efendimiz Muhammed’e (sallallahu aleyhi ve sellem) ve onun ailesine salât eyle.","cat":"derleme","note":"","source":"Nebhânî, Efdalü’s-Salavât, 7.","source_note":"| Editoryal çalışma: Latin harfli okunuş esas alınarak Arapça metin hizalandı; özgün Arapça nüshayla doğrulama bekleniyor.","arabicDraft":false},{"id":"koleksiyon34","name":"Kur’ân Harfleri Adedince","aliases":"","arabic":"اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ وَآلِهِ وَصَحْبِهِ وَسَلِّمْ بِعَدَدِ مَا فِي جَمِيعِ الْقُرْآنِ حَرْفًا حَرْفًا وَبِعَدَدِ كُلِّ حَرْفٍ أَلْفًا أَلْفًا.","latin":"Allâhümme salli alâ seyyidinâ Muhammedin ve âlihî ve sahbihî ve sellim bi-adedi mâ fî cemîil-Kur’âni harfen harfen ve bi-adedi külli harfin elfen elfâ.","meaning":"Allah’ım! Bütün Kur’an’da bulunan harflerin her biri sayısınca ve her harfin sayısınca binlerce bin defa Efendimiz Muhammed’e, ailesine ve ashabına salât ve selâm eyle.","cat":"derleme","note":"","source":"Bursevî, Rûhu’l-Beyân, Ahzâb 33:56.","source_note":"| Editoryal çalışma: Latin harfli okunuş esas alınarak Arapça metin hizalandı; özgün Arapça nüshayla doğrulama bekleniyor.","arabicDraft":false},{"id":"koleksiyon36","name":"Dert ve Deva Adedince","aliases":"","arabic":"اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِ مُحَمَّدٍ بِعَدَدِ كُلِّ دَاءٍ وَدَوَاءٍ.","latin":"Allâhümme salli alâ Muhammedin ve âli Muhammedin bi-adedi külli dâin ve devâ’.","meaning":"Allah’ım! Her hastalık ve her deva sayısınca Efendimiz Muhammed’e (sallallahu aleyhi ve sellem) ve onun ailesine salât eyle.","cat":"derleme","note":"","source":"Bursevî, Rûhu’l-Beyân, Ahzâb 33:56.","source_note":"| Editoryal çalışma: Latin harfli okunuş esas alınarak Arapça metin hizalandı; özgün Arapça nüshayla doğrulama bekleniyor.","arabicDraft":false},{"id":"koleksiyon42","name":"Kemâlillâh Adedince","aliases":"","arabic":"اللَّهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَى سَيِّدِنَا مُحَمَّدٍ وَعَلَى آلِهِ عَدَدَ كَمَالِ اللَّهِ وَكَمَا يَلِيقُ بِكَمَالِهِ","latin":"Allâhümme salli ve sellim ve bârik alâ seyyidinâ Muhammedin ve alâ âlihî adede kemâlillâhi ve kemâ yelîku bi-kemâlih.","meaning":"Allah’ım! Efendimiz Muhammed’e (sallallahu aleyhi ve sellem) ve ailesine, Allah’ın kemalinin sayısınca ve O’nun kemaline yaraşır şekilde salât, selâm ve bereket ihsan eyle.","cat":"derleme","note":"Ahmed es-Sâvî’nin sözünde bunun Salât-ı Kemâliye olarak meşhur olduğu, farz namazlardan sonra on defa ve başka vakitlerde yüz defa veya daha fazla okunan virdler arasında bulunduğu nakledilir.","source":"Nebhânî, Efdalü’s-Salavât, 54. salavat; Ahmed es-Sâvî’den nakil.","arabicDraft":false},{"id":"koleksiyon43","name":"Nûr-i Zâtî","aliases":"","arabic":"اللَّهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَى سَيِّدِنَا مُحَمَّدٍ النُّورِ الذَّاتِيِّ وَالسِّرِّ السَّارِي فِي سَائِرِ الْأَسْمَاءِ وَالصِّفَاتِ","latin":"Allâhümme salli ve sellim ve bârik alâ seyyidinâ Muhammedinin-nûriz-zâtiyyi ves-sirris-sârî fî sâiril-esmâi ves-sıfât.","meaning":"Allah’ım! Zâtî nur ve isimlerle sıfatlarda yayılan sır olarak anılan Efendimiz Muhammed’e salât, selâm ve bereket ihsan eyle.","cat":"derleme","note":"Ahmed el-Mellevî, bu salavatı Ebü’l-Hasan eş-Şâzelî’ye nispet eder ve yüz bin salavata denk kabul edildiğini, sıkıntıların çözülmesi için okunduğunu aktarır.","source":"Nebhânî, Efdalü’s-Salavât, 44. salavat; İbn Âbidîn’in sebeti ve Mellevî derlemesi.","arabicDraft":false},{"id":"koleksiyon45","name":"İlmullâh Adedince","aliases":"","arabic":"اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ عَدَدَ مَا فِي عِلْمِ اللَّهِ صَلَاةً دَائِمَةً بِدَوَامِ مُلْكِ اللَّهِ","latin":"Allâhümme salli alâ seyyidinâ Muhammedin adede mâ fî ilmillâhi salâten dâimeten bi-devâmi mülkillâh.","meaning":"Allah’ım! İlminde bulunanların sayısınca ve mülkünün devamı boyunca sürecek daimî bir salâtı Efendimiz Muhammed’e (sallallahu aleyhi ve sellem) ihsan eyle.","cat":"derleme","note":"Ahmed Zeynî Dahlân, bazı âriflerin bu salavatın karşılığının altı yüz bin salavat olduğunu söylediğini; her cuma bin defa okunmaya devam edilmesini tavsiye ettiklerini nakleder. Salât-ı Saâdet diye adlandırıldığını belirtir.","source":"Nebhânî, Efdalü’s-Salavât, 52. salavat; Ahmed Zeynî Dahlân’ın mecmuası.","arabicDraft":false},{"id":"koleksiyon46","name":"Muhabbet Ehlinin Salavatı","aliases":"","arabic":"اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ وَعَلَى آلِهِ صَلَاةً تَعْدِلُ جَمِيعَ صَلَوَاتِ أَهْلِ مَحَبَّتِكَ وَسَلِّمْ عَلَى سَيِّدِنَا مُحَمَّدٍ وَعَلَى آلِهِ سَلَامًا يَعْدِلُ سَلَامَهُمْ.","latin":"Allâhümme salli alâ seyyidinâ Muhammedin ve alâ âlihî salâten ta‘dilü cemîa salavâti ehli mehabbetike ve sellim alâ seyyidinâ Muhammedin ve alâ âlihî selâmen ya‘dilü selâmehüm.","meaning":"Allah’ım! Efendimiz Muhammed’e ve ailesine, Seni sevenlerin bütün salavatlarına denk bir salât eyle. Efendimiz Muhammed’e ve ailesine, onların bütün selâmlarına denk bir selâm ver.","cat":"derleme","note":"","source":"Nebhânî, Saâdetü’d-Dâreyn, 8. bölüm, 114.","source_note":"| Editoryal çalışma: Latin harfli okunuş esas alınarak Arapça metin hizalandı; özgün Arapça nüshayla doğrulama bekleniyor.","arabicDraft":false},{"id":"koleksiyon47","name":"Peygamberler ve Bağışlanma","aliases":"","arabic":"اللَّهُمَّ إِنِّي أَسْأَلُكَ بِكَ أَنْ تُصَلِّيَ عَلَى سَيِّدِنَا مُحَمَّدٍ وَعَلَى سَائِرِ الْأَنْبِيَاءِ وَالْمُرْسَلِينَ وَعَلَى آلِهِمْ وَصَحْبِهِمْ أَجْمَعِينَ وَأَنْ تَغْفِرَ لِي مَا مَضَى وَتَحْفَظَنِي فِيمَا بَقِيَ.","latin":"Allâhümme innî es’elüke bike en tusalliye alâ seyyidinâ Muhammedin ve alâ sâiril-enbiyâi vel-mürselîne ve alâ âlihim ve sahbihim ecmaîne ve en tağfira lî mâ medâ ve tahfezanî fîmâ bakiye.","meaning":"Allah’ım! Senden, kendi zatın hakkı için Efendimiz Muhammed’e, diğer bütün peygamberlere ve elçilere, onların ailelerine ve ashabının tamamına salât etmeni; geçmişte yaptıklarımı bağışlamanı ve ömrümden geriye kalanda beni korumanı diliyorum.","cat":"derleme","note":"Ahmed Zeynî Dahlân’ın aktarımına göre İbrahim el-Metbûlî bu salavat için “Hiçbir Müslümanın dilinden düşmemesini isterdim” demiştir.","source":"Nebhânî, Efdalü’s-Salavât, 41.","source_note":"| Editoryal çalışma: Latin harfli okunuş esas alınarak Arapça metin hizalandı; özgün Arapça nüshayla doğrulama bekleniyor.","arabicDraft":false},{"id":"koleksiyon48","name":"Mihrâbü’l-Ervâh","aliases":"","arabic":"اللَّهُمَّ صَلِّ عَلَى مَنْ رُوحُهُ مِحْرَابُ الْأَرْوَاحِ وَالْمَلَائِكَةِ وَالْكَوْنِ، اللَّهُمَّ صَلِّ عَلَى مَنْ هُوَ إِمَامُ الْأَنْبِيَاءِ وَالْمُرْسَلِينَ، اللَّهُمَّ صَلِّ عَلَى مَنْ هُوَ إِمَامُ أَهْلِ الْجَنَّةِ عِبَادِ اللَّهِ الْمُؤْمِنِينَ.","latin":"Allâhümme salli alâ men rûhuhû mihrâbül-ervâhi vel-melâiketi vel-kevn. Allâhümme salli alâ men hüve imâmül-enbiyâi vel-mürselîn. Allâhümme salli alâ men hüve imâmü ehlil-cenneti ibâdillâhil-mü’minîn.","meaning":"Allah’ım! Ruhu, ruhlar, melekler ve varlık âlemi için mihrap olan zata salât eyle. Allah’ım! Peygamberlerin ve elçilerin önderi olan zata salât eyle. Allah’ım! Cennet ehli mümin kullarının önderi olan zata salât eyle.","cat":"derleme","note":"","source":"Nebhânî, Saâdetü’d-Dâreyn, 8. bölüm, 11.","source_note":" Türkçe anlam, mevcut Latin okunuş üzerinden hazırlanmıştır; özgün nüsha karşılaştırması bekleniyor.","arabicDraft":false},{"id":"koleksiyon67","name":"Peygamberlerin Tamamına","aliases":"","arabic":"اللَّهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَى سَيِّدِنَا مُحَمَّدٍ وَآدَمَ وَنُوحٍ وَإِبْرَاهِيمَ وَمُوسَى وَعِيسَى وَمَا بَيْنَهُمْ مِنَ النَّبِيِّينَ وَالْمُرْسَلِينَ صَلَوَاتُ اللَّهِ وَسَلَامُهُ عَلَيْهِمْ أَجْمَعِينَ.","latin":"Allâhümme salli ve sellim ve bârik alâ seyyidinâ Muhammedin ve Âdeme ve Nûhin ve İbrâhîme ve Mûsâ ve Îsâ ve mâ beynehüm minen-nebiyyîne vel-mürselîn. Salavâtullâhi ve selâmuhû aleyhim ecmaîn.","meaning":"Allah’ım! Efendimiz Muhammed’e (sallallahu aleyhi ve sellem), Âdem’e, Nûh’a, İbrâhim’e, Mûsâ’ya, Îsâ’ya ve onların arasında bulunan peygamberlerle elçilere salât, selâm ve bereket ihsan eyle. Allah’ın salâtı ve selâmı hepsinin üzerine olsun.","cat":"derleme","note":"Delâil şârihlerinin Muhammed b. Süleyman el-Cezûlî’den aktardığına göre, bu salavatı üç defa okuyan kişinin Delâilü’l-Hayrât kitabını tamamlamış gibi olacağı nakledilir.","source":"Nebhânî, Efdalü’s-Salavât, 51.","source_note":"| Editoryal çalışma: Latin harfli okunuş esas alınarak Arapça metin hizalandı; özgün Arapça nüshayla doğrulama bekleniyor.","arabicDraft":false},{"id":"koleksiyon70","name":"Rızâ ve Hakkını Eda","aliases":"","arabic":"اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ صَلَاةً تَكُونُ لَكَ رِضَاءً وَلِحَقِّهِ أَدَاءً","latin":"Allâhümme salli alâ seyyidinâ Muhammedin salâten tekûnü leke rıdâen ve li-hakkihî edââ.","meaning":"Allah’ım! Efendimiz Muhammed’e, Senin rızana uygun ve onun hakkını yerine getiren bir salât eyle.","cat":"derleme","note":"","source":"Nebhânî, Saâdetü’d-Dâreyn, 8. bölüm, 1/37.","arabicDraft":false},{"id":"koleksiyon81","name":"Ezvâc ve Zürriyet Salavatı","aliases":"","arabic":"اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَأَزْوَاجِهِ وَذُرِّيَّتِهِ كَمَا صَلَّيْتَ عَلَى آلِ إِبْرَاهِيمَ، وَبَارِكْ عَلَى مُحَمَّدٍ وَأَزْوَاجِهِ وَذُرِّيَّتِهِ كَمَا بَارَكْتَ عَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ","latin":"Allâhümme salli alâ Muhammedin ve ezvâcihî ve zürriyyetihî kemâ salleyte alâ âli İbrâhîm. Ve bârik alâ Muhammedin ve ezvâcihî ve zürriyyetihî kemâ bârekte alâ âli İbrâhîm. İnneke hamîdün mecîd.","meaning":"Allah’ım! Peygamber Efendimize (sallallahu aleyhi ve sellem), O’nun eşlerine ve nesline, İbrâhim Aleyhisselam’ın ailesine salât ettiğin gibi salât eyle. Allah’ım! Peygamber Efendimize (sallallahu aleyhi ve sellem), O’nun eşlerine ve nesline, İbrâhim Aleyhisselam’ın ailesine bereket verdiğin gibi bereket ver. Şüphesiz Sen, övgüye layık ve şanı yüce olansın.","cat":"derleme","note":"Ebû Humeyd es-Sâidî’nin rivayetine göre sahâbîler Peygamber Efendimize “Sana nasıl salavat getirelim?” diye sorunca, kendisine, eşlerine ve nesline İbrahim ailesine salât ve bereket dilendiği gibi dua edilen lafzı öğretmiştir.","source":"Buhârî, Sahîh 3369; Müslim, Sahîh 407.","arabicDraft":false},{"id":"koleksiyon102","name":"Arş ve Kelimât Adedince","aliases":"","arabic":"اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ عَبْدِكَ وَنَبِيِّكَ وَرَسُولِكَ النَّبِيِّ الْأُمِّيِّ وَعَلَى آلِهِ وَأَزْوَاجِهِ وَذُرِّيَّتِهِ وَسَلِّمْ عَدَدَ خَلْقِكَ وَرِضَا نَفْسِكَ وَزِنَةَ عَرْشِكَ وَمِدَادَ كَلِمَاتِكَ.","latin":"Allâhümme salli alâ seyyidinâ Muhammedin abdike ve nebiyyike ve resûliken-nebiyyil-ümmiyyi ve alâ âlihî ve ezvâcihî ve zürriyyetihî ve sellim adede halkıke ve rıdâ nefsike ve zinete arşike ve midâde kelimâtik.","meaning":"Allah’ım! Kulun, peygamberin, elçin ve ümmî peygamber olan Efendimiz Muhammed’e (sallallahu aleyhi ve sellem), ailesine, eşlerine ve nesline, yarattıklarının sayısınca, rızan ölçüsünce, arşının ağırlığınca ve kelimelerinin mürekkebi miktarınca salât ve selâm eyle.","cat":"derleme","note":"Yûsuf en-Nebhânî, Sehâvî’nin Fîrûzâbâdî’den ve onun da bazı kimselerden naklettiği şu değerlendirmeyi aktarır: Peygamber Efendimize en faziletli salavatı getirmeye yemin eden kimsenin, “adede halkike ve rıdâ nefsike ve zinete arşike ve midâde kelimâtike” ifadelerini taşıyan lafzı söylemesi önerilir.","source":"Nebhânî, Efdalü’s-Salavât, 23.","arabicDraft":false},{"id":"koleksiyon108","name":"Kalbi Celâl ile Dolu","aliases":"","arabic":"اللَّهُمَّ صَلِّ وَسَلِّمْ عَلَى سَيِّدِنَا وَمَوْلَانَا مُحَمَّدٍ الَّذِي مَلَأْتَ قَلْبَهُ مِنْ جَلَالِكَ وَعَيْنَهُ مِنْ جَمَالِكَ، فَأَصْبَحَ فَرِحًا مَسْرُورًا مُؤَيَّدًا مَنْصُورًا، وَعَلَى آلِهِ وَصَحْبِهِ وَسَلِّمْ تَسْلِيمًا كَثِيرًا، وَالْحَمْدُ لِلَّهِ عَلَى ذَلِكَ.","latin":"Allâhümme salli ve sellim alâ seyyidinâ ve mevlânâ Muhammedinillezî mele’te kalbehû min celâlike ve aynehû min cemâlike fe-asbaha ferihan mesrûran müeyyeden mansûrâ. Ve alâ âlihî ve sahbihî ve sellim teslîmen kesîrâ. Vel-hamdü lillâhi alâ zâlik.","meaning":"Allah’ım! Kalbini celâlinle, gözünü cemâlinle doldurduğun; sevinçli, desteklenmiş ve yardım edilmiş kıldığın Efendimiz ve Mevlâmız Efendimiz Muhammed’e, ailesine ve ashabına bolca salât ve selam eyle. Bunun için Allah’a hamdolsun.","cat":"derleme","note":"Demîrî’nin nakline göre Ebû Abdullah İbnü’n-Nu‘mân, Peygamber Efendimizi rüyasında yüz defa görmüştür. Sonuncusunda kendisine en faziletli salavatın hangisi olduğunu sorar. Cevapta kalbinin celâl ile gözünün cemâl ile doldurulmasını anan bu salavatı okuması öğretilir.","source":"Nebhânî, Efdalü’s-Salavât, 25. salavat; Demîrî, Şerhu’l-Minhâc.","source_note":" Türkçe anlam, mevcut Latin okunuş üzerinden hazırlanmıştır; özgün nüsha karşılaştırması bekleniyor.","arabicDraft":false},{"id":"koleksiyon122","name":"Aile ve Zürriyet İçin","aliases":"","arabic":"اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ وَعَلَى آلِهِ وَأَصْحَابِهِ وَأَزْوَاجِهِ وَذُرِّيَّتِهِ وَأَهْلِ بَيْتِهِ عَدَدَ مَا فِي عِلْمِكَ، صَلَاةً دَائِمَةً بِدَوَامِ مُلْكِكَ","latin":"Allâhümme salli alâ seyyidinâ Muhammedin ve alâ âlihî ve ashâbihî ve ezvâcihî ve zürriyyetihî ve ehli beytihî adede mâ fî ilmike salâten dâimeten bi-devâmi mülkik.","meaning":"Allah’ım! İlminin içinde bulunanların sayısınca, mülkünün devamı boyunca sürecek sürekli bir salâtı Efendimiz Muhammed’e, ailesine, ashabına, eşlerine, soyuna ve Ehl-i Beyt’ine eyle.","cat":"derleme","note":"Yûsuf en-Nebhânî, Saâdetü’d-Dâreyn adlı eserinin sekizinci bölümünde bu salavata 123. salavat olarak yer verir. Nebhânî, Sağîr İbn Meyyâr’dan naklen, bir defa okunmasının Delâilü’l-Hayrât ’ı kırk defa okumaya denk olduğuna dair fazilet naklini aktarır.","source":"Yûsuf en-Nebhânî, Saâdetü’d-Dâreyn , sekizinci bölüm, 123. salavat.","source_note":"| Editoryal çalışma: Latin harfli okunuş esas alınarak Arapça metin hizalandı; özgün Arapça nüshayla doğrulama bekleniyor.","arabicDraft":false},{"id":"koleksiyon128","name":"Ukdetim Çözülsün","aliases":"","arabic":"اللَّهُمَّ صَلِّ وَسَلِّمْ عَلَى سَيِّدِنَا وَمَوْلَانَا مُحَمَّدٍ صَلَاةً تَحُلُّ بِهَا عُقْدَتِي وَتُفَرِّجُ بِهَا كُرْبَتِي وَتُنْقِذُنِي بِهَا مِنْ وَحْلَتِي وَتُقِيلُ بِهَا عَثْرَتِي وَتَقْضِي بِهَا حَاجَتِي.","latin":"Allâhümme salli ve sellim alâ seyyidinâ ve mevlânâ Muhammedin salâten tehullü bihâ ukdetî ve tüferricü bihâ kürbetî ve tünkızünî bihâ min vahletî ve tükîlü bihâ asretî ve takdî bihâ hâcetî.","meaning":"Allah’ım! Efendimiz ve Mevlâmız Muhammed’e (sallallahu aleyhi ve sellem) öyle bir salât ve selâm eyle ki onunla düğümümü çözesin, sıkıntımı gideresin, beni saplandığım bataklıktan kurtarasın, sürçmemi bağışlayasın ve ihtiyacımı karşılayasın.","cat":"derleme","note":"","source":"Nebhânî, Saâdetü’d-Dâreyn, 8. bölüm, 53.","source_note":"| Editoryal çalışma: Latin harfli okunuş esas alınarak Arapça metin hizalandı; özgün Arapça nüshayla doğrulama bekleniyor.","arabicDraft":false},{"id":"koleksiyon148","name":"Nimetler Adedince","aliases":"","arabic":"اللَّهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَى سَيِّدِنَا مُحَمَّدٍ وَعَلَى آلِهِ عَدَدَ إِنْعَامِ اللَّهِ وَإِفْضَالِهِ","latin":"Allâhümme salli ve sellim ve bârik alâ seyyidinâ Muhammedin ve alâ âlihî adede in‘âmillâhi ve ifdâlih.","meaning":"Allah’ım! Nimetlerinin ve ihsanlarının sayısınca Efendimiz Muhammed’e (sallallahu aleyhi ve sellem) ve ailesine salât, selâm ve bereket ihsan eyle.","cat":"derleme","note":"Ahmed es-Sâvî, bunun Salât-ı İn‘âm olduğunu, okuyana dünya ve ahiret nimetlerinden kapılar açıldığını ve karşılığının sayılamayacağını nakleder.","source":"Nebhânî, Efdalü’s-Salavât, 55. salavat; Ahmed es-Sâvî’den nakil.","arabicDraft":false},{"id":"koleksiyon153","name":"Ente Lehâ Ehlün","aliases":"","arabic":"اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ وَعَلَى آلِهِ صَلَاةً أَنْتَ لَهَا أَهْلٌ وَهُوَ لَهَا أَهْلٌ","latin":"Allâhümme salli alâ seyyidinâ Muhammedin ve alâ âlihî salâten ente lehâ ehlün ve hüve lehâ ehl.","meaning":"Allah’ım! Efendimiz Muhammed’e ve ailesine, Senin ihsan etmeye ve onun almaya layık olduğu bir salât eyle.","cat":"derleme","note":"İbn Âbidîn’in Şerâbâtî sebetinden aktarılan kayıtta Celâleddîn es-Süyûtî’nin, bu salavatın her okuyuşunun on bir bin salavata denk olduğunu bildirdiği nakledilir.","source":"Nebhânî, Efdalü’s-Salavât, 57. salavat; Ahmed el-Hucendî, İbn Âbidîn ve Abdülkerîm eş-Şerâbâtî sebetleri.","arabicDraft":false},{"id":"koleksiyon167","name":"Âl ve Ashâb ile Salavat","aliases":"","arabic":"اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ وَعَلَى آلِهِ وَصَحْبِهِ وَسَلِّمْ","latin":"Allâhümme salli alâ seyyidinâ Muhammedin ve alâ âlihî ve sahbihî ve sellim.","meaning":"Allah’ım! Efendimiz Muhammed’e, ailesine ve ashabına salât ve selâm eyle.","cat":"derleme","note":"","source":"Nebhânî, Saâdetü’d-Dâreyn, 8. bölüm, 6/1.","arabicDraft":false},{"id":"koleksiyon170","name":"İbrahimiyye'nin Diğer Lafzı","aliases":"","arabic":"اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ وَعَلَى آلِ سَيِّدِنَا مُحَمَّدٍ وَبَارِكْ عَلَى سَيِّدِنَا مُحَمَّدٍ وَعَلَى آلِ سَيِّدِنَا مُحَمَّدٍ كَمَا صَلَّيْتَ وَبَارَكْتَ عَلَى سَيِّدِنَا إِبْرَاهِيمَ وَعَلَى آلِ سَيِّدِنَا إِبْرَاهِيمَ فِي الْعَالَمِينَ إِنَّكَ حَمِيدٌ مَجِيدٌ","latin":"Allâhümme salli alâ seyyidinâ Muhammedin ve alâ âli seyyidinâ Muhammedin ve bârik alâ seyyidinâ Muhammedin ve alâ âli seyyidinâ Muhammedin kemâ salleyte ve bârekte alâ seyyidinâ İbrâhîme ve alâ âli seyyidinâ İbrâhîme fil-âlemîn. İnneke hamîdün mecîd.","meaning":"Allah’ım! Efendimiz Muhammed’e ve ailesine salât ve bereket eyle; âlemlerde İbrahim’e ve ailesine salât ve bereket ettiğin gibi. Şüphesiz Sen övgüye layık ve şanı yüce olansın.","cat":"derleme","note":"Kâ‘b b. Ucre rivayetinde sahâbîler Peygamber Efendimize nasıl salavat getireceklerini sorarlar. Peygamberimiz kendisine ve âline, İbrahim ve âline salât ve bereket dilenen İbrahimiyye lafzını öğretir.","source":"Nebhânî, Saâdetü’d-Dâreyn, 8. bölüm, Mellevî derlemesindeki lafız.","arabicDraft":false},{"id":"koleksiyon197","name":"Mak‘ad-ı Mukarreb ve Haşr","aliases":"","arabic":"اللَّهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَى سَيِّدِنَا وَمَوْلَانَا مُحَمَّدٍ وَأَنْزِلْهُ الْمَقْعَدَ الْمُقَرَّبَ عِنْدَكَ يَوْمَ الْقِيَامَةِ وَاحْشُرْنَا فِي زُمْرَتِهِ تَحْتَ لِوَائِهِ فِي ظِلِّ عَرْشِكَ الْمَجِيدِ إِنَّكَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ","latin":"Allâhümme salli ve sellim ve bârik alâ seyyidinâ ve mevlânâ Muhammedin ve enzilhül-mak‘adel-mukarrabe indeke yevmel-kıyâmeti vahşurnâ fî zümratihî tahte livâihî fî zılli arşikel-mecîd. İnneke alâ külli şey’in kadîr.","meaning":"Allah’ım! Efendimiz Muhammed’e salât, selâm ve bereket ihsan eyle; kıyamet günü onu katında yakın makama yerleştir. Bizi onun topluluğunda, sancağı altında ve yüce arşının gölgesinde haşret. Sen her şeye kadirsin.","cat":"derleme","note":"Rüveyfi‘ b. Sâbit el-Ensârî’den aktarılan rivayette, Peygamber Efendimize kıyamet günü katındaki yakın makama erişmesi için dua eden kişiye şefaatin gerekeceği nakledilir.","source":"Ahmed b. Hanbel, Müsned 16991; Taberânî, el-Mu‘cemü’l-Kebîr 4480; Bezzâr, Müsned 2315.","arabicDraft":false},{"id":"koleksiyon199","name":"Salâtü’l-Gavsiyye (Rahmeten Lil Âlemîn)","aliases":"Salâtü’l-Gavsiyye; es-Salâtü’l-Gavsiyye; Rahmeten Lil Âlemîn","arabic":"اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ السَّابِقِ لِلْخَلْقِ نُورُهُ وَالرَّحْمَةِ لِلْعَالَمِينَ ظُهُورُهُ، عَدَدَ مَنْ مَضَى مِنْ خَلْقِكَ وَمَنْ بَقِيَ، وَمَنْ سَعِدَ مِنْهُمْ وَمَنْ شَقِيَ، صَلَاةً تَسْتَغْرِقُ الْعَدَّ وَتُحِيطُ بِالْحَدِّ، صَلَاةً لَا غَايَةَ لَهَا وَلَا انْتِهَاءَ وَلَا انْقِضَاءَ، صَلَاةً دَائِمَةً بِدَوَامِكَ، وَعَلَى آلِهِ وَأَصْحَابِهِ، وَسَلِّمْ تَسْلِيمًا مِثْلَ ذَلِكَ.","latin":"Allâhümme salli alâ seyyidinâ Muhammedin es-sâbiki lil-halki nûruhû, ver-rahmeti lil-âlemîne zuhûruhû, adede men medâ min halkike ve men bakiye, ve men saide minhum ve men şekiye. Salâten testağrikul-adde ve tuhîtu bil-haddi, salâten lâ gâyete lehâ ve lâ intihâe ve lâ inkidâe, salâten dâimeten bi-devâmike, ve alâ âlihî ve ashâbihî, ve sellim teslîmen misle zâlik.","meaning":"Allah’ım! Nuru yaratılmışlardan önce gelen, ortaya çıkışı âlemlere rahmet olan Efendimiz Muhammed’e (sallallahu aleyhi ve sellem); yarattıklarından geçmiş ve geriye kalmış olanların, bahtiyar ve bahtsız olanların sayısınca salât eyle. Bütün sayıları içine alan ve bütün sınırları kuşatan; gayesi, sonu ve kesilmesi olmayan, Senin devamlılığınla devam eden bir salât eyle. Ailesine ve ashabına da salât eyle ve aynı ölçüde selâm ihsan eyle.","cat":"derleme","note":"Muhyiddin diye anılan Cüneyd-i Yemen’den naklen, bu salavatı sabah ve akşam onar defa okuyana Allah’ın rızası ve gazabından korunma nasip olacağı, işlerinin kolaylaşacağı anlatılır.","source":"Nebhânî, Efdalü’s-Salavât, 31. salavat; Delâil şerhi.","arabicDraft":false},{"id":"koleksiyon101","name":"Kad Dâkat Hîletî","aliases":"Orijinal liste: 101","arabic":"اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ وَعَلَى آلِ سَيِّدِنَا مُحَمَّدٍ، قَدْ ضَاقَتْ حِيلَتِي، أَدْرِكْنِي يَا رَسُولَ اللَّهِ.","latin":"Allâhümme salli alâ seyyidinâ Muhammedin ve alâ âli seyyidinâ Muhammed. Kad dâkat hîletî edriknî yâ Resûlallâh.","meaning":"Allah’ım! Efendimiz Muhammed’e ve ailesine salât eyle. Çarem daraldı; ey Allah’ın Resulü, imdadıma yetiş.","cat":"derleme","note":"Muhammed Emîn İbn Âbidîn, Şam’da büyük bir fitne çıktığında bu salavatı okuduğunu anlatır. Yaklaşık iki yüz defa tekrar ettikten sonra bir kişi gelip fitnenin sona erdiğini haber vermiştir.","source":"Nebhânî, Efdalü’s-Salavât, 58. salavat; İbn Âbidîn’in sebeti.","arabicDraft":false},{"id":"koleksiyon104","name":"Ezan Sonrası Vesîle Duası","aliases":"Orijinal liste: 104","arabic":"اللَّهُمَّ رَبَّ هَذِهِ الدَّعْوَةِ التَّامَّةِ، وَالصَّلَاةِ الْقَائِمَةِ، آتِ مُحَمَّدًا الْوَسِيلَةَ وَالْفَضِيلَةَ، وَابْعَثْهُ مَقَامًا مَحْمُودًا الَّذِي وَعَدْتَهُ.","latin":"Allâhümme rabbe hâzihid-da‘vetit-tâmmeti ves-salâtil-kâimeti, âti Muhammedenil-vesîlete vel-fazîlete, veb‘ashü makâmen mahmûdenillezî veadtehû.","meaning":"Allah’ım! Bu eksiksiz davetin ve kılınacak namazın Rabbi! Peygamber Efendimize (sallallahu aleyhi ve sellem) vesîleyi ve fazîleti ihsan eyle. Onu kendisine vadettiğin Makâm-ı Mahmûd’a eriştir.","cat":"derleme","note":"Câbir b. Abdullah (radıyallahu anh) rivayet eder: Peygamber Efendimiz (sallallahu aleyhi ve sellem), ezanı işiten kişinin bu duayı okuması hâlinde, “Kıyamet günü şefaatim ona helâl olur.” buyurmuştur. Bu dua, Peygamber Efendimizin öğrettiği şekliyle Sahîh-i Buhârî’de yer alır. Ezanın ardından okunur.","source":"Sahîh-i Buhârî, Ezan Kitabı, hadis 614 (Câbir b. Abdullah rivayeti).","arabicDraft":false},{"id":"koleksiyon114","name":"Nûrü’l-Envâr","aliases":"Orijinal liste: 114","arabic":"اللَّهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَى نُورِ الْأَنْوَارِ، وَسِرِّ الْأَسْرَارِ، وَتِرْيَاقِ الْأَغْيَارِ، وَمِفْتَاحِ بَابِ الْيَسَارِ، سَيِّدِنَا مُحَمَّدٍ الْمُخْتَارِ، وَآلِهِ الْأَطْهَارِ، وَأَصْحَابِهِ الْأَخْيَارِ، عَدَدَ نِعَمِ اللَّهِ وَإِفْضَالِهِ.","latin":"Allâhümme salli ve sellim ve bârik alâ nûril-envâri ve sirril-esrâri ve tiryâkil-ağyâri ve miftâhi bâbil-yesâri seyyidinâ Muhammedinil-muhtâri ve âlihil-athâri ve ashâbihil-ahyâri adede ni‘amillâhi ve ifdâlih.","meaning":"Allah’ım! Nurların nuru, sırların sırrı, yabancılığın devası ve kolaylık kapısının anahtarı olarak anılan seçilmiş Efendimiz Muhammed’e, tertemiz ailesine ve hayırlı ashabına, Allah’ın nimetleri ve ihsanları sayısınca salât, selâm ve bereket ihsan et.","cat":"derleme","note":"Ahmed Zeynî Dahlân, âriflerin bu salavatı ihtiyaçların karşılanması ve sıkıntıların çözülmesi için tecrübe ettiklerini; günlük virdinin yüz defa olduğunu nakleder.","source":"Ahmed Zeynî Dahlân mecmuasından nakil.","arabicDraft":false},{"id":"koleksiyon126","name":"Lâ İlâhe İllallâh Kadrince","aliases":"Orijinal liste: 126","arabic":"اللَّهُمَّ صَلِّ وَسَلِّمْ عَلَى سَيِّدِنَا مُحَمَّدٍ وَعَلَى آلِهِ قَدْرَ لَا إِلَهَ إِلَّا اللَّهُ، وَأَغْنِنَا وَاحْفَظْنَا وَوَفِّقْنَا لِمَا تَرْضَاهُ، وَاصْرِفْ عَنَّا السُّوءَ، وَارْضَ عَنِ الْحَسَنَيْنِ رَيْحَانَتَيْ خَيْرِ الْأَنَامِ وَعَنْ سَائِرِ آلِهِ وَأَصْحَابِهِ الْكِرَامِ وَأَدْخِلْنَا الْجَنَّةَ دَارَ السَّلَامِ، يَا حَيُّ يَا قَيُّومُ يَا اللَّهُ.","latin":"Allâhümme salli ve sellim alâ seyyidinâ Muhammedin ve alâ âlihî kadra lâ ilâhe illallâh. Ve ağninâ vahfaznâ ve veffiknâ limâ terdâhu vasrif annes-sûe varda anil-Haseneyni rayhânetey hayril-enâmi ve an sâiri âlihî ve ashâbihil-kirâmi ve edhılnel-cennete dâres-selâm. Yâ Hayyü yâ Kayyûmü yâ Allâh.","meaning":"Allah’ım! Lâ ilâhe illallah sözünün değeri ölçüsünde Efendimiz Muhammed’e (sallallahu aleyhi ve sellem) ve ailesine salât ve selâm eyle. Bizi ihtiyaçtan kurtar, koru, razı olduğun işlere muvaffak kıl ve kötülüğü bizden uzaklaştır. Yaratılmışların en hayırlısının iki güzel kokulu çiçeği olan Hasan ve Hüseyin’den, onun diğer bütün ailesinden ve değerli ashabından razı ol. Bizi esenlik yurdu olan cennete koy. Ey Hayy, ey Kayyûm, ey Allah!","cat":"derleme","note":"Yûsuf en-Nebhânî, bu salavatı İbn Atâullah el-İskenderî’nin Miftâhu’l-Felâh adlı eserinin son yaprağında, kitabın asıl metnine dahil olmayan bir kayıt olarak gördüğünü yazar. Oradaki notta çeşitli maksatlar için yüz ile bin arasında okunması tavsiye edilir.","source":"Nebhânî, Saâdetü’d-Dâreyn, 8. bölüm, 121.","arabicDraft":false},{"id":"koleksiyon172","name":"Kemâlin Sonsuzluğu","aliases":"Orijinal liste: 172","arabic":"اللَّهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَى سَيِّدِنَا مُحَمَّدٍ وَعَلَى آلِهِ كَمَا لَا نِهَايَةَ لِكَمَالِكَ وَعَدَدَ كَمَالِهِ.","latin":"Allâhümme salli ve sellim ve bârik alâ seyyidinâ Muhammedin ve alâ âlihî kemâ lâ nihâyete li-kemâlike ve adede kemâlih.","meaning":"Allah’ım! Efendimiz Muhammed’e (sallallahu aleyhi ve sellem) ve ailesine, Senin kemalinin sonu olmadığı gibi ve onun kemalinin sayısınca salât, selâm ve bereket ihsan eyle.","cat":"derleme","note":"Ali eş-Şebramellisî’nin ilim tahsilinde yaşadığı sıkıntı sırasında bir zattan öğrendiği salavat hakkında anlattığı menkıbedir. Zat ona salavatı akşam ile yatsı arasında belirli bir sayıya bağlamadan okumasını tavsiye eder.","source":"Nebhânî, Saâdetü’d-Dâreyn, 8. bölüm, 95.","arabicDraft":false},{"id":"koleksiyon176","name":"Habîbü’l-Âlî","aliases":"Orijinal liste: 176","arabic":"اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ النَّبِيِّ الْأُمِّيِّ الْحَبِيبِ الْعَالِي الْقَدْرِ الْعَظِيمِ الْجَاهِ، وَعَلَى آلِهِ وَصَحْبِهِ وَسَلِّمْ.","latin":"Allâhümme salli alâ seyyidinâ Muhammedinin nebiyyil ümmiyyil habîbil âlil kadril azîmil câhi ve alâ âlihî ve sahbihî ve sellim.","meaning":"Allah’ım! Ümmî peygamber, sevgili, yüce değer ve büyük makam sahibi Efendimiz Muhammed’e, ailesine ve ashabına salât ve selâm eyle.","cat":"derleme","note":"Ahmed Zeynî Dahlân, bazı âriflerden cuma geceleri okunan bu salavatın ölüm ve kabir hâliyle ilgili manevi faziletine ilişkin bir nakil aktarır.","source":"Nebhânî, Efdalü’s-Salavât, 56. salavat, Salâtü’l-Âli’l-Kadr.","arabicDraft":false},{"id":"koleksiyon18","name":"Makâm-ı Mahmûd Salavatı","aliases":"","arabic":"اللَّهُمَّ اجْعَلْ صَلَاتَكَ وَرَحْمَتَكَ وَبَرَكَاتِكَ عَلَى سَيِّدِ الْمُرْسَلِينَ، وَإِمَامِ الْمُتَّقِينَ، وَخَاتَمِ النَّبِيِّينَ، مُحَمَّدٍ عَبْدِكَ وَرَسُولِكَ، إِمَامِ الْخَيْرِ وَقَائِدِ الْخَيْرِ وَرَسُولِ الرَّحْمَةِ. اللَّهُمَّ ابْعَثْهُ مَقَامًا مَحْمُودًا يَغْبِطُهُ بِهِ الْأَوَّلُونَ وَالْآخِرُونَ. اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ. اللَّهُمَّ بَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ.","latin":"Allâhümmec‘al salâteke ve rahmeteke ve berekâtike alâ seyyidi’l-mürselîne ve imâmi’l-müttakîne ve hâtemi’n-nebiyyîne Muhammedin abdike ve resûlike, imâmi’l-hayri ve kāidi’l-hayri ve resûli’r-rahmeti. Allâhümmeb‘ashü makāmen mahmûden yağbituhû bihi’l-evvelûne ve’l-âhirûn. Allâhümme salli alâ Muhammedin ve alâ âli Muhammedin kemâ salleyte alâ İbrâhîme ve alâ âli İbrâhîme, inneke hamîdün mecîd. Allâhümme bârik alâ Muhammedin ve alâ âli Muhammedin kemâ bârekte alâ İbrâhîme ve alâ âli İbrâhîme, inneke hamîdün mecîd.","meaning":"Allah’ım! Salâtını, rahmetini ve bereketlerini peygamberlerin efendisi, takvâ sahiplerinin önderi ve peygamberlerin sonuncusu olan kulun ve elçin Peygamber Efendimiz Muhammed’e (sallallahu aleyhi ve sellem), hayrın önderine, hayra rehberlik edene ve rahmet elçisine ihsan eyle. Allah’ım! Onu, öncekilerin ve sonrakilerin gıpta edeceği Makâm-ı Mahmûd’a eriştir. Allah’ım! İbrâhim Aleyhisselam’a ve ailesine salât ettiğin gibi Peygamber Efendimize (sallallahu aleyhi ve sellem) ve ailesine de salât eyle. Şüphesiz Sen övgüye layık, şanı yüce olansın. Allah’ım! İbrâhim Aleyhisselam’a ve ailesine bereket verdiğin gibi Peygamber Efendimize (sallallahu aleyhi ve sellem) ve ailesine de bereket ver. Şüphesiz Sen övgüye layık, şanı yüce olansın.","cat":"derleme","note":"İbn Mâce’de, Esved b. Yezîd’in Abdullah b. Mes‘ûd’dan (radıyallahu anh) naklettiğine göre, İbn Mes‘ûd, Peygamber Efendimize (sallallahu aleyhi ve sellem) salavat getirirken bunu güzelce yapmayı öğütler. Kendisine nasıl salavat getirileceği sorulduğunda bu uzun duayı öğretir.","source":"İbn Mâce, Sünen , 906; Abdullah b. Mes‘ûd rivayeti.","source_note":"","arabicDraft":false,"previousArabic":"اللاهومماجال صلواتك و بركاتك و رحمتك و رافاتيكا و ماهابباتيكا على ساييديل مورسالينا و يماميل موتتاكين و كايديل غورريل موهاججالين و هاتاميننابيين سيدنا محمد عبدك و رسولك و نابييكا يماميلهايري و كايديلهايري و رسول الرحمة. اللاهومماباسهو ماكامان ماهمودان ياغبيتوهو بيهيل اووالونا وال اهيرونا. اللهم صل على سيدنا محمد و على الي سيدنا محمد كاما ساللايتا على ي̇براهيما و على الي ي̇براهيما إنك هاميدون ماجيد.","submittedArabic":"اللَّهُمَّ اجْعَلْ صَلَوَاتِكَ وَبَرَكَاتِكَ وَرَحْمَتَكَ وَرَأْفَتَكَ وَمَحَبَّتَكَ عَلَى سَيِّدِ الْمُرْسَلِينَ، وَإِمَامِ الْمُتَّقِينَ، وَقَائِدِ الْغُرِّ الْمُحَجَّلِينَ، وَخَاتَمِ النَّبِيِّينَ، سَيِّدِنَا مُحَمَّدٍ عَبْدِكَ وَرَسُولِكَ وَنَبِيِّكَ، إِمَامِ الْخَيْرِ، وَقَائِدِ الْخَيْرِ، وَرَسُولِ الرَّحْمَةِ. اللَّهُمَّ ابْعَثْهُ مَقَاماً مَحْمُوداً يَغْبِطُهُ بِهِ الأَوَّلُونَ وَالآخِرُونَ. اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ وَعَلَى آلِ سَيِّدِنَا مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ.","displayNumber":52},{"id":"koleksiyon23","name":"Vesîle ve Fazîlet","aliases":"","arabic":"اللَّهُمَّ اجْعَلْ صَلَوَاتِكَ وَبَرَكَاتِكَ وَرَحْمَتَكَ وَرَأْفَتَكَ وَمَحَبَّتَكَ عَلَى سَيِّدِ الْمُرْسَلِينَ، وَإِمَامِ الْمُتَّقِينَ، وَقَائِدِ الْغُرِّ الْمُحَجَّلِينَ، وَخَاتَمِ النَّبِيِّينَ، سَيِّدِنَا مُحَمَّدٍ عَبْدِكَ وَرَسُولِكَ وَنَبِيِّكَ، إِمَامِ الْخَيْرِ، وَقَائِدِ الْخَيْرِ، وَرَسُولِ الرَّحْمَةِ. اللَّهُمَّ ابْعَثْهُ مَقَاماً مَحْمُوداً يَغْبِطُهُ بِهِ الأَوَّلُونَ وَالآخِرُونَ. اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ وَعَلَى آلِ سَيِّدِنَا مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ.","latin":"Allâhümmec‘al salavâtike ve berekâtike ve rahmetike ve ra’fetike ve mehabbetike alâ seyyidil-mürselîne ve imâmil-müttakîne ve kâidil-ğurril-muhaccelîne ve hâtemin-nebiyyîne seyyidinâ Muhammedin abdike ve resûlike ve nebiyyike imâmil-hayri ve kâidil-hayri ve resûlir-rahmeh. Allâhümmeb‘ashü makâmen mahmûden yağbituhû bihil-evvelûne vel-âhirûn. Allâhümme salli alâ seyyidinâ Muhammedin ve alâ âli seyyidinâ Muhammedin kemâ salleyte alâ İbrâhîme ve alâ âli İbrâhîme inneke hamîdün mecîd.","meaning":"Allah’ım! Salâtlarını, bereketlerini, rahmetini, şefkatini ve sevgini; elçilerin efendisi, takvâ sahiplerinin önderi, abdest nurlarıyla yüzleri ve uzuvları parlayanların rehberi, peygamberlerin sonuncusu, kulun, elçin ve peygamberin Efendimiz Muhammed’e (sallallahu aleyhi ve sellem), hayrın önderine, hayra rehberlik edene ve rahmet elçisine ihsan eyle. Allah’ım! Onu, öncekilerin ve sonrakilerin gıpta edeceği Makâm-ı Mahmûd’a eriştir. Allah’ım! İbrâhim’e ve ailesine salât ettiğin gibi Efendimiz Muhammed’e ve ailesine salât eyle. Şüphesiz Sen övgüye layık ve şanı yüce olansın.","cat":"derleme","note":"Abdullah b. Mes‘ûd’dan, Peygamber Efendimize salavatı güzelce getirmeyi öğütleyen söz nakledilir.","source":"İbn Mâce, Sünen 906; Müslim, Sahîh, Tahâret 249a.","source_note":"","arabicDraft":false,"previousArabic":"اللهم صل على سيدنا محمد و على الي سيدنا محمد صلاة تاكونو لاكا رازاان و ليهاككاهي اداان و ااتيهيل واسيلاتا وال فازيلاتا وال ماكامال ماهموداللازي واادتاهو واجزيهي اننا افدالا ما جازايتا نابيان ان ومماتيهي و صل على جاميي يهوانيهي مينان نابيينا واسساليهينا, بيراهماتيكا يا ارهامارراهيمين.","submittedArabic":"اللَّهُمَّ اجْعَلْ صَلَوَاتِكَ وَبَرَكَاتِكَ وَرَحْمَتَكَ وَرَأْفَتَكَ وَمَحَبَّتَكَ عَلَى سَيِّدِ الْمُرْسَلِينَ، وَإِمَامِ الْمُتَّقِينَ، وَقَائِدِ الْغُرِّ الْمُحَجَّلِينَ، وَخَاتَمِ النَّبِيِّينَ، سَيِّدِنَا مُحَمَّدٍ عَبْدِكَ وَرَسُولِكَ وَنَبِيِّكَ، إِمَامِ الْخَيْرِ، وَقَائِدِ الْخَيْرِ، وَرَسُولِ الرَّحْمَةِ. اللَّهُمَّ ابْعَثْهُ مَقَاماً مَحْمُوداً يَغْبِطُهُ بِهِ الأَوَّلُونَ وَالآخِرُونَ. اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ وَعَلَى آلِ سَيِّدِنَا مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ.","displayNumber":53},{"id":"koleksiyon26","name":"Küfür ve Tuğyânın Dağılışı","aliases":"","arabic":"اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ مُفَرِّقِ فِرَقِ الْكُفْرِ وَالطُّغْيَانِ وَمُشَتِّتِ بُغَاةِ جُيُوشِ الْقَرِينِ وَالشَّيْطَانِ وَعَلَى آلِ مُحَمَّدٍ وَسَلِّمْ","latin":"Allâhümme salli alâ seyyidinâ Muhammedin müferrikı firekıl küfri vettuğyâni ve müşettiti buğâti cüyûşil karîni veşşeytâni ve alâ âli Muhammedin vesellim.","meaning":"Allah’ım! Küfür ve azgınlık topluluklarını dağıtan, karîn ve şeytan ordularının azgın saldırganlarını darmadağın eden Efendimiz Muhammed’e (sallallahu aleyhi ve sellem) ve ailesine salât ve selâm eyle.","cat":"derleme","note":"Sa‘deddin el-Hamevî’ye nispet edilen tavsiyede, şeytanın vesvesesinden, nefsin ve hevânın sıkıntısından zarar gören kimsenin bu salavata devam etmesi öğütlenir.","source":"İsmâil Hakkı Bursevî, Rûhu’l-Beyân, Ahzâb 33:56 tefsiri, c.7 s.234.","source_note":" Türkçe anlam, mevcut Latin okunuş üzerinden hazırlanmıştır; özgün nüsha karşılaştırması bekleniyor.","arabicDraft":false},{"id":"koleksiyon35","name":"Salavât-ı Melevân","aliases":"","arabic":"اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ مَا اخْتَلَفَ الْمَلَوَانِ وَتَعَاقَبَ الْعَصْرَانِ وَكَرَّ الْجَدِيدَانِ وَاسْتَقَلَّ الْفَرْقَدَانِ وَبَلِّغْ رُوحَهُ وَأَرْوَاحَ أَهْلِ بَيْتِهِ مِنَّا التَّحِيَّةَ وَالسَّلَامَ وَبَارِكْ وَسَلِّمْ عَلَيْهِ كَثِيرًا.","latin":"Allâhümme salli alâ seyyidinâ Muhammedin mahtelefel-melevâni ve teâkabel-asrâni ve kerrel-cedîdâni vestekallel-ferkadâni ve belliğ rûhahû ve ervâha ehli beytihî minnet-tahiyyete ves-selâme ve bârik ve sellim aleyhi kesîrâ.","meaning":"Allah’ım! Gece ile gündüz değişip birbirini izledikçe, iki yeni olan gece ve gündüz tekrar geldikçe, iki Ferkad yıldızı yükseldikçe Efendimiz Muhammed’e (sallallahu aleyhi ve sellem) salât eyle. Onun ruhuna ve Ehl-i Beyt’inin ruhlarına bizden hürmet ve selâm ulaştır. Ona bolca bereket ve selâm ihsan eyle.","cat":"derleme","note":"İsmâil Hakkı Bursevî’nin naklettiği rüya anlatısında borçlu biri, Peygamber Efendimizi rüyasında görür ve borcunu anlatır. Gazneli Mahmud’a gidip gecenin başında ve sonunda otuzar bin salavat okumasını söylemesi istenir. Sultan, bu kadar salavatı ne zaman okuduğu sorulunca bir lafzın tek okuyuşunun on bin salavata denk olduğunu işittiğini ve gecenin başında ve sonunda üçer defa okuduğunu anlatır.","source":"Bursevî, Rûhu’l-Beyân, Ahzâb 33:56.","source_note":"","arabicDraft":false,"previousArabic":"اللهم صل على سيدنا محمد ماهتالافال مالاواني و تااكابال اساراني و كاررارال جاديداني واستاكبالال فارغاداني و بالليغ روهاهو و ارواها اهلي بايتيهي, ميننات تاهياتا واسالام و بارك و سلم كاسيرا.","submittedArabic":"اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ مَا اخْتَلَفَ الْمَلَوَانِ وَتَعَاقَبَ الْعَصْرَانِ وَكَرَّرَ الْجَدِيدَانِ وَاسْتَقْبَلَ الْفَرْقَدَانِ وَبَلِّغْ رُوحَهُ وَاَرْوَاحَ اَهْلِ بَيْتِهِ مِنَّا التَّحِيَّةَ وَالسَّلَامَ وَبَارِكْ وَسَلِّمْ كَثِيرًا","displayNumber":55},{"id":"koleksiyon37","name":"Ağaçlar ve Yağmurlar Adedince","aliases":"","arabic":"اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ بِعَدَدِ وَرَقِ هَذِهِ الْأَشْجَارِ، وَصَلِّ عَلَى مُحَمَّدٍ بِعَدَدِ الْوَرْدِ وَالْأَنْوَارِ، وَصَلِّ عَلَى مُحَمَّدٍ بِعَدَدِ قَطْرِ الْأَمْطَارِ، وَصَلِّ عَلَى مُحَمَّدٍ بِعَدَدِ رَمْلِ الْقِفَارِ، وَصَلِّ عَلَى مُحَمَّدٍ بِعَدَدِ دَوَابِّ الْبَرَارِي وَالْبِحَارِ.","latin":"Allâhümme salli alâ Muhammedin bi-adedi varakı hâzihil-eşcâr. Ve salli alâ Muhammedin bi-adedil-verdi vel-envâr. Ve salli alâ Muhammedin bi-adedi kataril-emtâr. Ve salli alâ Muhammedin bi-adedi ramlil-kıfâr. Ve salli alâ Muhammedin bi-adedi devâbbil-berârî vel-bihâr.","meaning":"Allah’ım! Bu ağaçların yaprakları sayısınca Peygamber Efendimize (sallallahu aleyhi ve sellem) salât eyle. Güller ve çiçekler sayısınca Peygamber Efendimize (sallallahu aleyhi ve sellem) salât eyle. Yağmur damlaları sayısınca Peygamber Efendimize (sallallahu aleyhi ve sellem) salât eyle. Issız çöllerin kumları sayısınca Peygamber Efendimize (sallallahu aleyhi ve sellem) salât eyle. Karalarda ve denizlerde bulunan canlılar sayısınca Peygamber Efendimize (sallallahu aleyhi ve sellem) salât eyle.","cat":"derleme","note":"","source":"Bursevî, Rûhu’l-Beyân, Ahzâb 33:56.","source_note":" Türkçe anlam, mevcut Latin okunuş üzerinden hazırlanmıştır; özgün nüsha karşılaştırması bekleniyor.","arabicDraft":false},{"id":"koleksiyon52","name":"İhlâs Mertebeleri","aliases":"","arabic":"اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ عَبْدِكَ وَرَسُولِكَ وَخَلِيلِكَ وَحَبِيبِكَ صَلَاةً أَرْقَى بِهَا مَرَاقِيَ الْإِخْلَاصِ وَأَنَالُ بِهَا غَايَةَ الِاخْتِصَاصِ وَسَلِّمْ تَسْلِيمًا عَدَدَ مَا أَحَاطَ بِهِ عِلْمُكَ وَأَحْصَاهُ كِتَابُكَ كُلَّمَا ذَكَرَكَ الذَّاكِرُونَ وَغَفَلَ عَنْ ذِكْرِهِ الْغَافِلُونَ","latin":"Allâhümme salli alâ seyyidinâ Muhammedin abdike ve resûlike ve halîlike ve habîbike salâten erkâ bihâ merâkıyel-ihlâsi ve enâlü bihâ gâyetel-ihtisâsi ve sellim teslîmen adede mâ ehâta bihî ilmüke ve ahsâhü kitâbüke küllemâ zekerakez-zâkirûne ve ğafele an zikrihil-ğâfilûn.","meaning":"Allah’ım! Kulun, elçin, dostun ve sevgilin Efendimiz Muhammed’e (sallallahu aleyhi ve sellem), vesilesiyle ihlâs basamaklarına yükseleceğim ve hususi yakınlığın son gayesine erişeceğim bir salât eyle. İlminin kuşattığı ve kitabının kaydettiği şeylerin sayısınca; Seni ananlar her andığında ve gafiller onu anmaktan her gafil kaldığında ona selâm ihsan eyle.","cat":"derleme","note":"","source":"Nebhânî, Saâdetü’d-Dâreyn, 8. bölüm, 22.","source_note":" Türkçe anlam, mevcut Latin okunuş üzerinden hazırlanmıştır; özgün nüsha karşılaştırması bekleniyor.","arabicDraft":false},{"id":"koleksiyon71","name":"Şiddette Yardım Duası","aliases":"","arabic":"اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ وَاٰلِهِ وَصَحْبِهِ وَسَلِّمْ. يَا عِدَّتِي عِنْدَ شِدَّتِي. وَيَا غَوْثِي عِنْدَ كُرْبَتِي. وَيَا حَارِسِي عِنْدَ كُلِّ مُصِيبَتِي. وَيَا حَافِظِي عِنْدَ كُلِّ بَلِيَّتِي. وَصَلِّ عَلٰى مُحَمَّدٍ وَاٰلِهِ وَعَلٰى جَمِيعِ الْمُرْسَلِينَ. وَالْحَمْدُ لِلهِ رَبِّ الْعَالَمِينَ.","latin":"Allâhümme salli alâ seyyidinâ Muhammedin ve âlihî ve sahbihî ve sellim. Yâ iddetî inde şiddetî ve yâ ğavsî inde kürbetî ve yâ hârisî inde külli musîbetî ve yâ hâfizî inde külli beliyyetî ve salli alâ Muhammedin ve âlihî ve alâ cemîil-mürselîn. Vel-hamdü lillâhi Rabbil-âlemîn.","meaning":"Allah’ım! Efendimiz Muhammed’e, ailesine ve ashabına salât ve selam eyle. Ey sıkıntı anında dayanağım, darlıkta yardımcım, her musibette koruyucum ve her belada muhafızım! Efendimiz Muhammed’e, ailesine ve bütün elçilere salât eyle. Hamd âlemlerin Rabbi Allah’adır.","cat":"derleme","note":"Salavat-ı İstigâse veya Kurbet ve Şiddet Salavatı adıyla, darlık ve sıkıntıda okunan bir vird olarak tanıtılmıştır. İmam Şâzelî ve tasavvuf büyüklerine nispet edilen yorumda, “Yâ iddetî inde şiddetî” sözü kulun Allah’ı sıkıntıda dayanak bilmesini; “Yâ gavsî inde kürbetî” ise darlıkta O’ndan yardım istemesini ifade eder. Dünyevi dayanaklardan ziyade sebepleri yaratan Allah’a yöneliş ve teslimiyet vurgulanır.","source":"","source_note":"","arabicDraft":false,"previousArabic":"اللهم صل على سيدنا محمد و آله و صحبه و سلم. يا يدداتي اندا شيدداتي. وايا غاوسي اندا كورباتي. و يا هاريسي اندا كل موسيباتي. و يا هافيزي اندا كل بالياتي. و صل على محمد و آله و على جامي-ال مورساليين. وال هامدوليللاهي رب الاميين.","submittedArabic":"اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ وَاٰلِهِ وَصَحْبِهِ وَسَلِّمْ. يَا عِدَّتِي عِنْدَ شِدَّتِي. وَيَا غَوْثِي عِنْدَ كُرْبَتِي. وَيَا حَارِسِي عِنْدَ كُلِّ مُصِيبَتِي. وَيَا حَافِظِي عِنْدَ كُلِّ بَلِيَّتِي. وَصَلِّ عَلٰى مُحَمَّدٍ وَاٰلِهِ وَعَلٰى جَمِيعِ الْمُرْسَلِينَ. وَالْحَمْدُ لِلهِ رَبِّ الْعَالَمِينَ.","displayNumber":58},{"id":"koleksiyon76","name":"Bahri Envâr","aliases":"","arabic":"اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ بَحْرِ اَنْوَارِكَ وَمَعْدِنِ اَسْرَارِكَ وَلِسَانِ حُجَّتِكَ وَعَرُوسِ مَمْلَكَتِكَ وَاِمَامِ حَضْرَتِكَ وَطِرَازِ مُلْكِكَ وَخَزَائِنِ رَحْمَتِكَ وَطَرِيقِ شَرِيعَتِكَ الْمُتَلَذِّذِ بِتَوْحِيدِكَ اِنْسَانِ عَيْنِ الْوُجُودِ وَالسَّبَبِ فِي كُلِّ مَوْجُودٍ عَيْنِ اَعْيَانِ خَلْقِكَ الْمُتَقَدِّمِ مِنْ نُورِ ضِيَائِكَ. صَلَاةً تَدُومُ بِدَوَامِكَ وَتَبْقٰى بِبَقَائِكَ لَا مُنْتَهٰى لَهَا دُونَ عِلْمِكَ صَلَاةً تُرْضِيكَ وَتُرْضِيهِ وَتَرْضٰى بِهَا عَنَّا يَا رَبَّ الْعَالَمِينَ.","latin":"Allâhümme salli alâ seyyidinâ Muhammedin bahri envârike ve ma‘dini esrârike ve lisâni huccetike ve arûsi memleketike ve imâmi hadratike ve tırâzi mülkike ve hazâini rahmetike ve tarîkı şerîatikel-mütelezzizi bi-tevhîdike insâni aynil-vücûdi ves-sebebi fî külli mevcûdin ayni a‘yâni halkıkel-mütekaddimi min nûri dıyâik. Salâten tedûmü bi-devâmike ve tebkâ bi-bekâike lâ müntehâ lehâ dûne ilmike salâten turdîke ve turdîhi ve terdâ bihâ annâ yâ Rabbel-âlemîn.","meaning":"Allah’ım! Nurlarının denizi, sırlarının madeni, delilinin dili, mülkünün gelini ve süsü, huzurunun imamı, saltanatının ziyneti, rahmetinin hazineleri, şeriatının yolu; Senin birliğini müşahede etmekten haz duyan, varlık gözünün göz bebeği, her var olanın sebebi, yarattıklarının özünün özü ve aydınlığının nurundan önce gelmiş olan Efendimiz Muhammed’e (sallallahu aleyhi ve sellem) salât eyle. Senin devamlılığınla devam eden, Senin bekânla bâki kalan ve sonunu ancak Senin ilminin kuşattığı bir salât olsun. Seni ve onu razı eden, vesilesiyle bizden de razı olacağın bir salât eyle, ey âlemlerin Rabbi!","cat":"derleme","note":"Ahmed es-Sâvî’den aktarıldığına göre bu salavat Salât-ı Nûr-i Kıyâme diye adlandırılır; bir taş üzerine yazıldığı ve Delâil şerhlerinde on dört bin salavata denk olduğunun nakledildiği anlatılır.","source":"Nebhânî, Efdalü’s-Salavât, 27. salavat; Ahmed es-Sâvî ve Delâil şerhi.","source_note":"","arabicDraft":false,"previousArabic":"اللهم صل على سيدنا محمد باهري انواريكا و ماديني اسرااريكا و ليساني هوججاتيكا و ارووسي ماملاكاتيكا و يمامي هازراتيكا و تاراازي ملكك و هازايني رحمتك و تارايكا شاريياتيكال موتالاززيزي ب تاوهايديكا ينساني اينيل ووجوودي واسابابي فيي كل ماوجوودين ايني اياني هالكاكال موتاكادديمي من نور زايايكا. صلاة تادوومو ب داواميكا و تابكا ب باكايكا لا مونتاها لاها دونا علمك صلاة تورزايكا و تورزايهي و تارزا بيها اننا يا راببال الاميين.","submittedArabic":"اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ بَحْرِ اَنْوَارِكَ وَمَعْدِنِ اَسْرَارِكَ وَلِسَانِ حُجَّتِكَ وَعَرُوسِ مَمْلَكَتِكَ وَاِمَامِ حَضْرَتِكَ وَطِرَازِ مُلْكِكَ وَخَزَائِنِ رَحْمَتِكَ وَطَرِيقِ شَرِيعَتِكَ الْمُتَلَذِّذِ بِتَوْحِيدِكَ اِنْسَانِ عَيْنِ الْوُجُودِ وَالسَّبَبِ فِي كُلِّ مَوْجُودٍ عَيْنِ اَعْيَانِ خَلْقِكَ الْمُتَقَدِّمِ مِنْ نُورِ ضِيَائِكَ. صَلَاةً تَدُومُ بِدَوَامِكَ وَتَبْقٰى بِبَقَائِكَ لَا مُنْتَهٰى لَهَا دُونَ عِلْمِكَ صَلَاةً تُرْضِيكَ وَتُرْضِيهِ وَتَرْضٰى بِهَا عَنَّا يَا رَبَّ الْعَالَمِينَ.","displayNumber":59},{"id":"koleksiyon115","name":"Vesîle ve Makâm-ı Mahmûd","aliases":"","arabic":"اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلٰى سَيِّدِنَا وَمَوْلَانَا مُحَمَّدٍ وَعَلٰى اٰلِهِ وَصَحْبِهِ وَاَهْلِ بَيْتِهِ صَلَاةً تَكُونُ لَكَ رِضَاءً وَلِحَقِّهِ اَدَاءً وَاٰتِهِ الْوَسِيلَةَ وَابْعَثْهُ الْمَقَامَ الْمَحْمُودَ الَّذِي وَعَدْتَهُ وَاجْزِهِ عَنَّا مَا هُوَ اَهْلُهُ وَاجْزِهِ اَفْضَلَ مَا جَزَيْتَ نَبِيًّا عَنْ اُمَّتِهِ وَصَلِّ عَلَيْهِ وَعَلٰى جَمِيعِ اِخْوَانِهِ مِنَ النَّبِيِّينَ وَالْمُرْسَلِينَ وَعَلٰى اٰلِهِمْ وَصَحْبِهِمْ اَجْمَعِينَ يَا اَرْحَمَ الرَّاحِمِينَ.","latin":"Allâhümme salli ve sellim ve bârik alâ seyyidinâ ve mevlânâ Muhammedin ve alâ âlihî ve sahbihî ve ehli beytihî salâten tekûnü leke rıdâen ve li-hakkihî edââ. Ve âtihil-vesîlete veb‘ashül-makâmel-mahmûdellezî veadtehû veczihi annâ mâ hüve ehlühû veczihi efdale mâ cezeyte nebiyyen an ümmetihî ve salli aleyhi ve alâ cemîi ihvânihî minen-nebiyyîne vel-mürselîne ve alâ âlihim ve sahbihim ecmaîn. Yâ Erhamer-râhimîn.","meaning":"Allah’ım! Efendimiz ve Mevlâmız Muhammed’e (sallallahu aleyhi ve sellem), ailesine, ashabına ve Ehl-i Beyt’ine, Senin rızana uygun ve onun hakkını eda eden bir salât, selâm ve bereket ihsan eyle. Ona vesîleyi ver ve onu vadettiğin Makâm-ı Mahmûd’a eriştir. Onu bizim adımıza kendisinin layık olduğu şekilde mükâfatlandır; bir peygamberi ümmeti adına mükâfatlandırdığın en üstün karşılıkla mükâfatlandır. Ona, peygamberlerden ve elçilerden olan bütün kardeşlerine, onların ailelerine ve ashabının tamamına salât eyle. Ey merhametlilerin en merhametlisi!","cat":"derleme","note":"İmam Gazzâlî, cuma âdâbı bahsinde bu lafzı aktardıktan sonra, yedi cuma boyunca her cuma yedi defa okuyana şefaatin gerekeceğinin söylendiğini nakleder.","source":"Gazzâlî, İhyâü Ulûmi’d-Dîn, cuma âdâbı; Nebhânî, Efdalü’s-Salavât, 21. salavat.","source_note":"","arabicDraft":false,"previousArabic":"اللهم صل و سلم و بارك على سيدنا و ماولانا محمد و على آله و صحبه و اهلي بايتيهي صلاة تاكونو لاكا ريداان و ليهاككيهي اداان و اتيهيل واسيلاتا واباسهول ماكامال ماهموداللازي واادتاهو و اجزيهي اننا ماهووا اهلوهو و اجزيهي افدالا ما جازايتا نابيان ان ومماتيهي و صل الايهي و على جامي يهوانيهي ميناننابيينا وال مورسالين و على اليهيم و ساهبيهيم اجماين يا ارهامارراهيمين.","submittedArabic":"اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلٰى سَيِّدِنَا وَمَوْلَانَا مُحَمَّدٍ وَعَلٰى اٰلِهِ وَصَحْبِهِ وَاَهْلِ بَيْتِهِ صَلَاةً تَكُونُ لَكَ رِضَاءً وَلِحَقِّهِ اَدَاءً وَاٰتِهِ الْوَسِيلَةَ وَابْعَثْهُ الْمَقَامَ الْمَحْمُودَ الَّذِي وَعَدْتَهُ وَاجْزِهِ عَنَّا مَا هُوَ اَهْلُهُ وَاجْزِهِ اَفْضَلَ مَا جَزَيْتَ نَبِيًّا عَنْ اُمَّتِهِ وَصَلِّ عَلَيْهِ وَعَلٰى جَمِيعِ اِخْوَانِهِ مِنَ النَّبِيِّينَ وَالْمُرْسَلِينَ وَعَلٰى اٰلِهِمْ وَصَحْبِهِمْ اَجْمَعِينَ يَا اَرْحَمَ الرَّاحِمِينَ.","displayNumber":60},{"id":"koleksiyon118","name":"Salavât-ı Azîmiyye","aliases":"","arabic":"اَللّٰهُمَّ اِنِّي اَسْأَلُكَ بِنُورِ وَجْهِ اللهِ الْعَظِيمِ الَّذِي مَلَاَ اَرْكَانَ عَرْشِ اللهِ الْعَظِيمِ وَقَامَتْ بِهِ عَوَالِمُ اللهِ الْعَظِيمِ اَنْ تُصَلِّيَ عَلٰى مَوْلَانَا مُحَمَّدٍ ذِي الْقَدْرِ الْعَظِيمِ وَعَلٰى اٰلِ نَبِيِّ اللهِ الْعَظِيمِ بِقَدْرِ عَظَمَةِ ذَاتِ اللهِ الْعَظِيمِ فِي كُلِّ لَمْحَةٍ وَنَفَسٍ عَدَدَ مَا فِي عِلْمِ اللهِ الْعَظِيمِ صَلَاةً كَامِلَةً دَائِمَةً بِدَوَامِ اللّٰهِ الْعَظِيمِ تَعْظِيمًا لِحَقِّكَ يَا مَوْلَانَا يَا مُحَمَّدُ يَا ذَا الْخُلُقِ الْعَظِيمِ وَسَلِّمْ عَلَيْهِ وَعَلٰى اٰلِهِ وَصَحْبِهِ مِثْلَ ذٰلِكَ وَاجْمَعْ بَيْنِي وَبَيْنَهُ كَمَا جَمَعْتَ بَيْنَ الرُّوحِ وَالنَّفْسِ ظَاهِرًا وَبَاطِنًا يَقَظَةً وَمَنَامًا وَاجْعَلْهُ يَا رَبِّ رُوحًا لِذَاتِي مِنْ جَمِيعِ الْوُجُوهِ فِي الدُّنْيَا قَبْلَ الْاٰخِرَةِ يَا عَظِيمُ يَا اَللّٰهُ.","latin":"Allâhümme innî es’elüke bi-nûri vechillâhil-azîmillezî mele’e erkâne arşillâhil-azîmi ve kâmet bihî avâlimullâhil-azîmi en tusalliye alâ mevlânâ Muhammedin zil-kadril-azîmi ve alâ âli nebiyyillâhil-azîmi bi-kadri azameti zâtillâhil-azîm. Fî külli lemhatin ve nefesin adede mâ fî ilmillâhil-azîmi salâten kâmileten dâimeten bi-devâmillâhil-azîm. Ta‘zîmen li-hakkike yâ mevlânâ yâ Muhammedü yâ zel-hulukil-azîm. Ve sellim aleyhi ve alâ âlihî ve sahbihî misle zâlike vecma‘ beynî ve beynehû kemâ cema‘te beyn er-rûhi ven-nefsi zâhiran ve bâtinen yakazaten ve menâmâ. Vec‘alhü yâ Rabbi rûhan li-zâtî min cemîil-vücûhi fid-dünyâ kablel-âhirah. Yâ Azîmü yâ Allâh.","meaning":"Allah’ım! Yüce Allah’ın arşının bütün yönlerini dolduran ve yüce Allah’ın âlemlerinin kendisiyle ayakta durduğu, yüce Allah’ın vechinin nuru hürmetine Senden diliyorum: Büyük değer sahibi Mevlâmız Muhammed’e (sallallahu aleyhi ve sellem) ve yüce Allah’ın peygamberinin ailesine, yüce Allah’ın zâtının azameti ölçüsünde, her bakışta ve her nefeste, yüce Allah’ın ilminde bulunanların sayısınca, yüce Allah’ın devamlılığıyla devam eden eksiksiz bir salât eyle. Ey Mevlâmız, ey Muhammed, ey büyük ahlâk sahibi! Bu, senin hakkını yüceltmek içindir. Ona, ailesine ve ashabına aynı ölçüde selâm ihsan eyle. Ruh ile nefsi bir araya getirdiğin gibi, beni de onunla açıkta ve gizlide, uyanıklıkta ve uykuda bir araya getir. Ey Rabbim! Âhiretten önce dünyada, bütün yönlerden onu benim varlığımın ruhu kıl. Ey azamet sahibi Allah’ım!","cat":"derleme","note":"Ahmed İbn İdrîs, Peygamber Efendimizle sûret üzere bir buluşmada Hızır’ın da bulunduğunu, Peygamberimizin Hızır’a kendisine Şâzeliyye evradını öğretmesini emrettiğini, onun da öğrettiğini nakleder.","source":"Nebhânî, Efdalü’s-Salavât, Ahmed İbn İdrîs’in 64–69. salavatlarının ardından gelen açıklama.","source_note":"","arabicDraft":false,"previousArabic":"اللهم ينني اسالوكا بينوري واجهيللاهيل ازيميللازي مالاا اركانا ارشيللاهيل ازيم و كامات بيهي اواليموللاهيل ازيم ان توساللييا على ماولانا محمد زيل كادريل ازيم و على ال-ي ناببيييللاهيل ازيم ب كاداري ازاماتي زاتيللاهيل ازيم في كل لامهاتين و نافاسين عدد ما في يلميللاهيل ازيم صلاة كاميلاتان دايماتان ب داواميللاهيل ازيم تازيمان ليهاككيكا يا ماولانا يا موهاممادو يا زال هولوكيل ازيم و سلم الايهي و على آله و صحبه ميسلا زاليكا اللاهومماجما بايني و بايناهو كاما جاماتا باينارروهي واننافاسي زاهيران و باتينان ياكازاتان و مانامان واجالهو يا ربي روهان ليزاتي من جاميل واجوهي فيددونيا كابلال اهراتي يا ازيمو يا الله.","submittedArabic":"اَللّٰهُمَّ اِنِّي اَسْأَلُكَ بِنُورِ وَجْهِ اللهِ الْعَظِيمِ الَّذِي مَلَاَ اَرْكَانَ عَرْشِ اللهِ الْعَظِيمِ وَقَامَتْ بِهِ عَوَالِمُ اللهِ الْعَظِيمِ اَنْ تُصَلِّيَ عَلٰى مَوْلَانَا مُحَمَّدٍ ذِي الْقَدْرِ الْعَظِيمِ وَعَلٰى اٰلِ نَبِيِّ اللهِ الْعَظِيمِ بِقَدَرِ عَظَمَةِ ذَاتِ اللهِ الْعَظِيمِ فِي كُلِّ لَمْحَةٍ وَنَفَسٍ عَدَدَ مَا فِي عِلْمِ اللهِ الْعَظِيمِ صَلَاةً كَامِلَةً دَائِمَةً بِدَوَامِ الله{الْعَظِيمِ} تَعْظِيمًا لِحَقِّكَ يَا مَوْلَانَا يَا مُحَمَّدُ يَا ذَا الْخُلُقِ الْعَظِيمِ وَسَلِّمْ عَلَيْهِ وَعَلٰى اٰلِهِ وَصَحْبِهِ مِثْلَ ذٰلِكَ وَاجْمَعْ بَيْنِي وَبَيْنَهُ كَمَا جَمَعْتَ بَيْنَ الرُّوحِ وَالنَّفَسِ ظَاهِرًا وَبَاطِنًا يَقَظَةً وَمَنَامًا وَاجْعَلْهُ يَا رَبِّ رُوحًا لِذَاتِي مِنْ جَمِيعِ الْوُجُوهِ فِي الدُّنْيَا قَبْلَ الْاٰخِرَةِ يَا عَظِيمُ يَا اَللّٰهُ.","displayNumber":8},{"id":"koleksiyon152","name":"Sâbık-ı Nûr","aliases":"","arabic":"اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ السَّابِقِ لِلْخَلْقِ نُورُهُ وَرَحْمَةٌ لِلْعَالَمِينَ ظُهُورُهُ عَدَدَ مَنْ مَضَى مِنْ خَلْقِكَ وَمَنْ بَقِيَ وَمَنْ سَعِدَ مِنْهُمْ وَمَنْ شَقِيَ صَلَاةً تَسْتَغْرِقُ الْعَدَّ وَتُحِيطُ بِالْحَدِّ صَلَاةً لَا غَايَةَ لَهَا وَلَا مُنْتَهَى وَلَا انْقِضَاءَ صَلَاةً دَائِمَةً بِدَوَامِكَ وَعَلَى آلِهِ وَصَحْبِهِ وَسَلِّمْ تَسْلِيمًا مِثْلَ ذَلِكَ","latin":"Allâhümme salli alâ seyyidinâ Muhammedinis-sâbikı lil-halkı nûruhû ve rahmetün lil-âlemîne zuhûruhû adede men medâ min halkıke ve men bakiye ve men saide minhüm ve men şekıye. Salâten testağrikul-adde ve tuhîtu bil-haddi salâten lâ gâyete lehâ ve lâ müntehâ ve lâ inkıdâe salâten dâimeten bi-devâmike ve alâ âlihî ve sahbihî ve sellim teslîmen misle zâlik.","meaning":"Allah’ım! Nuru yaratılmışlardan önce gelen ve ortaya çıkışı âlemlere rahmet olan Efendimiz Muhammed’e (sallallahu aleyhi ve sellem); yarattıklarından geçmiş ve geriye kalmış olanların, bahtiyar ve bahtsız olanların sayısınca salât eyle. Sayıyı içine alan ve sınırı kuşatan; son gayesi, bitişi ve kesilmesi olmayan, Senin devamlılığınla devam eden bir salât olsun. Ailesine ve ashabına da salât eyle ve aynı ölçüde selâm ihsan eyle.","cat":"derleme","note":"Muhyiddin, “Cüneyd-i Yemen” diye bilinen zattan naklen bu salavatın sabah ve akşam onar defa okunmasının manevi faydaları hakkında söz aktarır.","source":"Nebhânî, Efdalü’s-Salavât, 31.","source_note":" Türkçe anlam, mevcut Latin okunuş üzerinden hazırlanmıştır; özgün nüsha karşılaştırması bekleniyor.","arabicDraft":false},{"id":"koleksiyon13","name":"Lebbeyk Salavatı","aliases":"Orijinal liste: 13","arabic":"لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ وَسَعْدَيْكَ، صَلَوَاتُ اللَّهِ الْبَرِّ الرَّحِيمِ وَالْمَلَائِكَةِ الْمُقَرَّبِينَ وَالنَّبِيِّينَ وَالصِّدِّيقِينَ وَالشُّهَدَاءِ وَالصَّالِحِينَ وَمَا سَبَّحَ لَكَ مِنْ شَيْءٍ يَا رَبَّ الْعَالَمِينَ عَلَى مُحَمَّدِ بْنِ عَبْدِ اللَّهِ خَاتَمِ النَّبِيِّينَ وَسَيِّدِ الْمُرْسَلِينَ وَإِمَامِ الْمُتَّقِينَ وَرَسُولِ رَبِّ الْعَالَمِينَ الشَّاهِدِ الْبَشِيرِ الدَّاعِي إِلَيْكَ بِإِذْنِكَ الصِّرَاطِ الْمُسْتَقِيمِ السِّرَاجِ الْمُنِيرِ وَعَلَيْهِ السَّلَامُ.","latin":"Lebbeyk Allâhümme lebbeyke ve sa‘deyk. Salavâtüllâhil-berrir-rahîmi vel-melâiketil-mukarrabîne ven-nebiyyîne ves-sıddîkîne veş-şühedâi ves-sâlihîne ve mâ sebbeha leke min şey’in yâ Rabbel-âlemîn, alâ Muhammedibni Abdillâhi hâtemin-nebiyyîne ve seyyidil-mürselîne ve imâmil-müttakîne ve resûli Rabbil-âlemîne, eş-şâhidil-beşîri’d-dâî ileyke bi-iznike, es-sırâtıl-müstakîmi’s-sirâcil-münîr. Ve aleyhis-selâm.","meaning":"Buyur Allah’ım, emrine amadeyim! Buyur Allah’ım, emrine amadeyim ve Sana itaat ederim! Ey âlemlerin Rabbi! İyilik sahibi ve merhametli olan Allah’ın; Allah’a yakın meleklerin, peygamberlerin, sıddıkların, şehitlerin, salihlerin ve Seni tesbih eden bütün varlıkların salâtı; Abdullah’ın oğlu, peygamberlerin sonuncusu, elçilerin efendisi, takva sahiplerinin önderi ve âlemlerin Rabbinin elçisi olan Peygamber Efendimiz Muhammed’in (sallallahu aleyhi ve sellem) üzerine olsun. O, şahitlik eden, müjdeleyen, Senin izninle Sana davet eden, dosdoğru yolu gösteren ve aydınlatıcı bir kandil olan Peygamber Efendimizdir. Selâm da O’nun üzerine olsun.","cat":"derleme","note":"Yûsuf en-Nebhânî’nin Saâdetü’d-Dâreyn adlı eserinde, Ahzâb sûresinin 56. âyetinin ardından “Lebbeyk Allâhümme…” diye başlayan uzun salavat dizisi içerisinde yer alır. Eserde her gün üç, cuma günü yüz defa okunacağı kaydedilir.","source":"Yûsuf en-Nebhânî, Saâdetü’d-Dâreyn, ilgili Lebbeyk salavatı bölümü.","arabicDraft":false,"previousArabic":"بيسميللاهيرراهمانيرراهيم. ي̇نناللاها و مالايكاتاهو يوساللونا الاننابيي; يا ايوهاللازينا امانو ساللو الايهي و سالليمو تاسليما. لاببايك اللهم و سادايك سالاواتوللاهيل باررير راهيم, والمالايكاتيل موكاررابين, واننابيين واسادديكين واشوهاداي واساليهين. واما سابباها لاكا شايون يا راببال العالمين على سيدنا محمد يبن ابديللاه, هاتاميننابيين و ساييديل مورسالين و يماميل موتتاكين و راسولي رب العالمين, اشاهيديل باشيريد داي يلايكا بييزنيكا اسيراجيل مونير, و الايهيسالام و ايمماتي اهلي بايتيهي رادوانوللاهي الايهيم أجمعين.","submittedArabic":"بِسْمِ اللّٰهِ الرَّحْمٰنِ الرَّحِيمِ. اِنَّ اللّٰهَ وَمَلَائِكَتَهُ يُصَلُّونَ عَلَى النَّبِيِّ يَا اَيُّهَا الَّذِينَ اٰمَنُوا صَلُّوا عَلَيْهِ وَسَلِّمُوا تَسْلِيمًا. لَبَّيْكَ اَللّٰهُمَّ وَسَعْدَيْكَ صَلَوَاتُ اللّٰهِ الْبَرِّ الرَّحِيمِ وَالْمَلَائِكَتِ الْمُقَرَّبِينَ وَالنَّبِيِّينَ وَالصِّدِّيقِينَ وَالشُّهَدَاءِ وَالصَّالِحِينَ وَمَا سَبَّحَ لَكَ مِنْ شَيْءٍ يَا رَبَّ الْعَالَمِينَ عَلٰى سَيِّدِنَا مُحَمَّدِ بْنِ عَبْدِ اللّٰهِ خَاتَمِ النَّبِيِّينَ وَسَيِّدِ الْمُرْسَلِينَ وَاِمَامِ الْمُتَّقِينَ وَرَسُولِ رَبِّ الْعَالَمِينَ الشَّاهِدِ الْبَشِيرِ الدَّاعِي اِلَيْكَ بِاِذْنِكَ السِّرَاجِ الْمُنِيرِ وَعَلَيْهِ السَّلَامُ وَاَئِمَّةِ اَهْلِ بَيْتِهِ رِضْوَانُ اللّٰهِ عَلَيْهِمْ اَجْمَعِينَ.","source_note":"","displayNumber":62},{"id":"koleksiyon28","name":"Kıyamet Arasâtı Salavatı","aliases":"Orijinal liste: 28","arabic":"اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ فِي عَرَصَاتِ الْقِيَامَةِ. اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ حِينَ تَقُومُ السَّاعَةُ الطَّامَّةُ. اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ صَلَاةً مُخَلِّصَةً عَنِ الْمَلَامَةِ. اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ صَلَاةً مُبَلِّغَةً إِلَى السَّلَامَةِ. اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ صَلَاةً فَائِضَةً عَلَى أَهْلِ الْكَرَامَةِ. اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ فِي كُلِّ حِينٍ وَآنٍ. اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ فِي كُلِّ زَمَانٍ وَمَكَانٍ. اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ فِي كُلِّ لِسَانٍ وَجَنَانٍ. اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ عِنْدَ ظُهُورِ كُلِّ حِكْمَةٍ وَبَيَانٍ. اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ صَاحِبِ الْكِتَابِ الْعَزِيزِ وَحَامِلِ الْفُرْقَانِ الْمَجِيدِ. اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ صَلَاةً جَامِعَةً بَيْنَ كُنْ وَكَانَ. وَصَلِّ عَلَى جَمِيعِ إِخْوَانِهِ مِنَ النَّبِيِّينَ وَالصِّدِّيقِينَ وَالشُّهَدَاءِ وَالصَّالِحِينَ أَهْلِ الْقِبْلَةِ وَالْإِيمَانِ. وَالْكِتَابِ وَالْمِيزَانِ. يَا حَنَّانُ يَا مَنَّانُ وَاغْفِرْ لِأُمَّةِ نَبِيِّكَ وَحَبِيبِكَ مُحَمَّدٍ عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ وَأَسْكِنْهُمْ أَعْلَى الْجِنَانِ وَأَحْسِنْ إِلَيْهِمْ وَلِيَّ الْإِحْسَانِ وَأَدْخِلْهُمْ بِرَحْمَتِكَ وَرِضًا وَرِضْوَانٍ وَالصَّلَوَاتِ وَالرَّحْمَةِ وَالْغُفْرَانِ وَأَعِذْهُمْ مِنَ الشَّيْطَانِ وَالنِّيرَانِ بِرَحْمَتِكَ يَا أَرْحَمَ الرَّاحِمِينَ.","latin":"Allâhümme salli alâ seyyidinâ Muhammedin fî arasâtil-kıyâmeh. Allâhümme salli alâ seyyidinâ Muhammedin hîne tekûmüs-sâatüt-tâmmeh. Allâhümme salli alâ seyyidinâ Muhammedin salâten muhallisaten anil-melâmeh. Allâhümme salli alâ seyyidinâ Muhammedin salâten mübelliğaten iles-selâmeh. Allâhümme salli alâ seyyidinâ Muhammedin salâten fâidaten alâ ehlil-kerâmeh. Allâhümme salli alâ seyyidinâ Muhammedin fî külli hînin ve ân. Allâhümme salli alâ seyyidinâ Muhammedin fî külli zamânin ve mekân. Allâhümme salli alâ seyyidinâ Muhammedin fî külli lisânin ve cenân. Allâhümme salli alâ seyyidinâ Muhammedin inde zuhûri külli hikmetin ve beyân. Allâhümme salli alâ seyyidinâ Muhammedin sâhibil-kitâbil-azîzi ve hâmilil-furkânil-mecîd. Allâhümme salli alâ seyyidinâ Muhammedin salâten câmiaten beyne kün ve kân. Ve salli alâ cemîi ihvânihî minen-nebiyyîne ves-sıddîkîne veş-şühedâi ves-sâlihîne ehlil-kıbleti vel-îmâni vel-kitâbi vel-mîzân. Yâ Hannânü yâ Mennânü vağfir li-ümmeti nebiyyike ve habîbike Muhammedin aleyhis-salâtü ves-selâmü ve eskinhüm a‘lel-cinâni ve ahsin ileyhim veliyyel-ihsâni ve edhılhüm bi-rahmetike ve rıdan ve rıdvânin ves-salavâti ver-rahmeti vel-ğufrâni ve e‘izhüm mineş-şeytâni ven-nîrân. Bi-rahmetike yâ Erhamer-râhimîn.","meaning":"Allah’ım! Kıyametin toplanma meydanlarında Efendimiz Muhammed’e (sallallahu aleyhi ve sellem) salât eyle. Her şeyi kuşatan o büyük kıyamet saati geldiğinde ona salât eyle. Kınanmadan kurtaran, selâmete ulaştıran ve ikram ehli üzerine taşan bir salât eyle. Her an ve vakitte, her zaman ve mekânda, her dil ve gönülde, her hikmet ve açıklama ortaya çıktığında ona salât eyle. Aziz Kitabın sahibi ve yüce Furkân’ın taşıyıcısı olan Efendimiz Muhammed’e salât eyle. “Ol” ile “oldu”yu bir araya getiren bir salât eyle. Onun peygamberlerden, sıddıklardan, şehitlerden ve salihlerden olan bütün kardeşlerine; kıble, iman, kitap ve mizan ehline de salât eyle. Ey çok şefkatli, ey bol ihsan sahibi! Peygamberin ve sevgilin Muhammed’in ümmetini bağışla; ona salât ve selâm olsun. Onları cennetlerin en yücesine yerleştir. Ey ihsanın sahibi, onlara iyilik eyle. Onları rahmetinle, hoşnutluğunla, rızanla, salâtlarınla, merhametinle ve bağışlamanla cennete koy. Onları şeytandan ve cehennem ateşlerinden koru. Rahmetinle, ey merhametlilerin en merhametlisi!","cat":"derleme","note":"Ulemanın bu salavatı “Eman ve Selamet Salavatı” olarak adlandırdığı; Arasât meydanında Peygamberimizin sancağı altında bulunmak ve hesabın kolaylığı niyetiyle seherde okunmasının tavsiye edildiği aktarılmıştır.","source":"Wird: Salawāt al-Awliyā, Arapça nüsha, s. 13–14.","arabicDraft":false,"previousArabic":"اللهم صل على سيدنا محمد في اراساتيل كاياماه. اللهم صل على سيدنا محمد هينا تاكوموسااتو واتتاماه. اللهم صل على سيدنا محمد صلاة موهاللاساتان انيل مالاماه. اللهم صل على سيدنا محمد صلاة موباللاغاتان يلاسالاماه. اللهم صل على سيدنا محمد صلاة فايزاتان على اهليل كيراماه. اللهم صل على سيدنا محمد في كل هينين و ان, في كل زامانان و ماكان, بيكوللي ليسانان و جانان, اندا زوهوري كل هيكماتين و بايان. اللهم صل على سيدنا محمد ساهيبيل كيتابيل ازيزي و هاميليل فوركان. اللهم صل على سيدنا محمد صلاة جامياتان باينا كون و كان. و صل على جاميي يهوانيهي ميناننابيينا واسادديكينا واشوهاداي واساليهين. يا هاننان يا ماننان, واغفير لي ومماتي محمد, و اسكينهوم الال جينان, بيراهماتيكا يا ارهامارراهيمين.","submittedArabic":"اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ فِي عَرَصَاتِ الْقِيَامَةِ. اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ حِينَ تَقُومُ السَّاعَةُ وَالتَّامَّةُ. اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ صَلَاةً مُخَلَّصَةً مِنَ الْمَلَامَةِ. اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ صَلَاةً مُبَلَّغَةً اِلَى السَّلَامَةِ. اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ صَلَاةً فَائِضَةً عَلٰى اَهْلِ الْكِرَامَةِ. اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ فِي كُلِّ حِينٍ وَآنٍ، فِي كُلِّ زَمَانٍ وَمَكَانٍ، بِكُلِّ لِسَانٍ وَجَنَانٍ، عِنْدَ ظُهُورِ كُلِّ حِكْمَةٍ وَبَيَانٍ. اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ صَاحِبِ الْكِتَابِ الْعَزِيزِ وَحَامِلِ الْفُرْقَانِ. اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ صَلَاةً جَامِعَةً بَيْنِ كُن وَكَانَ. وَصَلِّ عَلٰى جَمِيعِ اِخْوَانِهِ مِنَ النَّبِيِّينَ وَالصِّدِّيقِينَ وَالشُّهَدَاءِ وَالصَّالِحِينَ. يَا حَنَّانُ يَا مَنَّانُ، وَاغْفِرْ لِاُمَّتِ مُحَمَّدٍ، وَاَسْكِنْهُمْ عَلَى الْجِنَانِ، بِرَحْمَتِكَ يَا اَرْحَمَ الرَّاحِمِينَ.","source_note":"","displayNumber":63},{"id":"koleksiyon29","name":"Nûr ve Sürûr Salavatı","aliases":"Orijinal liste: 29","arabic":"اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ صَلَاةً لَاحِقَةً بِنُورِهِ. اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ صَلَاةً مَقْرُونَةً بِذِكْرِهِ وَمَذْكُورِهِ. اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ صَلَاةً مُنَوِّرَةً لِقَبْرِهِ بِأَكْمَلِ تَنْوِيرِهِ. اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ صَلَاةً شَارِحَةً لِصَدْرِهِ مُوجِبَةً لِسُرُورِهِ. وَصَلِّ عَلَى جَمِيعِ إِخْوَانِهِ مِنَ الْأَنْبِيَاءِ وَالْأَوْلِيَاءِ صَلَاةً بِعَدَدِ النُّورِ وَظُهُورِهِ.","latin":"Allâhümme salli alâ seyyidinâ Muhammedin salâten lâhikaten bi-nûrih. Allâhümme salli alâ seyyidinâ Muhammedin salâten makrûneten bi-zikrihî ve mezkûrih. Allâhümme salli alâ seyyidinâ Muhammedin salâten münevviraten li-kabrihî bi-ekmeli tenvîrih. Allâhümme salli alâ seyyidinâ Muhammedin salâten şârihaten li-sadrihî mûcibeten li-sürûrih. Ve salli alâ cemîi ihvânihî minel-enbiyâi vel-evliyâi salâten bi-adedin-nûri ve zuhûrih.","meaning":"Allah’ım! Efendimiz Muhammed’e (sallallahu aleyhi ve sellem), onun nuruna ulaşan bir salât eyle. Onun zikriyle ve zikrettiğiyle birlikte olan bir salât eyle. Kabrini en eksiksiz aydınlatmayla nurlandıran bir salât eyle. Göğsünü ferahlatan ve sevincine vesile olan bir salât eyle. Onun peygamberlerden ve velilerden olan bütün kardeşlerine de nurun ve onun ortaya çıkışının sayısınca salât eyle.","cat":"derleme","note":"Sûfiyye büyüklerinin vesvese, kasvet ve hüzün anında bu salavatı tavsiye ettiği; sürûrun iç ferahlığı anlamına geldiği aktarılmıştır.","source":"Nebhânî, Saâdetü’d-Dâreyn, 8. bölüm, 89.","arabicDraft":false,"previousArabic":"اللهم صل على سيدنا محمد صلاة لاهيكاتان بينوريهي. اللهم صل على سيدنا محمد صلاة ماكروناتان بيزيكريهي و مازكوريهي. اللهم صل على سيدنا محمد صلاة جامياتان باينا فاراهيهي و سوروريهي. اللهم صل على سيدنا محمد صلاة موهيتاتان بيتوريهي و سوريهي. اللهم صل على سيدنا محمد صلاة موناوواراتان ليكولوبي اسهابي سودوريهي. و صل على جاميي يهوانيهي مينال انبيياي و اوليياي يا ارهامارراهيمين.","submittedArabic":"اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ صَلَاةً لَاحِقَةً بِنُورِهِ. اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ صَلَاةً مَقْرُونَةً بِذِكْرِهِ وَمَذْكُورِهِ. اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ صَلَاةً جَامِعَةً بَيْنَ فَرَحِهِ وَسُرُورِهِ. اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ صَلَاةً مُحِيطَةً بِطُورِهِ وَسُورِهِ. اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ صَلَاةً مُنَوِّرَةً لِقُلُوبِ اَصْحَابِ صُدُورِهِ. وَصَلِّ عَلٰى جَمِيعِ اِخْوَانِهِ مِنَ الْاَنْبِيَاءِ وَالْاَوْلِيَاءِ يَا اَرْحَمَ الرَّاحِمِينَ.","source_note":"","displayNumber":64},{"id":"koleksiyon39","name":"Peygambere Selâm ve Hitaplar","aliases":"Orijinal liste: 39","arabic":"اَلصَّلَاةُ وَالسَّلَامُ عَلَيْكَ يَا رَسُولَ اللّٰهِ. اَلصَّلَاةُ وَالسَّلَامُ عَلَيْكَ يَا حَبِيبَ اللّٰهِ. اَلصَّلَاةُ وَالسَّلَامُ عَلَيْكَ يَا خَلِيلَ اللّٰهِ. اَلصَّلَاةُ وَالسَّلَامُ عَلَيْكَ يَا صَفِيَّ اللّٰهِ. اَلصَّلَاةُ وَالسَّلَامُ عَلَيْكَ يَا نَجِيَّ اللّٰهِ. اَلصَّلَاةُ وَالسَّلَامُ عَلَيْكَ يَا خَيْرَ خَلْقِ اللّٰهِ. اَلصَّلَاةُ وَالسَّلَامُ عَلَيْكَ يَا سَيِّدَ الْمُرْسَلِينَ. اَلصَّلَاةُ وَالسَّلَامُ عَلَيْكَ يَا اِمَامَ الْمُتَّقِينَ. اَلصَّلَاةُ وَالسَّلَامُ عَلَيْكَ يَا خَاتَمَ النَّبِيِّينَ. اَلصَّلَاةُ وَالسَّلَامُ عَلَيْكَ يَا شَفِيعَ الْاُمَّةِ. اَلصَّلَاةُ وَالسَّلَامُ عَلَيْكَ يَا صَاحِبَ الْمَقَامِ الْمَحْمُودِ. اَلصَّلَاةُ وَالسَّلَامُ عَلَيْكَ يَا نَبِيَّ الرَّحْمَةِ. اَلصَّلَاةُ وَالسَّلَامُ عَلَيْكَ يَا اَحْمَدُ. اَلصَّلَاةُ وَالسَّلَامُ عَلَيْكَ يَا سَيِّدِي مُحَمَّدُ. صَلَوَاتُ اللّٰهِ وَمَلَائِكَتِهِ وَرُسُلِهِ وَحَمَلَةِ عَرْشِهِ وَجَمِيعِ خَلْقِهِ عَلَيْكَ وَعَلٰى اٰلِكَ وَاَصْحَابِكَ وَرَحْمَتُ اللّٰهِ وَبَرَكَاتُهُ.","latin":"Essalâtü vesselâmü aleyke yâ Resûlallâh. Essalâtü vesselâmü aleyke yâ Habîballâh. Essalâtü vesselâmü aleyke yâ Halîlallâh. Essalâtü vesselâmü aleyke yâ Safiyyallâh. Essalâtü vesselâmü aleyke yâ Neciyyallâh. Essalâtü vesselâmü aleyke yâ Hayre halkillâh. Essalâtü vesselâmü aleyke yâ Seyyidel mürselîn. Essalâtü vesselâmü aleyke yâ İmâmel müttekîn. Essalâtü vesselâmü aleyke yâ Hâtemennebiyyîn. Essalâtü vesselâmü aleyke yâ Şefîal ümmeti. Essalâtü vesselâmü aleyke yâ Sâhibel-makâmil-mahmûd. Essalâtü vesselâmü aleyke yâ Nebiyyerrahmeti. Essalâtü vesselâmü aleyke yâ Ahmed. Essalâtü vesselâmü aleyke yâ Seyyidi Muhammed. Salavâtullâhi ve melâiketihî ve rüsülihî ve hameleti arşihî ve cemîi halkıhî aleyke ve alâ âlike ve eshâbike ve rahmetullâhi ve berekâtühû.","meaning":"Salât ve selâm sana olsun ey Allah'ın Resulü! Salât ve selâm sana olsun ey Allah'ın sevgilisi! Salât ve selâm sana olsun ey Allah'ın dostu! Salât ve selâm sana olsun ey Allah'ın seçkini! Salât ve selâm sana olsun ey Allah'ın sırdaş kıldığı! Salât ve selâm sana olsun ey Allah'ın yaratılmışlarının en hayırlısı! Salât ve selâm sana olsun ey elçilerin efendisi! Salât ve selâm sana olsun ey takvâ sahiplerinin önderi! Salât ve selâm sana olsun ey peygamberlerin sonuncusu! Salât ve selâm sana olsun ey ümmetin şefaatçisi! Salât ve selâm sana olsun ey Makâm-ı Mahmûd'un sahibi! Salât ve selâm sana olsun ey rahmet peygamberi! Salât ve selâm sana olsun ey Ahmed! Salât ve selâm sana olsun ey Efendimiz Muhammed (sallallahu aleyhi ve sellem)! Allah'ın, meleklerinin, elçilerinin, arşını taşıyanların ve bütün yaratılmışlarının salâtı senin üzerine; ayrıca ailenin ve ashabının üzerine olsun. Allah'ın rahmeti ve bereketleri de üzerinize olsun.","cat":"derleme","note":"Medine’de Hücre-i Saadet huzurunda veya uzaktan kalbi Medine’ye çevirerek okunacak selam hitapları olarak tanıtılmıştır.","source":"Bursevî, Rûhu’l-Beyân, Ahzâb 33:56.","arabicDraft":false,"previousArabic":"اسالاتو واسالامو الايكا يا راسولاللاه. اسالاتو واسالامو الايكا يا هابيباللاه. اسالاتو واسالامو الايكا يا هاليلاللاه. اسالاتو واسالامو الايكا يا سافياللاه. اسالاتو واسالامو الايكا يا ناجياللاه. اسالاتو واسالامو الايكا يا هايرا هالكيللاه. اسالاتو واسالامو الايكا يا ساييدال مورسالين. اسالاتو واسالامو الايكا يا ي̇مامال موتتاكين. اسالاتو واسالامو الايكا يا هاتاماننابيين. اسالاتو واسالامو الايكا يا شافيال ومماتي. اسالاتو واسالامو الايكا يا ساهيبا ماكاميل ماهمود. اسالاتو واسالامو الايكا يا نابيارراهماتي. اسالاتو واسالامو الايكا يا اهماد. اسالاتو واسالامو الايكا يا ساييدي محمد. سالاواتوللاهي و مالايكاتيهي و روسوليهي و هامالاتي ارشيهي و جاميي هالكاهي الايكا و على اليكا و اسهابيكا و راهماتوللاهي و باراكاتوهو.","submittedArabic":"اَلسَّلَاةُ وَالسَّلَامُ عَلَيْكَ يَا رَسُولَ اللّٰهِ. اَلسَّلَاةُ وَالسَّلَامُ عَلَيْكَ يَا حَبِيبَ اللّٰهِ. اَلسَّلَاةُ وَالسَّلَامُ عَلَيْكَ يَا خَلِيلَ اللّٰهِ. اَلسَّلَاةُ وَالسَّلَامُ عَلَيْكَ يَا صَفِيَّ اللّٰهِ. اَلسَّلَاةُ وَالسَّلَامُ عَلَيْكَ يَا نَجِيَّ اللّٰهِ. اَلسَّلَاةُ وَالسَّلَامُ عَلَيْكَ يَا خَيْرَ خَلْقِ اللّٰهِ. اَلسَّلَاةُ وَالسَّلَامُ عَلَيْكَ يَا سَيِّدَ الْمُرْسَلِينَ. اَلسَّلَاةُ وَالسَّلَامُ عَلَيْكَ يَا اِمَامَ الْمُتَّقِينَ. اَلسَّلَاةُ وَالسَّلَامُ عَلَيْكَ يَا خَاتَمَ النَّبِيِّينَ. اَلسَّلَاةُ وَالسَّلَامُ عَلَيْكَ يَا شَفِيعَ الْاُمَّةِ. اَلسَّلَاةُ وَالسَّلَامُ عَلَيْكَ يَا صَاحِبَ الْمَقَامِ الْمَحْمُودِ. اَلسَّلَاةُ وَالسَّلَامُ عَلَيْكَ يَا نَبِيَّ الرَّحْمَتِ. اَلسَّلَاةُ وَالسَّلَامُ عَلَيْكَ يَا اَحْمَدُ. اَلسَّلَاةُ وَالسَّلَامُ عَلَيْكَ يَا سَيِّدِي مُحَمَّدٌ. صَلَوَاتُ اللّٰهِ وَمَلَائِكَتِهِ وَرُسُلِهِ وَحَمَلَةِ عَرْشِهِ وَجَمِيعِ خَلْقِهِ عَلَيْكَ وَعَلٰى اٰلِكَ وَاَصْحَابِكَ وَرَحْمَتُ اللّٰهِ وَبَرَكَاتُهُ.","source_note":"","displayNumber":65},{"id":"koleksiyon40","name":"Haremeyn ve Sakaleyn Selâmı","aliases":"Orijinal liste: 40","arabic":"اَلسَّلَامُ عَلَيْكَ يَا اِمَامَ الْحَرَمَيْنِ. اَلسَّلَامُ عَلَيْكَ يَا اِمَامَ الْخَافِقَيْنِ. اَلسَّلَامُ عَلَيْكَ يَا رَسُولَ الثَّقَلَيْنِ. اَلسَّلَامُ عَلَيْكَ يَا صَاحِبَ الْقِبْلَتَيْنِ. اَلسَّلَامُ عَلَيْكَ يَا نُورَ الْمَشْرِقَيْنِ وَضِيَاءَ الْمَغْرِبَيْنِ. اَلسَّلَامُ عَلَيْكَ يَا جَدَّ السِّبْطَيْنِ الْحَسَنِ وَالْحُسَيْنِ. عَلَيْكَ وَعَلٰى عِتْرَتِكَ وَاَوْلَادِكَ وَاَزْوَاجِكَ وَاَصْحَابِكَ وَاَتْبَاعِكَ سَلَامُ اللّٰهِ وَمَلَائِكَتِهِ وَالنَّاسِ اَجْمَعِينَ اِلٰى يَوْمِ الدِّينِ. وَالْحَمْدُ لِلهِ رَبِّ الْعَالَمِينَ.","latin":"Esselâmü aleyke yâ imâmel haremeyn. Esselâmü aleyke yâ imâmel hâfikeyn. Esselâmü aleyke yâ Resûlessakaleyn. Esselâmü aleyke yâ sâhibel kıbleteyn. Esselâmü aleyke yâ nûral meşrikayn ve ziyâel mağribeyn. Esselâmü aleyke yâ ceddessibtayni el Hasani vel Hüseyni. Aleyke ve alâ itretike ve evlâdike ve ezvâcike ve eshâbike ve etbâike selâmullâhi ve melâiketihî vennâsi ecmaîne ilâ yevmiddîn. Velhamdülillâhi Rabbil âlemîn.","meaning":"Selâm sana olsun ey iki harem bölgesinin imamı! Selâm sana olsun ey doğu ve batı ufuklarının imamı! Selâm sana olsun ey insanlara ve cinlere gönderilen elçi! Selâm sana olsun ey iki kıblenin sahibi! Selâm sana olsun ey iki doğunun nuru ve iki batının ışığı! Selâm sana olsun ey Hasan ile Hüseyin'in dedesi! Allah'ın, meleklerinin ve bütün insanların selâmı kıyamet gününe kadar senin, soyunun, çocuklarının, eşlerinin, ashabının ve sana uyanların üzerine olsun. Hamd âlemlerin Rabbi Allah'a mahsustur.","cat":"derleme","note":"İmam Şa‘rânî’ye nispetle Peygamberimizin insanlara ve cinlere gönderilişini ve Ehl-i Beyt sevgisini vurgulayan bir selam olarak tanıtılmıştır. Hz. Hasan ve Hz. Hüseyin’e muhabbet ve şefaat niyetiyle okunması aktarılmıştır.","source":"Bursevî, Rûhu’l-Beyân, Ahzâb 33:56.","arabicDraft":false,"previousArabic":"اسالامو الايكا يا يمامال هاراماين. اسالامو الايكا يا يمامال هافيكاين. اسالامو الايكا يا راسولاساكالاين. اسالامو الايكا يا ساهيبال كابلاتاين. اسالامو الايكا يا نورال ماشريكاين و زيياال ماغريباين. اسالامو الايكا يا جادداسيبتايني ال هاساني وال هوسايني. الايكا و على يتراتيكا و اولاديكا و ازواجيكا و اسهابيكا و اتبايكا سالاموللاهي وال مالايكاتيهي وانناسي اجماينا إلى ياوميددين. والهامدوليللاهي رب العالمين.","submittedArabic":"اَلسَّلَامُ عَلَيْكَ يَا اِمَامَ الْحَرَمَيْنِ. اَلسَّلَامُ عَلَيْكَ يَا اِمَامَ الْخَافِقَيْنِ. اَلسَّلَامُ عَلَيْكَ يَا رَسُولَ الثَّقَلَيْنِ. اَلسَّلَامُ عَلَيْكَ يَا صَاحِبَ الْقِبْلَتَيْنِ. اَلسَّلَامُ عَلَيْكَ يَا نُورَ الْمَشْرِقَيْنِ وَضِيَاءَ الْمَغْرِبَيْنِ. اَلسَّلَامُ عَلَيْكَ يَا جَدَّ السِّبْطَيْنِ الْحَسَنِ وَالْحُسَيْنِ. عَلَيْكَ وَعَلٰى عِتْرَتِكَ وَاَوْلَادِكَ وَاَزْوَاجِكَ وَاَصْحَابِكَ وَاَتْبَاعِكَ سَلَامُ اللّٰهِ وَمَلَائِكَتِهِ وَالنَّاسِ اَجْمَعِينَ اِلٰى يَوْمِ الدِّينِ. وَالْحَمْدُ لِلهِ رَبِّ الْعَالَمِينَ.","source_note":"","displayNumber":66},{"id":"koleksiyon79","name":"Yağmur ve Yapraklar Adedince","aliases":"Orijinal liste: 79","arabic":"بِسْمِ اللّٰهِ الرَّحْمٰنِ الرَّحِيمِ. اَللّٰهُمَّ صَلِّ عَلٰى مُحَمَّدٍ النَّبِيِّ عَدَدَ مَنْ صَلّٰى عَلَيْهِ مِنَ الْاَخْيَارِ وَعَدَدَ مَنْ لَمْ يُصَلِّ عَلَيْهِ. وَعَدَدَ قَطَرَاتِ الْاَمْطَارِ وَاَوْرَاقِ الْاَشْجَارِ وَاَنْفَاسِ الْمُسْتَغْفِرِينَ بِالْاَسْحَارِ. وَعَدَدَ مَا كَانَ وَمَا يَكُونُ اِلٰى يَوْمِ الْحَشْرِ. وَصَلِّ عَلَيْهِ مَا تَعَاقَبَ اللَّيْلُ وَالنَّهَارُ. وَبَلِّغْ رُوحَهُ وَاَرْوَاحَ اَهْلِ بَيْتِهِ مِنَّا التَّحِيَّةَ وَالسَّلَامَ. اَللّٰهُمَّ صَلِّ عَلٰى مُحَمَّدٍ وَعَلٰى اٰلِ مُحَمَّدٍ بِعَدَدِ كُلِّ ذَرَّةٍ اَلْفَ اَلْفَ مَرَّةٍ. سُبُّوحٌ قُدُّوسٌ رَبُّنَا وَرَبُّ الْمَلَائِكَةِ وَالرُّوحِ. رَبِّ اغْفِرْ وَارْحَمْ.","latin":"Bismillâhirrahmânirrahîm. Allâhümme salli alâ Muhammedinin nebiyyi adede men sallâ aleyhi minel ahyâr ve adede men lem yusalli aleyhi. Ve adede katarâtil emtâr ve evrâkiş eşcâr ve enfâsil müstağfirîne bil eshâr. Ve adede mâ kâne ve mâ yekûnü ilâ yevmil haşr. Ve salli aleyhi mâ teâkabel leylü vennehâr. Ve belliğ rûhahû ve ervâha ehli beytihî minnet tahiyyete vesselâm. Allâhümme salli alâ Muhammedin ve alâ âli Muhammedin biadedi külli zerretin elfe elfe merretin. Sübbûhun kuddûsün Rabbünâ ve Rabbül melâiketi verrûh. Rabbiğfir verham.","meaning":"Rahmân ve Rahîm olan Allah'ın adıyla. Allah'ım! Peygamber Efendimiz Muhammed'e (sallallahu aleyhi ve sellem), hayırlı kimselerden ona salât edenlerin sayısınca ve ona salât etmeyenlerin sayısınca salât eyle. Yağmur damlalarının, ağaç yapraklarının ve seher vakitlerinde bağışlanma dileyenlerin nefeslerinin sayısınca salât eyle. Geçmişte olanların ve mahşer gününe kadar olacakların sayısınca salât eyle. Gece ve gündüz birbirini izlediği müddetçe ona salât eyle. Onun ruhuna ve Ehl-i beytinin ruhlarına bizden selâm ve esenlik dileklerini ulaştır. Allah'ım! Efendimiz Muhammed'e ve ailesine her bir zerre adedince binlerce bin defa salât eyle. Sen her türlü eksiklikten uzak ve pek mukaddessin. Rabbimiz; meleklerin ve Ruh'un Rabbidir. Rabbim! Bağışla ve merhamet et.","cat":"derleme","note":"İmam Gazâlî’nin İhyâ’sına ve Ahmed el-Bûnî’ye nispetle adetli salavat, bereket ve rızık hakkında açıklamalar aktarılmıştır.","source":"","arabicDraft":false,"previousArabic":"بيسميللاهيرراهمانيرراهيم. اللهم صل على موهاممادينين نابيي عدد مان ساللاللاهو الايهي مينال اهيار و عدد مان لام يوساللي الايهي. و عدد كاتاراتيل امتار و اوراكيش اشجار و انفاسيل موستاغفيرينا بيل اسهار. و عدد ما كانا و ما ياكونو إلى ياوميل هاشر. و صل الايهي ما تااكابال لايلو وانناهار. و بالليغ روهاهو و ارواها اهلي بايتيهي ميننات تاهياتا واسالام. اللهم صل على محمد و على الي محمد بيادادي كل زارراتين الفا الفا مارراتين. سوببوهون كوددوسون راببونا و راببول مالايكاتي وارروه. راببيغفير وارهام.","submittedArabic":"بِسْمِ اللّٰهِ الرَّحْمٰنِ الرَّحِيمِ. اَللّٰهُمَّ صَلِّ عَلٰى مُحَمَّدٍ النَّبِيِّ عَدَدَ مَنْ صَلّٰى عَلَيْهِ مِنَ الْاَخْيَارِ وَعَدَدَ مَنْ لَمْ يُصَلِّ عَلَيْهِ. وَعَدَدَ قَطَرَاتِ الْاَمْطَارِ وَاَوْرَاقِ الْاَشْجَارِ وَاَنْفَاسِ الْمُسْتَغْفِرِينَ بِالْاَسْحَارِ. وَعَدَدَ مَا كَانَ وَمَا يَكُونُ اِلٰى يَوْمِ الْحَشْرِ. وَصَلِّ عَلَيْهِ مَا تَعَاقَبَ اللَّيْلُ وَالنَّهَارُ. وَبَلِّغْ رُوحَهُ وَاَرْوَاحَ اَهْلِ بَيْتِهِ مِنَّا التَّحِيَّةَ وَالسَّلَامَ. اَللّٰهُمَّ صَلِّ عَلٰى مُحَمَّدٍ وَعَلٰى اٰلِ مُحَمَّدٍ بِعَدَدِ كُلِّ ذَرَّةٍ اَلْفَ اَلْفَ مَرَّةٍ. سُبُّوحٌ قُدُّوسٌ رَبُّنَا وَرَبُّ الْمَلَائِكَتِ وَالرُّوحِ. رَبِّ اغْفِرْ وَارْحَمْ.","source_note":"","displayNumber":67},{"id":"koleksiyon82","name":"Bahr-i Envârın Diğer Metni","aliases":"Orijinal liste: 82","arabic":"اَللّٰهُمَّ صَلِّ عَلٰى مُحَمَّدٍ بَحْرِ اَنْوَارِكَ وَمَعْدِنِ اَسْرَارِكَ وَعَيْنِ عِنَايَتِكَ وَشَمْسِ هِدَايَتِكَ وَعَرُوسِ مَمْلَكَتِكَ وَاَمْنِ وِلَايَتِكَ وَلِسَانِ مُحَبَّتِكَ وَاِمَامِ حَضْرَتِكَ وَخَيْرِ خَلْقِكَ وَاَحَبِّ الْخَلْقِ اِلَيْكَ، عَبْدِكَ وَحَبِيبِكَ وَرَسُولِكَ النَّبِيِّ الْاُمِّيِّ الَّذِي خَتَمْتَ بِهِ الْاَنْبِيَاءَ وَالْمُرْسَلِينَ. وَعَلٰى مَلَائِكَتِكَ الْمُقَرَّبِينَ مِنْ اَهْلِ السَّمَاوَاتِ وَاَهْلِ الْاَرَضِينَ رِضْوَانُ اللّٰهِ عَلَيْهِمْ اَجْمَعِينَ بِرَحْمَتِكَ يَا اَرْحَمَ الرَّاحِمِينَ.","latin":"Allâhümme salli alâ Muhammedin bahri envârike ve ma’deni esrârike ve ayni inâyetike ve şemsi hidâyetike ve arûsi memleketike ve emni vilâyetike ve lisâni muhabbetike ve imâmi hazretike ve hayri halkıke ve ehabbil halkı ileyke, abdike ve habîbike ve resûliken nebiyyil ümmiyyillezî hatemte bihil enbiyâe vel mürselîne. Ve alâ melâiketikel mukarrabîne min ehlissemâvâti ve ehlil aradîne rıdvânullâhi aleyhim ecmaîne birahmetike yâ Erhamerrâhimîn.","meaning":"Allah'ım! Nurlarının denizi, sırlarının madeni, inayetinin kaynağı, hidayetinin güneşi, mülkünün gelini ve süsü, velâyetinin güveni, muhabbetinin dili, huzurunun imamı, yaratılmışlarının en hayırlısı ve Sana en sevgili olan; kulun, sevgilin, elçin ve kendisiyle peygamberleri ve resulleri sona erdirdiğin ümmî peygamber Efendimiz Muhammed'e (sallallahu aleyhi ve sellem) salât eyle. Göklerin ve yerlerin ehlinden Sana yakın kılınmış meleklerine de salât eyle. Allah'ın rızası hepsinin üzerine olsun. Ey merhametlilerin en merhametlisi, rahmetinle!","cat":"derleme","note":"Ebü’l-Hasan eş-Şâzelî’ye, bazı aktarımlarda Abdülkadir Geylânî’ye nispet edilir. Cuma gecesi okumaya devam etmenin marifet ve hikmete vesile olacağı şeklindeki tasavvufi yorum aktarılmıştır.","source":"","arabicDraft":false,"previousArabic":"اللهم صل على محمد باهري انواريكا و ماداني اسراريكا و ايني يناياتيكا و شامسي هيداياتيكا و اروسي ماملاكاتيكا و امني ويلاياتيكا و ليساني موهابباتيكا و يمامي هازراتيكا و هايري هالكاكا و اهاببيل هالكا يلايكا, عبدك و هابيبيكا و راسوليكان النبي وممييللازي هاتامتا بيهيل انبيياا وال مورسالينا. و على مالايكاتيكال موكاررابينا من اهليساماواتي و اهليل ارادينا رادوانوللاهي الايهيم اجماينا بيراهماتيكا يا ارهامارراهيمين.","submittedArabic":"اَللّٰهُمَّ صَلِّ عَلٰى مُحَمَّدٍ بَحْرِ اَنْوَارِكَ وَمَعْدِنِ اَسْرَارِكَ وَعَيْنِ عِنَايَتِكَ وَشَمْسِ هِدَايَتِكَ وَعَرُوسِ مَمْلَكَتِكَ وَاَمْنِ وِلَايَتِكَ وَلِسَانِ مُحَبَّتِكَ وَاِمَامِ حَضْرَتِكَ وَخَيْرِ خَلْقِكَ وَاَحَبِّ الْخَلْقِ اِلَيْكَ، عَبْدِكَ وَحَبِيبِكَ وَرَسُولِكَ النَّبِيِّ الْاُمِّيِّ الَّذِي خَتَمْتَ بِهِ الْاَنْبِيَاءَ وَالْمُرْسَلِينَ. وَعَلٰى مَلَائِكَتِكَ الْمُقَرَّبِينَ مِنْ اَهْلِ السَّمَاوَاتِ وَاَهْلِ الْاَرَضِينَ رِضْوَانُ اللّٰهِ عَلَيْهِمْ اَجْمَعِينَ بِرَحْمَتِكَ يَا اَرْحَمَ الرَّاحِمِينَ.","source_note":"","displayNumber":68},{"id":"koleksiyon83","name":"Efdal-i Salavât (Uzun)","aliases":"Orijinal liste: 83","arabic":"اللَّهُمَّ اجْعَلْ أَفْضَلَ صَلَوَاتِكَ أَبَدًا وَأَنْمَى بَرَكَاتِكَ سَرْمَدًا وَأَزْكَى تَحِيَّاتِكَ فَضْلًا وَعَدَدًا عَلَى أَشْرَفِ الْخَلَائِقِ الْإِنْسَانِيَّةِ وَمَجْمَعِ الْحَقَائِقِ الْإِيمَانِيَّةِ وَطُورِ التَّجَلِّيَاتِ الْإِحْسَانِيَّةِ وَمَهْبِطِ الْأَسْرَارِ الرَّحْمَانِيَّةِ وَاسِطَةِ عِقْدِ النَّبِيِّينَ وَمُقَدَّمِ جَيْشِ الْمُرْسَلِينَ وَقَائِدِ رَكْبِ الْأَنْبِيَاءِ الْمُكَرَّمِينَ وَأَفْضَلِ الْخَلَائِقِ أَجْمَعِينَ حَامِلِ لِوَاءِ الْعِزِّ الْأَعْلَى وَمَالِكِ أَزِمَّةِ الْمَجْدِ الْأَسْنَى شَاهِدِ أَسْرَارِ الْأَزَلِ وَمُشَاهِدِ أَنْوَارِ السَّوَابِقِ الْأُوَلِ وَتَرْجُمَانِ لِسَانِ الْقِدَمِ وَمَنْبَعِ الْعِلْمِ وَالْحِلْمِ وَالْحِكَمِ مَظْهَرِ سِرِّ الْجُودِ الْجُزْئِيِّ وَالْكُلِّيِّ وَإِنْسَانِ عَيْنِ الْوُجُودِ الْعُلْوِيِّ وَالسُّفْلِيِّ رُوحِ جَسَدِ الْكَوْنَيْنِ وَعَيْنِ حَيَاةِ الدَّارَيْنِ الْمُتَحَقِّقِ بِأَعْلَى رُتَبِ الْعُبُودِيَّةِ الْمُتَخَلِّقِ بِأَخْلَاقِ الْمَقَامَاتِ الِاصْطِفَائِيَّةِ الْخَلِيلِ الْأَعْظَمِ وَالْحَبِيبِ الْأَكْرَمِ سَيِّدِنَا مُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ عَبْدِ الْمُطَّلِبِ وَعَلَى سَائِرِ الْأَنْبِيَاءِ وَالْمُرْسَلِينَ وَعَلَى آلِهِمْ وَصَحْبِهِمْ أَجْمَعِينَ كُلَّمَا ذَكَرَكَ الذَّاكِرُونَ وَغَفَلَ عَنْ ذِكْرِهِمُ الْغَافِلُونَ.","latin":"Allâhümmec‘al efdale salavâtike ebeden ve enmâ berekâtike sermeden ve ezkâ tahiyyâtike fadlen ve adeden alâ eşrefil-halâikil-insâniyyeti ve mecmeil-hakâikil-îmâniyyeti ve tûrit-tecelliyâtil-ihsâniyyeti ve mehbitil-esrârir-rahmâniyyeti vâsıtati ikdin-nebiyyîne ve mukaddemi ceyşil-mürselîne ve kâidi rakbil-enbiyâil-mükerremîne ve efdalil-halâiki ecmaîne hâmili livâil-izzil-a‘lâ ve mâliki ezimmetil-mecdil-esnâ şâhidi esrâril-ezeli ve müşâhidi envâris-sevâbikıl-üveli ve tercümâni lisânil-kıdemi ve menbeil-ilmi vel-hilmi vel-hikemi mazheri sirril-cûdil-cüz’iyyi vel-külliyyi ve insâni aynil-vücûdil-ulviyyî ves-süfliyyi rûhi cesedil-kevneyni ve ayni hayâtid-dâraynil-mütehakkıkı bi-a‘lâ rutebil-ubûdiyyetil-mütehallikı bi-ahlâkil-makâmâtil-istıfâiyyetil-halîlil-a‘zami vel-habîbil-ekremi seyyidinâ Muhammedibni Abdillâhibni Abdilmuttalib. Ve alâ sâiril-enbiyâi vel-mürselîne ve alâ âlihim ve sahbihim ecmaîne küllemâ zekerakez-zâkirûne ve ğafele an zikrihimül-ğâfilûn.","meaning":"Allah’ım! Ebediyen en üstün salâtlarını, sonsuza dek en çok artan bereketlerini, fazilet ve sayı bakımından en temiz selâmlarını; insan olarak yaratılmışların en şereflisine, iman hakikatlerinin toplandığı yere, ihsan tecellilerinin Tûr’una, Rahmânî sırların indiği makama, peygamberler gerdanlığının ortasındaki kıymetli cevhere, elçiler ordusunun öncüsüne, değerli peygamberler kafilesinin rehberine ve bütün yaratılmışların en üstününe ihsan eyle. O; en yüce izzet sancağının taşıyıcısı, en yüksek şerefin dizginlerinin sahibi, ezel sırlarının şahidi, ilk nurların müşahede edicisi, kıdem dilinin tercümanı, ilmin, yumuşak huyluluğun ve hikmetlerin kaynağı, cüz’î ve küllî cömertlik sırrının görünme yeri, yüce ve aşağı varlık âleminin göz bebeği, iki âlemin bedeninin ruhu, iki yurdun hayat kaynağı, kulluğun en yüce derecelerini gerçekleştiren, seçilmişlik makamlarının ahlâkıyla ahlâklanan, en büyük dost ve en değerli sevgili olan, Abdullah oğlu ve Abdülmuttalib torunu Efendimiz Muhammed’dir (sallallahu aleyhi ve sellem). Diğer bütün peygamberlere, elçilere, onların ailelerine ve ashabının tamamına da Seni ananlar her andığında ve gafiller onları anmaktan her gafil kaldığında salât eyle.","cat":"derleme","note":"Ahmed es-Sâvî, “Allahümme’c‘al efdale salavâtike ebedâ...” diye başlayan uzun salavatı Şemsü’l-Kenzi’l-A‘zam diye adlandırır ve manevi faziletine ilişkin sözler nakleder.","source":"Nebhânî, Efdalü’s-Salavât, 32.","arabicDraft":false,"previousArabic":"اللاهومماجال افدالا صلواتك ابادان و انما بركاتك سارمادان و ازكا تاهياتيكا فادلان و ادادان على اشرافيل هالايكيل ينسانياتي و ماجماال هاكايكيل يمانياتي و توريتتاجالليياتيل يهسانياتي و ماهبيتيل اسرارير راهمانياتي و اروسيل ماملاكاتير راببانياتي و واساتاتي اكدين نابيينا و موكادديمي جايشيل مورسالينا و كايدي راكبيل انبييايل موكاررامينا, سيدنا محمد يبني ابديللاه يبني ابديلموتتاليب. و على سايريل انبيياي وال مورسالينا و مالايكاتيكال موكاررابينا و يباديللاهيس ساليهينا.","submittedArabic":"اَللّٰهُمَّ اجْعَلْ اَفْضَلَ صَلَوَاتِكَ اَبَدًا وَاَنْمٰى بَرَكَاتِكَ سَرْمَدًا وَاَزْكٰى تَحِيَّاتِكَ فَضْلًا وَعَدَدًا عَلٰى اَشْرَفِ الْخَلَائِقِ الْاِنْسَانِيَّةِ وَمَجْمَعِ الْحَقَائِقِ الْاِيمَانِيَّةِ وَطُورِ التَّجَلِّيَاتِ الْاِحْسَانِيَّةِ وَمَهْبِطِ الْاَسْرَارِ الرَّحْمَانِيَّةِ وَعَرُوسِ الْمَمْلَكَةِ الرَّبَّانِيَّةِ وَوَاسِطَةِ عِقْدِ النَّبِيِّينَ وَمُقَدِّمِ جَيْشِ الْمُرْسَلِينَ وَقَائِدِ رَكْبِ الْاَنْبِيَاءِ الْمُكَرَّمِينَ، سَيِّدِنَا مُحَمَّدِ بْنِ عَبْدِ اللّٰهِ بْنِ عَبْدِ الْمُطَّلِبِ. وَعَلٰى سَائِرِ الْاَنْبِيَاءِ وَالْمُرْسَلِينَ وَمَلَائِكَتِكَ الْمُقَرَّبِينَ وَعِبَادِ اللّٰهِ الصَّالِحِينَ.","source_note":"","displayNumber":69},{"id":"koleksiyon87","name":"Zât-ı Muhammediyye","aliases":"Orijinal liste: 87","arabic":"بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ. اللَّهُمَّ صَلِّ عَلَى الذَّاتِ الْمُحَمَّدِيَّةِ اللَّطِيفَةِ الْأَحَدِيَّةِ شَمْسِ سَمَاءِ الْأَسْرَارِ وَمَظْهَرِ الْأَنْوَارِ وَمَرْكَزِ مَدَارِ الْجَلَالِ وَقُطْبِ فَلَكِ الْجَمَالِ. اللَّهُمَّ بِسِرِّهِ لَدَيْكَ وَبِسَيْرِهِ إِلَيْكَ آمِنْ خَوْفِي وَأَقِلْ عَثْرَتِي وَأَذْهِبْ حُزْنِي وَحِرْصِي وَكُنْ لِي وَخُذْنِي إِلَيْكَ مِنِّي وَارْزُقْنِي الْفَنَاءَ عَنِّي وَلَا تَجْعَلْنِي مَفْتُونًا بِنَفْسِي مَحْجُوبًا بِحِسِّي وَاكْشِفْ لِي عَنْ كُلِّ سِرٍّ مَكْتُومٍ يَا حَيُّ يَا قَيُّومُ.","latin":"Bismillâhirrahmânirrahîm. Allâhümme salli alez-zâtil-Muhammediyyetil-latîfetil-ehadiyyeti şemsi semâil-esrâri ve mazheril-envâri ve merkezi medâril-celâli ve kutbi felekil-cemâl. Allâhümme bi-sirrihî ledeyke ve bi-seyrihî ileyke âmin havfî ve ekıl asretî ve ezhib huznî ve hırsî ve kün lî ve huznî ileyke minnî verzuknil-fenâe annî ve lâ tec‘alnî meftûnen bi-nefsî mahcûben bi-hissî vekşif lî an külli sirrin mektûm. Yâ Hayyü yâ Kayyûm.","meaning":"Rahmân ve Rahîm olan Allah’ın adıyla. Allah’ım! Latif ve birliğe ait Muhammedî zâta; sırlar göğünün güneşine, nurların görünme yerine, celâlin yörüngesinin merkezine ve cemâl feleğinin kutbuna salât eyle. Allah’ım! Onun Senin katındaki sırrı ve Sana yönelen manevi yolculuğu hürmetine korkumu güvene çevir, sürçmemi bağışla, üzüntümü ve hırsımı gider. Benim yardımcım ol; beni benliğimden alıp Sana yönelt ve bana benliğimden geçmeyi nasip et. Beni nefsime kapılmış, duyularımla perdelenmiş kılma. Her gizli sırrın üzerindeki perdeyi benim için kaldır. Ey Hayy, ey Kayyûm!","cat":"derleme","note":"Yûsuf en-Nebhânî, bu salavatın İbrahim ed-Desûkî’ye nispet edildiğini yazar.","source":"Nebhânî, Efdalü’s-Salavât, 36.","arabicDraft":false,"previousArabic":"اللهم صل الاززاتيل موهاممادياتيل لاتيفاتيل اهادياتي شامسي سامايل أسرار و مازهاريل أنوار و ماركازي ماداريل جالالي و كوتبي فالاكيل جامالي. اللهم ب سارراهي لادايكا و سايريهي يلايكا امين هاوفي و اكيل وسراتي و ازهيب هوزني و هارسي. والا تاجالني مافتونان ب نافسي ماهجوبان بيهيسي. واكشيف لي ان كل سارران ماكتومين. و على اليهي و ساهبيهي و سلم. يا هايو يا كايوم يا الله.","submittedArabic":"بِسْمِ اللّٰهِ الرَّحْمٰنِ الرَّحِيمِ\nاَللّٰهُمَّ صَلِّ عَلَى الذَّاتِ الْمُحَمَّدِيَّةِ اللَّطِيفَةِ الْاَحَدِيَّةِ، شَمْسِ سَمَاءِ الْاَسْرَارِ، وَمَظْهَرِ الْاَنْوَارِ، وَمَرْكَزِ مَدَارِ الْجَلَالِ، وَقُطْبِ فَلَكِ الْجَمَالِ. اَللّٰهُمَّ بِسِرِّهِ لَدَيْكَ، وَسَيْرِهِ اِلَيْكَ، اٰمِنْ خَوْفِي، وَاَقِلْ عَثْرَتِي (عُسْرَتِي)، وَاَذْهِبْ حُزْنِي وَحِرْصِي. وَلَا تَجْعَلْنِي مَفْتُوناً بِنَفْسِي، مَحْجُوباً بِحِسِّي. وَاكْشِفْ لِي عَنْ كُلِّ سِرٍّ مَكْتُومٍ. وَعَلٰى اٰلِهِ وَصَحْبِهِ وَسَلِّمْ. يَا حَيُّ يَا قَيُّومُ يَا اَللّٰهُ.","source_note":"","displayNumber":70},{"id":"koleksiyon88","name":"Şeceretü’l-Asl","aliases":"Orijinal liste: 88","arabic":"اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلٰى سَيِّدِنَا وَمَوْلَانَا مُحَمَّدٍ شَجَرَةِ الْاَصْلِ النُّورَانِيَّةِ وَلَمْعَةِ الْقَبْضَةِ الرَّحْمَانِيَّةِ وَاَفْضَلِ الْخَلِيقَةِ الْاِنْسَانِيَّةِ وَاَشْرَفِ الصُّورَةِ الْجِسْمَانِيَّةِ وَمَعْدِنِ الْاَسْرَارِ الرَّبَّانِيَّةِ وَخَزَائِنِ الْعُلُومِ الْاِصْطِفَائِيَّةِ، صَاحِبِ الْقَبْضَةِ الْاَصْلِيَّةِ وَالْبَهْجَةِ السَّنِيَّةِ وَالرُّتْبَةِ الْعَلِيَّةِ. مَنِ انْدَرَجَتِ النَّبِيُّونَ تَحْتَ لِوَائِهِ فَهُمْ مِنْهُ وَاِلَيْهِ. وَصَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ وَعَلٰى اٰلِهِ وَصَحْبِهِ عَدَدَ مَا خَلَقْتَ وَرَزَقْتَ وَاَمَتَّ وَاَحْيَيْتَ اِلٰى يَوْمِ تَبْعَثُ مَنْ اَفْنَيْتَ وَسَلِّمْ تَسْلِيمًا كَثِيرًا وَالْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ.","latin":"Allâhümme salli ve sellim ve bârik alâ seyyidinâ ve mevlânâ Muhammedin şeceratil-aslin-nûrâniyyeti ve lem‘atil-kabdatir-rahmâniyyeti ve efdalil-halîkatil-insâniyyeti ve eşrefis-sûratil-cismâniyyeti ve ma‘dinil-esrârir-rabbâniyyeti ve hazâinil-ulûmil-istıfâiyyeti sâhibil-kabdatil-asliyyeti vel-behcetis-seniyyeti ver-rutbetil-aliyyeti meninderacetin-nebiyyûne tahte livâihî fehüm minhü ve ileyh. Ve salli ve sellim ve bârik aleyhi ve alâ âlihî ve sahbihî adede mâ halakte ve razakte ve emette ve ahyeyte ilâ yevmi teb‘asü men efneyte ve sellim teslîmen kesîrâ vel-hamdü lillâhi Rabbil-âlemîn.","meaning":"Allah’ım! Nurânî aslın ağacı, Rahmânî kabzanın parıltısı, insan olarak yaratılmışların en üstünü, cismânî suretlerin en şereflisi, Rabbânî sırların madeni, seçilmişlik ilimlerinin hazineleri; aslî kabzanın, parlak güzelliğin ve yüce rütbenin sahibi olan Efendimiz ve Mevlâmız Muhammed’e (sallallahu aleyhi ve sellem) salât, selâm ve bereket ihsan eyle. Peygamberler onun sancağı altında toplanmıştır; onlar ondandır ve ona yönelirler. Yarattıklarının, rızık verdiklerinin, öldürdüklerinin ve dirilttiklerinin sayısınca, yok ettiklerini yeniden dirilteceğin güne kadar ona, ailesine ve ashabına salât, selâm ve bereket ihsan eyle. Bolca selâm ihsan eyle. Hamd âlemlerin Rabbi Allah’a mahsustur.","cat":"derleme","note":"Ahmed Zeynî Dahlân, Ahmed el-Bedevî’ye nispet edilen salavat hakkında birçok ârifin nurların ortaya çıkmasına ve sırların açılmasına vesile olduğunu anlattığını kaydeder. Sabah namazından sonra üç, akşamdan sonra üç defa okumaya devam edilmesine dair söz aktarır.","source":"Nebhânî, Efdalü’s-Salavât, 34.","arabicDraft":false,"previousArabic":"اللهم صل و سلم و بارك على سيدنا و ماولانا محمد شاجاراتيل اسلين نورانياتي و لاماتيل كابداتير راهمانياتي و افداليل هالكاتيل ينسانياتي و اشرافيسوراتيل جيسمانياتي و مادانيل اسرارير راببانياتي و هازاينيل ولوميل استيفاياتي, ساهيبيل كابداتيل اسلياتي و باهجاتيس سانياتي وارروتباتيل الياتي. اننابيونا تاهتا ليوايهي فاهوم مينهو و يلايهي. و صل و سلم و بارك الايهي و على اليهي و ساهبيهي عدد ما هالاكتا و رازاكتا و اماتتا و اهيايتا إلى ياومي تاباسو مان افنايتا.","submittedArabic":"اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلٰى سَيِّدِنَا وَمَوْلَانَا مُحَمَّدٍ شَجَرَةِ الْاَصْلِ النُّورَانِيَّةِ وَلَمْعَةِ الْقَبْضَةِ الرَّحْمَانِيَّةِ وَاَفْضَلِ الْخِلْقَةِ الْاِنْسَانِيَّةِ وَاَشْرَفِ الصُّورَةِ الْجِسْمَانِيَّةِ وَمَعْدِنِ الْاَسْرَارِ الرَّبَّانِيَّةِ وَخَزَائِنِ الْعُلُومِ الْاِصْطِفَائِيَّةِ، صَاحِبِ الْقَبْضَةِ الْاَصْلِيَّةِ وَالْبَهْجَةِ السَّنِيَّةِ وَالرُّتْبَةِ الْعَلِيَّةِ. اَلنَّبِيُّونَ تَحْتَ لِوَائِهِ فَهُمْ مِنْهُ وَاِلَيْهِ. وَصَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ وَعَلٰى اٰلِهِ وَصَحْبِهِ عَدَدَ مَا خَلَقْتَ وَرَزَقْتَ وَاَمَتَّ وَاَحْيَيْتَ اِلٰى يَوْمِ تَبْعَثُ مَنْ اَفْنَيْتَ.","source_note":"","displayNumber":71},{"id":"koleksiyon90","name":"Mihnet ve Belâlardan Kurtuluş / Salât-ı Tüncînâ","aliases":"Orijinal liste: 90","arabic":"اَللّٰهُمَّ صَلِّ وَسَلِّمْ عَلٰى سَيِّدِنَا مُحَمَّدٍ وَعَلٰى اٰلِ سَيِّدِنَا مُحَمَّدٍ صَلَاةً تُنْجِينَا بِهَا مِنْ جَمِيعِ الْمِحَنِ وَالْإِحَنِ وَالْاَهْوَالِ وَالْبَلِيَّاتِ. وَتُسَلِّمُنَا بِهَا مِنْ جَمِيعِ الْفِتَنِ وَالْاَسْقَامِ وَالْاٰفَاتِ. وَتُطَهِّرُنَا بِهَا مِنْ جَمِيعِ الْعُيُوبِ وَالسَّيِّئَاتِ. وَتَغْفِرُ لَنَا بِهَا مِنْ جَمِيعِ الذُّنُوبَاتِ. وَتَقْضِي لَنَا بِهَا جَمِيعَ مَا نَطْلُبُهُ مِنَ الْحَاجَاتِ. وَتَرْفَعُنَا بِهَا عِنْدَكَ اَعْلَى الدَّرَجَاتِ. وَتُبَلِّغُنَا بِهَا اَقْصَى الْغَايَاتِ مِنْ جَمِيعِ الْخَيْرَاتِ فِي الْحَيَاةِ وَبَعْدَ الْمَمَاتِ. يَا اَرْحَمَ الرَّاحِمِينَ اِرْحَمْنَا.","latin":"Allâhümme salli ve sellim alâ seyyidinâ Muhammedin ve alâ âli seyyidinâ Muhammedin salâten tüncînâ bihâ min cemîil mihani vel-ihani vel ahvâli vel beliyyât. Ve tüsellimünâ bihâ min cemîil fiteni vel eskâmi vel âfâti. Ve tütahhirunâ bihâ min cemîil uyûbi vesseyyiâti. Ve tağfiru lenâ bihâ min cemîiz zünûbât. Ve takdî lenâ bihâ cemîa mâ natlubuhu minel hâcât. Ve terfeunâ bihâ ındeke a’ledderacât. Ve tübelliğunâ bihâ aksal gâyât min cemîil hayrâti fil hayâti ve ba’del memât. Yâ Erhamerrâhimîn irhamnâ.","meaning":"Allah'ım! Efendimiz Muhammed'e (sallallahu aleyhi ve sellem) ve ailesine öyle bir salât ve selâm eyle ki onun vesilesiyle bizi bütün sıkıntılardan, kin ve düşmanlıklardan, korkulardan ve belâlardan kurtarasın; bütün fitnelerden, hastalıklardan ve afetlerden selâmete çıkarasın; bütün kusurlardan ve kötülüklerden arındırasın; bütün günahlarımızı bağışlayasın; ihtiyaçlardan talep ettiğimiz her şeyi karşılayasın; katında bizi en yüksek derecelere yükseltesin; hayatta ve ölümden sonra bütün hayırlardan en ileri gayelere eriştiresin. Ey merhametlilerin en merhametlisi! Bize merhamet et.","cat":"derleme","note":"Yûsuf en-Nebhânî, “Allahümme salli ve sellim alâ seyyidinâ Muhammed... salâten tüncînâ bihâ...” diye başlayan salavatı Abdülkadir Geylânî’ye nispet ettiği Salât-ı Kübrâ içinde verir.","source":"Nebhânî, Saâdetü’d-Dâreyn, 8. bölüm, Abdülkadir Geylânî’nin Salât-ı Kübrâ’sı; Efdalü’s-Salavât, 70. salavat.","arabicDraft":false,"previousArabic":"اللهم صل و سلم على سيدنا محمد و على الي سيدنا محمد صلاة تونجينا بيها من جامييل ميهاني وال يهاني وال اهوالي وال باليات. و توسالليمونا بيها من جامييل فيتاني وال اسكامي وال افاتي. و توتاههيرونا بيها من جامييل ويوبي واسايياتي. و تاغفيرو لانا بيها من جامييز زونوبات. و تاكدي لانا بيها جاميا ما ناتلوبوهو مينال هاجات. و تارفاونا بيها انداكا الادداراجات. و توبالليغونا بيها اكسال غايات من جامييل هايراتي في هاياتي و بادال مامات. يا ارهامارراهيمين يرهامنا.","submittedArabic":"اَللّٰهُمَّ صَلِّ وَسَلِّمْ عَلٰى سَيِّدِنَا مُحَمَّدٍ وَعَلٰى اٰلِ سَيِّدِنَا مُحَمَّدٍ صَلَاةً تُنْجِينَا بِهَا مِنْ جَمِيعِ الْمِحَنِ وَالْاِهَانِ وَالْاَهْوَالِ وَالْبَلِيَّاتِ. وَتُسَلِّمُنَا بِهَا مِنْ جَمِيعِ الْفِتَنِ وَالْاَسْقَامِ وَالْاٰفَاتِ. وَتُطَهِّرُنَا بِهَا مِنْ جَمِيعِ الْعُيُوبِ وَالسَّيِّئَاتِ. وَتَغْفِرُ لَنَا بِهَا مِنْ جَمِيعِ الذُّنُوبَاتِ. وَتَقْضِي لَنَا بِهَا جَمِيعَ مَا نَطْلُبُهُ مِنَ الْحَاجَاتِ. وَتَرْفَعُنَا بِهَا عِنْدَكَ اَعْلَى الدَّرَجَاتِ. وَتُبَلِّغُنَا بِهَا اَقْصَى الْغَايَاتِ مِنْ جَمِيعِ الْخَيْرَاتِ فِي الْحَيَاةِ وَبَعْدَ الْمَمَاتِ. يَا اَرْحَمَ الرَّاحِمِينَ اِرْحَمْنَا.","source_note":"","displayNumber":72},{"id":"koleksiyon92","name":"Salât-ı Zâtü’l-Mutalsem","aliases":"Orijinal liste: 92","arabic":"اللَّهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَى طَلْعَةِ الذَّاتِ الْمُطَلْسَمِ وَالْغَيْثِ الْمُطَمْطَمِ وَالْكَمَالِ الْمُكَتَّمِ لَاهُوتِ الْجَمَالِ وَنَاسُوتِ الْوِصَالِ وَطَلْعَةِ الْحَقِّ هُوِيَّةِ إِنْسَانِ الْأَزَلِ فِي نَشْرِ مَنْ لَمْ يَزَلْ مَنْ أَقَمْتَ بِهِ نَوَاسِيتَ الْفَرْقِ إِلَى طُرُقِ الْحَقِّ فَصَلِّ اللَّهُمَّ بِهِ مِنْهُ عَلَيْهِ وَسَلِّمْ تَسْلِيمًا كَثِيرًا وَالْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ.","latin":"Allâhümme salli ve sellim ve bârik alâ tal‘atiz-zâtil-mutalsemi vel-ğaysil-mutamtami vel-kemâlil-mükettemi lâhûtil-cemâli ve nâsûtil-visâli ve tal‘atil-hakkı hüviyyeti insânil-ezeli fî neşri men lem yezel men ekamte bihî nevâsîtel-farkı ilâ turukıl-hakk. Fe-salli Allâhümme bihî minhü aleyhi ve sellim teslîmen kesîrâ vel-hamdü lillâhi Rabbil-âlemîn.","meaning":"Allah’ım! Sırrı örtülü zâtın görünüşüne, engin rahmet yağmuruna, gizli kemale, cemâlin lâhûtuna ve kavuşmanın nâsûtuna; Hakk’ın görünüşü ve ezel insanının hüviyetine salât, selâm ve bereket ihsan eyle. O, ezelî olanın yayılışında, ayrılık âleminin insanî suretlerini kendisiyle hak yollarına yönelttiğin zâttır. Allah’ım! Onunla, ondan ona salât eyle ve bolca selâm ihsan eyle. Hamd âlemlerin Rabbi Allah’a mahsustur.","cat":"derleme","note":"","source":"Nebhânî, Saâdetü’d-Dâreyn, 8. bölüm, 64.","arabicDraft":false,"previousArabic":"اللهم صل و سلم و بارك الاتتالاتيل زاتيل موتالسامي والغايسيل موتامتامي وال كاماليل موكاتتامي لاهوتيل جامالي و ناسوتيل ويسالي تالاتيل الحق كاسيبيل ينسانيل ازاليي في ناشرين لام يازال في غابي ناسوتيل ويساليل اكرابي. اللهم صل بيهي مينهو فيهي الايهي و على اليهي و ساهبيهي و سلم تاسليمان.","submittedArabic":"اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَى الطَّلْعَةِ الذَّاتِ الْمُطَلْسَمِ وَالْغَيْثِ الْمُطَمْطَمِ وَالْكَمَالِ الْمُكَتَّمِ لَاهُوتِ الْجَمَالِ وَنَاسُوتِ الْوِصَالِ طَلْعَةِ الْحَقِّ كَثِيبِ الْاِنْسَانِ الْاَزَلِيِّ فِي نَشْرِ مَنْ لَمْ يَزَلْ فِي غَابِ نَاسُوتِ الْوِصَالِ الْاَقْرَبِ. اَللّٰهُمَّ صَلِّ بِهِ مِنْهُ فِيهِ عَلَيْهِ وَعَلٰى اٰلِهِ وَصَحْبِهِ وَسَلِّمْ تَسْلِيماً.","source_note":"","displayNumber":73},{"id":"koleksiyon107","name":"Hâurrahmeti Salavatı","aliases":"Orijinal liste: 107","arabic":"اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ حَاءِ الرَّحْمَةِ وَمِيمِ الْمُلْكِ وَدَالِ الدَّوَامِ، السَّيِّدِ الْكَامِلِ الْفَاتِحِ الْخَاتِمِ، عَدَدَ مَا فِي عِلْمِكَ كَائِنٌ أَوْ قَدْ كَانَ، كُلَّمَا ذَكَرَكَ وَذَكَرَهُ الذَّاكِرُونَ، وَكُلَّمَا غَفَلَ عَنْ ذِكْرِكَ وَذِكْرِهِ الْغَافِلُونَ، صَلَاةً دَائِمَةً بِدَوَامِكَ، بَاقِيَةً بِبَقَائِكَ، لَا مُنْتَهَى لَهَا دُونَ عِلْمِكَ، إِنَّكَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ.","latin":"Allâhümme salli alâ seyyidinâ Muhammedin hâir-rahmeti ve mîmil-mülki ve dâlid-devâmi, es-seyyidil-kâmilil-fâtihil-hâtimi. Adede mâ fî ilmike kâinün ev kad kâne. Küllemâ zekereke ve zekerehüz-zâkirûn, ve küllemâ ğafele an zikrike ve zikrihil-ğâfilûn. Salâten dâimeten bi-devâmike, bâkiyeten bi-bekâike, lâ müntehâ lehâ dûne ilmike. İnneke alâ külli şey’in kadîr.","meaning":"Allah’ım! Rahmetin Hâ harfi, mülkün Mîm harfi ve devamlılığın Dâl harfi ile vasıflandırılan; kâmil, açıcı ve sonlandırıcı olan Peygamber Efendimiz Muhammed’e (sallallahu aleyhi ve sellem) salât eyle. Senin ilminde bulunan ve geçmişte var olmuş şeylerin sayısınca; Seni ve Peygamber Efendimizi ananlar her andığında, gafiller Seni ve O’nu anmaktan her gaflete düştüğünde O’na salât eyle. Senin devamlılığınla devam eden, Senin bekânla bâki kalan, sınırını ancak Senin ilminin bildiği bir salât ihsan eyle. Şüphesiz Senin her şeye gücün yeter.","cat":"derleme","note":"Bu salavatın yakın bir şekli, Yûsuf en-Nebhânî’nin Saâdetü’d-Dâreyn adlı eserinin sekizinci bölümünde, Ahmed el-Mellevî’nin derlediği salavatlarla ilişkili metinler arasında yer alır. Hâü’r-rahmeti, Mîmü’l-mülki ve Dâlü’d-devâmi ifadeleri harf adlarıdır.","source":"Yûsuf en-Nebhânî, Saâdetü’d-Dâreyn, sekizinci bölüm.","arabicDraft":false,"previousArabic":"اللهم صل و سلم على سيدنا و ماولانا محمد هاورراهماتي و ميمال مولكي و داللودداوامي اساييدول كاميلول فاتيهول هاتيمو عدد ما في يلميكا كاينون او كاد كانا كوللاما زاكاراكا و زاكاراهوززاكيرون و كوللاما غافالا ان ذكرك و زيكريهيل غافيلون. صلاة دايماتان بدوامك باكيياتان بيباكايكا لا مونتاها لاها دونا يلميكا إنك على كل شايين كادير.","submittedArabic":"اَللّٰهُمَّ صَلِّ وَسَلِّمْ عَلٰى سَيِّدِنَا وَمَوْلَانَا مُحَمَّدٍ حَاءِ الرَّحْمَةِ وَمِيمِ الْمُلْكِ وَدَالِ الدَّوَامِ اَلسَّيِّدِ الْكَامِلِ الْفَاتِحِ الْخَاتِمِ عَدَدَ مَا فِي عِلْمِكَ كَائِنٌ اَوْ قَدْ كَانَ كُلَّمَا ذَكَرَكَ وَذَكَرَهُ الذَّاكِرُونَ وَكُلَّمَا غَفَلَ عَنْ ذِكْرِكَ وَذِكْرِهِ الْغَافِلُونَ. صَلَاةً دَائِمَةً بِدَوَامِكَ بَاقِيَةً بِبَقَائِكَ لَا مُنْتَهٰى لَهَا دُونَ عِلْمِكَ اِنَّكَ عَلٰى كُلِّ شَيْءٍ قَدِيرٌ.","source_note":"","displayNumber":74},{"id":"koleksiyon123","name":"Tevessül ve Ebedî Salavat","aliases":"Orijinal liste: 123","arabic":"اللَّهُمَّ بِكَ تَوَسَّلْتُ وَمِنْكَ سَأَلْتُ وَفِيكَ لَا فِي شَيْءٍ سِوَاكَ رَغِبْتُ، لَا أَسْأَلُ مِنْكَ سِوَاكَ وَلَا أَطْلُبُ مِنْكَ إِلَّا إِيَّاكَ.\nاللَّهُمَّ وَأَتَوَسَّلُ إِلَيْكَ فِي قَبُولِ ذَلِكَ بِالْوَسِيلَةِ الْعُظْمَى وَالْفَضِيلَةِ الْكُبْرَى سَيِّدِنَا مُحَمَّدًا الْمُصْطَفَى وَالصَّفِيَّ الْمُرْتَضَى وَالنَّبِيَّ الْمُجْتَبَى، وَبِهِ أَسْأَلُكَ أَنْ تُصَلِّيَ عَلَيْهِ صَلَاةً أَبَدِيَّةً دَيْمُومِيَّةً قَيُّومِيَّةً إِلَهِيَّةً رَبَّانِيَّةً، بِحَيْثُ يَشْهَدُ لِي ذَلِكَ فِي عَيْنِ كَمَالِهِ بِشَهَادَةِ مَعَارِفِ ذَاتِهِ، وَعَلَى آلِهِ وَصَحْبِهِ كَذَلِكَ، فَإِنَّكَ وَلِيُّ ذَلِكَ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ الْعَلِيِّ الْعَظِيمِ.","latin":"Allâhümme bike tevesseltü ve minke seeltü ve fîke lâ fî şey'in sivâke rağibtü. Lâ es'elü minke sivâke ve lâ atlubü minke illâ iyyâke.\nAllâhümme ve etevesselü ileyke fî kabûli zâlike bil-vesîletil-uzmâ vel-fadîletil-kübrâ, seyyidinâ Muhammedenil-Mustafâ ves-safiyyel-murtadâ ven-nebiyyel-müctebâ.\nVe bihî es'elüke en tusalliye aleyhi salâten ebediyyeten deymûmiyyeten kayyûmiyyeten ilâhiyyeten rabbâniyyeten.\nBi-haysü yeşhedü lî zâlike fî ayni kemâlihî bi-şehâdeti meârifi zâtihî.\nVe alâ âlihî ve sahbihî kezâlike. Fe inneke veliyyü zâlike. Ve lâ havle ve lâ kuvvete illâ billâhil-aliyyil-azîm.","meaning":"Allah’ım! Sana vesileyle yöneldim, yalnız Senden istedim. Senden başka hiçbir şeye değil, yalnız Sana rağbet ettim. Senden, Senden başkasını istemiyorum; yalnız Seni talep ediyorum.\nAllah’ım! Bu dileğimin kabulü için en büyük vesile ve en yüce fazilet sahibi olan; seçilmiş, razı olunmuş, seçkin Peygamber Efendimiz Muhammed’i (sallallahu aleyhi ve sellem) vesile kılarak Sana yöneliyorum.\nO'nun vesilesiyle Senden, Peygamber Efendimize ebedî, sürekli, her şeyi ayakta tutan kudretinle ilişkili, ilâhî ve Rabbânî bir salât ihsan etmeni diliyorum.\nÖyle bir salât ki, O'nun kemalinin hakikatinde, zâtına ilişkin mârifetlerin şahitliğiyle bu salât benim lehime şahitlik etsin.\nPeygamber Efendimizin ailesine ve ashabına da aynı şekilde salât ihsan eyle.\nŞüphesiz bunu gerçekleştirecek olan Sensin. Güç ve kuvvet ancak yüce ve azamet sahibi Allah'ın yardımıyladır.","cat":"derleme","note":"","source":"Nebhânî, Saâdetü’d-Dâreyn, 8. bölüm, 41, Muhammed Vefâ eş-Şâzelî salavatı.","arabicDraft":false,"previousArabic":"اللهم بيكا تاواسالتو و يلايكا تاواججاهتو و مينكا ساالتو و فيكا لا في اهادين سيواكا راغيبتو. لا اسالوكا سيواكا و لا اتلوبو مينكا يللا ياكا. اللهم و اتاواسالو يلايكا في كابولي زاليكا بيل واسيلاتيل وزما وال فازيلاتيل كوبرا وال هابيبيل ادنا واننابييل موجتابا محمد ساللاللاهو الايهي و ساللام. و بيهي اسالوكا ان توساللييا الايهي صلاة ابادياتان سارمادياتان ازالياتان يلاهياتان كايومياتان راببانياتان. و لا هاولا و لا كووواتا يللا بيللاهيل الييل ازيم.","submittedArabic":"اَللّٰهُمَّ بِكَ تَوَسَّلْتُ وَاِلَيْكَ تَوَجَّهْتُ وَمِنْكَ سَاَلْتُ وَفِيكَ لَا فِي اَحَدٍ سِوَاكَ رَغِبْتُ. لَا اَسْاَلُكَ سِوَاكَ وَلَا اَطْلُبُ مِنْكَ اِلَّا اِيَّاكَ. اَللّٰهُمَّ وَاَتَوَسَّلُ اِلَيْكَ فِي قَبُولِ ذٰلِكَ بِالْوَسِيلَةِ الْعُظْمٰى وَالْفَضِيلَةِ الْكُبْرٰى وَالْحَبِيبِ الْاَدْنٰى وَالنَّبِيِّ الْمُجْتَبٰى مُحَمَّدٍ صَلَّى اللّٰهُ عَلَيْهِ وَسَلَّمَ. وَبِهِ اَسْاَلُكَ اَنْ تُصَلِّيَ عَلَيْهِ صَلَاةً اَبَدِيَّةً سَرْمَدِيَّةً اَزَلِيَّةً اِلٰهِيَّةً قَيُّومِيَّةً رَبَّانِيَّةً. وَلَا حَوْلَ وَلَا قُوَّةَ اِلَّا بِاللّٰهِ الْعَلِيِّ الْعَظِيمِ.","source_note":"","displayNumber":75},{"id":"koleksiyon125","name":"Borçtan ve Fakirlikten Kurtuluş Salavatı","aliases":"Orijinal liste: 125","arabic":"اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ عَبْدِكَ وَرَسُولِكَ نَبِيِّ الرَّحْمَةِ وَعَلٰى اٰلِهِ وَصَحْبِهِ وَسَلِّمْ عَدَدَ مَا اَحَاطَ بِهِ عِلْمُكَ وَجَرٰى بِهِ قَلَمُكَ وَنَفَذَ بِهِ حُكْمُكَ. اَللّٰهُمَّ يَا مَنْ بِيَدِهِ خَزَائِنُ السَّمَاوَاتِ وَالْاَرْضِ وَمَنْ يَقُولُ لِلشَّيْءِ كُنْ فَيَكُونُ، اَسْاَلُكَ اَنْ تُصَلِّيَ عَلٰى سَيِّدِنَا مُحَمَّدٍ وَاَنْ تُعَافِيَنِي مِنَ الدَّيْنِ وَتُغْنِيَنِي مِنَ الْفَقْرِ وَاَنْ تَرْزُقَنِي رِزْقًا حَلَالاً وَاسِعاً مُبَارَكاً فِيهِ. وَصَلِّ اللَّهُمَّ عَلَى سَيِّدِنَا مُحَمَّدٍ وَآلِهِ وَسَلِّمْ.","latin":"Allâhümme salli alâ seyyidinâ Muhammedin abdike ve resûlike nebiyyir rahmeti ve alâ âlihî ve sahbihî ve sellim adede mâ ehâta bihî ilmüke ve cerâ bihî kalemüke ve nefeze bihî hukmüke. Allâhümme yâ men biyedihî hazâinüs semâvâti vel ard ve men yekûlü lişşey’i kün feyekûn, es’elüke en tüsalliye alâ seyyidinâ Muhammedin ve en tüâfiyenî mined deyni ve tuğniyenî minel fakri ve en terzukanî rızkan halâlen vâsian mübâreken fîh. Ve salli Allâhümme alâ seyyidinâ Muhammedin ve âlihî ve sellim.","meaning":"Allah'ım! Kulun, elçin ve rahmet peygamberi Efendimiz Muhammed'e (sallallahu aleyhi ve sellem), ailesine ve ashabına; ilminin kuşattığı, kaleminin yazdığı ve hükmünün gerçekleştiği her şeyin sayısınca salât ve selâm eyle. Allah'ım! Ey göklerin ve yerin hazineleri elinde bulunan, bir şeye 'Ol!' dediğinde o şey oluveren Rabbim! Senden Efendimiz Muhammed'e salât etmeni, beni borçtan kurtarıp afiyet vermeni, beni fakirlikten kurtarıp zenginleştirmeni ve bana geniş, helâl, bereketli rızık vermeni diliyorum. Allah’ım! Efendimiz Muhammed’e ve ailesine salât ve selâm eyle.","cat":"derleme","note":"Bu salavat, Yûsuf en-Nebhânî’nin Saâdetü’d-Dâreyn adlı eserinde 128. salavat olarak yer almaktadır.\nSalavatın ardından borçtan kurtulmak, fakirlikten uzaklaşmak ve bereketli, helâl rızka kavuşmak için yapılan dualar bulunmaktadır.","source":"Nebhânî, Saâdetü’d-Dâreyn, 8. bölüm, 128.","arabicDraft":false,"previousArabic":"اللهم صل على سيدنا محمد عبدك و رسولك نابيير راهماتي و على اليهي و ساهبيهي و سلم عدد ما اهاتا بيهي يلموكا و جارا بيهي كالاموكا و نافازا بيهي هوكموكا. اللهم يا مان بيياديهي هازاينوس ساماواتي وال ارد و مان ياكولو ليشايي كون فاياكون, اسالوكا ان توساللييا على سيدنا محمد و ان توافيياني ميناد دايني و توغنيياني مينال فاكري و ان تارزوكاني هالالان واسيان موباراكان فيه.","submittedArabic":"اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ عَبْدِكَ وَرَسُولِكَ نَبِيِّ الرَّحْمَةِ وَعَلٰى اٰلِهِ وَصَحْبِهِ وَسَلِّمْ عَدَدَ مَا اَحَاطَ بِهِ عِلْمُكَ وَجَرٰى بِهِ قَلَمُكَ وَنَفَذَ بِهِ حُكْمُكَ. اَللّٰهُمَّ يَا مَنْ بِيَدِهِ خَزَائِنُ السَّمَاوَاتِ وَالْاَرْضِ وَمَنْ يَقُولُ لِلشَّيْءِ كُنْ فَيَكُونُ، اَسْاَلُكَ اَنْ تُصَلِّيَ عَلٰى سَيِّدِنَا مُحَمَّدٍ وَاَنْ تُعَافِيَنِي مِنَ الدَّيْنِ وَتُغْنِيَنِي مِنَ الْفَقْرِ وَاَنْ تَرْزُقَنِي حَلَالاً وَاسِعاً مُبَارَكاً فِيهِ.","source_note":"","displayNumber":76},{"id":"koleksiyon129","name":"Şefaat ve Muhabbet Duası","aliases":"Orijinal liste: 129","arabic":"اللَّهُمَّ إِنِّي أَسْأَلُكَ وَأَتَوَجَّهُ إِلَيْكَ بِحَبِيبِكَ الْمُصْطَفَى عِنْدَكَ يَا حَبِيبَنَا يَا مُحَمَّدُ إِنَّا نَتَوَسَّلُ بِكَ إِلَى رَبِّكَ فَاشْفَعْ لَنَا عِنْدَ الْمَوْلَى الْعَظِيمِ يَا نِعْمَ الرَّسُولُ الطَّاهِرُ. اللَّهُمَّ شَفِّعْهُ فِينَا بِجَاهِهِ عِنْدَكَ. اللَّهُمَّ وَاجْعَلْنَا مِنْ خَيْرِ الْمُصَلِّينَ وَالْمُسَلِّمِينَ عَلَيْهِ وَمِنْ خَيْرِ الْمُقَرَّبِينَ مِنْهُ وَالْوَارِدِينَ عَلَيْهِ وَمِنْ أَخْيَارِ الْمُحِبِّينَ فِيهِ وَالْمَحْبُوبِينَ لَدَيْهِ وَفَرِّحْنَا بِهِ فِي عَرَصَاتِ الْقِيَامَةِ وَاجْعَلْهُ لَنَا دَلِيلًا إِلَى جَنَّةِ النَّعِيمِ بِلَا مَشَقَّةٍ وَلَا مَضَرَّةٍ وَلَا مُنَاقَشَةِ الْحِسَابِ وَاجْعَلْهُ مُقْبِلًا عَلَيْنَا وَلَا تَجْعَلْهُ غَاضِبًا عَلَيْنَا وَاغْفِرْ لَنَا وَلِجَمِيعِ الْمُسْلِمِينَ الْأَحْيَاءِ مِنْهُمْ وَالْمَيِّتِينَ وَآخِرُ دَعْوَانَا أَنِ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ.","latin":"Allâhümme innî es’elüke ve eteveccehü ileyke bi-habîbikel-Mustafâ indek. Yâ habîbenâ yâ Muhammedü innâ netevesselü bike ilâ Rabbike feşfa‘ lenâ indel-mevlâl-azîm. Yâ ni‘mer-resûlüt-tâhir. Allâhümme şeffi‘hü fînâ bi-câhihî indek. Allâhümme vec‘alnâ min hayril-musallîne vel-müsellimîne aleyhi ve min hayril-mukarrabîne minhü vel-vâridîne aleyhi ve min ahyâril-muhibbîne fîhi vel-mahbûbîne ledeyhi ve ferrihnâ bihî fî arasâtil-kıyâmeti vec‘alhü lenâ delîlen ilâ cennetin-naîmi bilâ meşakkatin ve lâ madarratin ve lâ münâkaşetil-hisâbi vec‘alhü mukbilen aleynâ ve lâ tec‘alhü ğâdıben aleynâ vağfir lenâ ve li-cemîil-müslimînel-ahyâi minhüm vel-meyyitîn. Ve âhiru da‘vânâ enil-hamdü lillâhi Rabbil-âlemîn.","meaning":"Allah’ım! Senin katında seçilmiş sevgilin hürmetine Senden diliyor ve Sana yöneliyorum. Ey sevgili Peygamberimiz, ey Muhammed! Rabbine yönelmek için seni vesile ediniyoruz; yüce Mevlâ’nın katında bize şefaat et. Ey ne güzel ve tertemiz elçi! Allah’ım! Senin katındaki makamı hürmetine onun bizim hakkımızdaki şefaatini kabul et. Allah’ım! Bizi ona en güzel salât ve selâm getirenlerden, ona en yakın olanlardan, onun huzuruna gelenlerden, onu sevenlerin en hayırlılarından ve onun yanında sevilenlerden kıl. Kıyametin toplanma meydanlarında bizi onunla sevindir. Onu, meşakkat, zarar ve hesabın ince ince sorgulanması olmaksızın nimetler cennetine ulaşmamız için bize rehber kıl. Onun bize yönelmesini nasip et; bize öfkelenmesine izin verme. Bizi ve hayatta olan yahut vefat etmiş bütün Müslümanları bağışla. Son duamız: Hamd âlemlerin Rabbi Allah’a mahsustur.","cat":"derleme","note":"","source":"Nebhânî, Saâdetü’d-Dâreyn, 8. bölüm, 122; Delâilü’l-Hayrât’taki dua.","arabicDraft":false,"previousArabic":"اللهم ينني اسالوكا و اتاواججاهو يلايكا ب هابيبيكال موستافا انداكا. يا هابيبانا يا موهاممادو يننا ناتاواسالو بيكا إلى راببيكا فاشفا لانا اندال ماولال ازيم. اللهم واجالنا من هايريل موساللينا وال موساللامينا الايهي و من هايريل موكاررابينا مينهو و من اهياريل موهيببينا فيهي. واغفير لانا و لي جامييل موسليمينال اهياي مينهوم وال ماييتين. والهامدوليللاهي رب العالمين.","submittedArabic":"اَللّٰهُمَّ اِنِّي اَسْاَلُكَ وَاَتَوَجَّهُ اِلَيْكَ بِحَبِيبِكَ الْمُصْطَفٰى عِنْدَكَ. يَا حَبِيبَنَا يَا مُحَمَّدُ اِنَّا نَتَوَسَّلُ بِكَ اِلٰى رَبِّكَ فَاشْفَعْ لَنَا عِنْدَ الْمَوْلَى الْعَظِيمِ. اَللّٰهُمَّ وَاجْعَلْنَا مِنْ خَيْرِ الْمُصَلِّينَ وَالْمُسَلِّمِينَ عَلَيْهِ وَمِنْ خَيْرِ الْمُقَرَّبِينَ مِنْهُ وَمِنْ اَخْيَارِ الْمُحِبِّينَ فِيهِ. وَاغْفِرْ لَنَا وَلِجَمِيعِ الْمُسْلِمِينَ الْاَحْيَاءِ مِنْهُمْ وَالْمَيِّتِينَ. وَالْحَمْدُ لِلّٰهِ رَبِّ الْعَالَمِينَ.","source_note":"","displayNumber":77},{"id":"koleksiyon130","name":"İlmin Kuşattığı Adedince","aliases":"Orijinal liste: 130","arabic":"اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ عَبْدِكَ وَرَسُولِكَ النَّبِيِّ الْأُمِّيِّ وَعَلَى آلِهِ وَصَحْبِهِ وَسَلِّمْ كُلَّمَا ذَكَرَكَ الذَّاكِرُونَ وَغَفَلَ عَنْ ذِكْرِهِ الْغَافِلُونَ عَدَدَ مَا أَحَاطَ بِهِ عِلْمُ اللَّهِ وَجَرَى بِهِ قَلَمُ اللَّهِ وَنَفَذَ بِهِ حُكْمُ اللَّهِ وَوَسِعَهُ عِلْمُ اللَّهِ عَدَدَ كُلِّ شَيْءٍ وَأَضْعَافَ كُلِّ شَيْءٍ وَمِلْءَ كُلِّ شَيْءٍ عَدَدَ خَلْقِ اللَّهِ وَزِنَةَ عَرْشِ اللَّهِ وَرِضَا نَفْسِ اللَّهِ وَمِدَادَ كَلِمَاتِ اللَّهِ عَدَدَ مَا كَانَ وَمَا يَكُونُ وَمَا هُوَ كَائِنٌ فِي عِلْمِ اللَّهِ صَلَاةً تَسْتَغْرِقُ الْعَدَّ وَتُحِيطُ بِالْحَدِّ صَلَاةً دَائِمَةً بِدَوَامِ مُلْكِ اللَّهِ بَاقِيَةً بِبَقَاءِ اللَّهِ.","latin":"Allâhümme salli alâ seyyidinâ Muhammedin abdike ve resûliken-nebiyyil-ümmiyyi ve alâ âlihî ve sahbihî ve sellim küllemâ zekerakez-zâkirûne ve ğafele an zikrihil-ğâfilûn. Adede mâ ehâta bihî ilmullâhi ve cerâ bihî kalemullâhi ve nefeze bihî hukmullâhi ve vesiahû ilmullâhi adede külli şey’in ve ad‘âfe külli şey’in ve mil’e külli şey’in adede halkillâhi ve zinete arşillâhi ve rıdâ nefsillâhi ve midâde kelimâtillâhi adede mâ kâne ve mâ yekûnü ve mâ hüve kâinün fî ilmillâhi salâten testağrikul-adde ve tuhîtu bil-haddi salâten dâimeten bi-devâmi mülkillâhi bâkiyeten bi-bekâillâh.","meaning":"Allah’ım! Kulun, elçin ve ümmî peygamber olan Efendimiz Muhammed’e (sallallahu aleyhi ve sellem), ailesine ve ashabına; Seni ananlar her andığında ve gafiller onu anmaktan her gafil kaldığında salât ve selâm eyle. Allah’ın ilminin kuşattığı, kaleminin yazdığı, hükmünün gerçekleştiği ve ilminin kapsadığı her şeyin sayısınca; her şeyin sayısınca, katlarınca ve her şeyi dolduracak kadar; Allah’ın yarattıklarının sayısınca, arşının ağırlığınca, rızası ölçüsünce ve kelimelerinin mürekkebi miktarınca; geçmişte olanların, gelecekte olacakların ve Allah’ın ilminde var olanların sayısınca salât eyle. Sayıyı içine alan, sınırı kuşatan, Allah’ın mülkünün devamıyla devam eden ve O’nun bekâsıyla bâki kalan bir salât olsun.","cat":"derleme","note":"Ahmed ed-Dîrebî’nin Mücerrebât’ından aktarılan sözde, bazı kimselerin bu salavatı on gece boyunca yatarken yüz defa okuyup temiz ve kıbleye dönük olarak sağ yanına yatarsa Peygamber Efendimizi rüyasında göreceği nakledilir.","source":"Nebhânî, Saâdetü’d-Dâreyn, 8. bölüm, 7.","arabicDraft":false,"previousArabic":"اللهم صل على سيدنا محمد عبدك و راسوليكان النبي الأمي و على اليهي و ساهبيهي و سلم كوللاما زاكاراكاززاكيرون و غافالا ان زيكريهيل غافيلون عدد ما اهاتا بيهي يلموللاهي و جارا بيهي كالاموللاهي و نافازا بيهي هوكموللاهي, عدد هالكيللاهي و زيناتا ارشيللاهي و رادا نافسيللاهي و ميدادا كاليماتيللاهي, صلاة دايماتان بيداوامي مولكيللاه.","submittedArabic":"اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ عَبْدِكَ وَرَسُولِكَ النَّبِيِّ الْاُمِّيِّ وَعَلٰى اٰلِهِ وَصَحْبِهِ وَسَلِّمْ كُلَّمَا ذَكَرَكَ الذَّاكِرُونَ وَغَفَلَ عَنْ ذِكْرِهِ الْغَافِلُونَ عَدَدَ مَا اَحَاطَ بِهِ عِلْمُ اللّٰهِ وَجَرٰى بِهِ قَلَمُ اللّٰهِ وَنَفَذَ بِهِ حُكْمُ اللّٰهِ، عَدَدَ خَلْقِ اللّٰهِ وَزِنَةَ عَرْشِ اللّٰهِ وَرِضَا نَفْسِ اللّٰهِ وَمِدَادَ كَلِمَاتِ اللّٰهِ، صَلَاةً دَائِمَةً بِدَوَامِ مُلْكِ اللّٰهِ.","source_note":"","displayNumber":78},{"id":"koleksiyon143","name":"İsm-i A‘zam ve Salavat","aliases":"Orijinal liste: 143","arabic":"بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ. اللَّهُمَّ إِنِّي أَسْأَلُكَ بِاسْمِكَ الْأَعْظَمِ الْمَكْتُوبِ مِنْ وَجْهِكَ الْأَعْلَى الْمُؤَبَّدِ الدَّائِمِ الْبَاقِي الْمُخَلَّدِ فِي قَلْبِ نَبِيِّكَ وَرَسُولِكَ مُحَمَّدٍ وَأَسْأَلُكَ بِاسْمِكَ الْأَعْظَمِ الْوَاحِدِ بِوَحْدَةِ الْأَحَدِ الْمُتَعَالِي عَنْ وَحْدَةِ الْكَمِّ وَالْعَدَدِ الْمُقَدَّسِ عَنْ كُلِّ أَحَدٍ وَبِحَقِّ بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ قُلْ هُوَ اللَّهُ أَحَدٌ اللَّهُ الصَّمَدُ لَمْ يَلِدْ وَلَمْ يُولَدْ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ أَنْ تُصَلِّيَ عَلَى سَيِّدِنَا مُحَمَّدٍ سِرِّ حَيَاةِ الْوُجُودِ وَالسَّبَبِ الْأَعْظَمِ لِكُلِّ مَوْجُودٍ صَلَاةً تُثَبِّتُ فِي قَلْبِي الْإِيمَانَ وَتُحَفِّظُنِي الْقُرْآنَ وَتُفَهِّمُنِي مِنْهُ الْآيَاتِ وَتَفْتَحُ لِي بِهَا نُورَ الْجَنَّاتِ وَنُورَ النَّعِيمِ وَنُورَ النَّظَرِ إِلَى وَجْهِكَ الْكَرِيمِ وَعَلَى آلِهِ وَصَحْبِهِ وَسَلِّمْ.","latin":"Bismillâhirrahmânirrahîm. Allâhümme innî es’elüke bismikel-a‘zamil-mektûbi min vechikel-a‘lâl-müebbedid-dâimil-bâkıl-muhalledi fî kalbi nebiyyike ve resûlike Muhammed. Ve es’elüke bismikel-a‘zamil-vâhidi bi-vahdetil-ehadil-müteâlî an vahdetil-kemmi vel-adedil-mukaddesi an külli ehadin ve bi-hakkı Bismillâhirrahmânirrahîm. Kul hüvallâhu ehad. Allâhus-samed. Lem yelid ve lem yûled. Ve lem yekün lehû küfüven ehad. En tusalliye alâ seyyidinâ Muhammedin sirri hayâtil-vücûdi ves-sebebil-a‘zami li-külli mevcûdin salâten tüsebbitü fî kalbiyel-îmâne ve tuhaffizunil-Kur’âne ve tüfehhimünî minhül-âyâti ve teftehu lî bihâ nûral-cennâti ve nûran-naîmi ve nûran-nazari ilâ vechikel-kerîm. Ve alâ âlihî ve sahbihî ve sellim.","meaning":"Rahmân ve Rahîm olan Allah’ın adıyla. Allah’ım! Peygamberin ve elçin Muhammed’in (sallallahu aleyhi ve sellem) kalbinde bulunan; Senin yüce ve ebedî, devamlı, bâki ve sonsuz vechinden yazılmış en büyük isminle Senden istiyorum. Bir olanın birliğiyle tek olan, nicelik ve sayı birliğinden yüce ve her bir varlığa benzemekten münezzeh en büyük isminle; “Rahmân ve Rahîm olan Allah’ın adıyla. De ki: O Allah birdir. Allah Samed’dir. Doğurmamış ve doğurulmamıştır. Hiçbir şey O’na denk değildir.” âyetleri hürmetine Senden diliyorum: Varlığın hayat sırrı ve her var olanın en büyük sebebi olarak anılan Efendimiz Muhammed’e öyle bir salât eyle ki onunla kalbimde imanı sağlamlaştırsın, bana Kur’an’ı ezberletsin, onun âyetlerini anlamamı sağlasın; bana cennetlerin nurunu, nimetlerin nurunu ve Senin kerem sahibi vechine bakmanın nurunu açsın. Ailesine ve ashabına da salât ve selâm eyle.","cat":"derleme","note":"","source":"Nebhânî, Saâdetü’d-Dâreyn, 8. bölüm, 110.","arabicDraft":false,"previousArabic":"بيسميللاهيرراهمانيرراهيم. اللهم ينني اسالوكا بيسميكال ازاميل ماكتوبي من نور واجهيكال الال موابباد, في قلب نابييكا و رسولك محمد. و اسالوكا بيسميكال ازاميل واهادي ب واهداتيل اهاد. و ب الحق بيسميللاهيرراهمانيرراهيم, كول هوواللاهو اهاد, اللاهوساماد, لام ياليد و لام يولاد و لام ياكون لاهو كوفووان اهاد, ان توساللييا على سيدنا محمد سيرري هاياتيل ووجود, صلاة توساببيتو في كالبيل يمان و توهاففيزونيل كوران و توفاههيموني مينهول ايات. و على اليهي و ساهبيهي و سلم.","submittedArabic":"بِسْمِ اللّٰهِ الرَّحْمٰنِ الرَّحِيمِ. اَللّٰهُمَّ اِنِّي اَسْاَلُكَ بِاسْمِكَ الْاَعْظَمِ الْمَكْتُوبِ مِنْ نُورِ وَجْهِكَ الْاَعْلَى الْمُؤَبَّدِ، فِي قَلْبِ نَبِيِّكَ وَرَسُولِكَ مُحَمَّدٍ. وَاَسْاَلُكَ بِاسْمِكَ الْاَعْظَمِ الْوَاحِدِ بِوَحْدَةِ الْاَحَدِ. وَبِحَقِّ بِسْمِ اللّٰهِ الرَّحْمٰنِ الرَّحِيمِ، قُلْ هُوَ اللّٰهُ اَحَدٌ، اَللّٰهُ الصَّمَدُ، لَمْ يَلِدْ وَلَمْ يُولَدْ، وَلَمْ يَكُنْ لَهُ كُفُواً اَحَدٌ، اَنْ تُصَلِّيَ عَلٰى سَيِّدِنَا مُحَمَّدٍ سِرِّ حَيَاةِ الْوُجُودِ، صَلَاةً تُثَبِّتُ فِي الْقَلْبِ الْاِيمَانَ وَتُحَفِّظُنِي الْقُرْاٰنَ وَتُفَهِّمُنِي مِنْهُ الْاٰيَاتِ. وَعَلٰى اٰلِهِ وَصَحْبِهِ وَسَلِّمْ.","source_note":"","displayNumber":79},{"id":"koleksiyon149","name":"Künh Salavatı","aliases":"Orijinal liste: 149","arabic":"بِسْمِ اللّٰهِ الرَّحْمٰنِ الرَّحِيمِ. اَللّٰهُمَّ صَلِّ عَلَى الذَّاتِ الْكُنْهِ قِبْلَةِ وُجُوهِ تَجَلِّيَاتِ الْكُنْهِ عَيْنِ الْكُنْهِ فِي الْكُنْهِ الْجَامِعِ لِحَقَائِقِ كَمَالِ كُنْهِ الْكُنْهِ الْقَائِمِ بِالْكُنْهِ فِي الْكُنْهِ لِلْكُنْهِ. صَلَاةً لَا غَايَةَ لِكُنْهِهَا دُونَ الْكُنْهِ وَعَلٰى اٰلِهِ وَسَلِّمْ كَمَا يَنْبَغِي مِنَ الْكُنْهِ لِلْكُنْهِ. اَللّٰهُمَّ اَسْاَلُكَ بِنُورِ الْاَنْوَارِ الَّذِي هُوَ عَيْنُكَ لَا غَيْرُكَ اَنْ تُرِيَنِي وَجْهَ نَبِيِّكَ سَيِّدِنَا مُحَمَّدٍ صَلَّى اللّٰهُ تَعَالٰى عَلَيْهِ وَسَلَّمَ كَمَا هُوَ عِنْدَكَ. اٰمِينَ.","latin":"Bismillâhirrahmânirrahîm. Allâhümme salli alez-zâtil-künhi kıbleti vücûhi tecelliyâtil-künhi aynil-künhi fil-künhil-câmii li-hakâiki kemâli künhil-künhil-kâimi bil-künhi fil-künhi lil-künh. Salâten lâ gâyete li-künhihâ dûnel-künhi ve alâ âlihî ve sellim kemâ yenbeğî minel-künhi lil-künh. Allâhümme es’elüke bi-nûril-envârillezî hüve aynüke lâ ğayruke en türiyenî veche nebiyyike seyyidinâ Muhammedin sallallâhu teâlâ aleyhi ve sellem kemâ hüve indek. Âmîn.","meaning":"Rahmân ve Rahîm olan Allah’ın adıyla. Allah’ım! Künhün tecellilerinin yüzlerinin yöneldiği kıble olan, künh içinde künhün kaynağı, künhün özünün kemal hakikatlerini kendinde toplayan ve künhle, künhte, künh için kaim olan künh zâtına salât eyle. Künh dışında özünün son sınırı bulunmayan bir salât olsun. Ailesine de salât eyle ve künhten künhe yaraşır şekilde selâm ihsan eyle. Allah’ım! Senden başkası olmayıp Senin aynın olan nurların nuru hürmetine Senden, peygamberin Efendimiz Muhammed’in (sallallahu aleyhi ve sellem) yüzünü Senin katındaki hâliyle bana göstermeni diliyorum. Âmin.","cat":"derleme","note":"Ahmed İbn İdrîs’e nispet edilen on dört salavat arasında beşinci sırada yer alır.","source":"","arabicDraft":false,"previousArabic":"بيسميللاهيرراهمانيرراهيم. اللهم صل الاززاتيل كونهي كابلاتي ووجوهي تاجالليياتيل كونهي اينيل كونهي في كونهي الجاميا لي هاكايكي كامالي كونهيل كونهي. صلاة لا غاياتا لي كونهيها دونال كونهي و على اليهي و سلم. اللهم اسالوكا ب نوريل انواريللازي هووا اينوكا لا غايروكا ان توريياني واجها نابييكا سيدنا محمد ساللاللاهو تاالا الايهي و ساللام كاما هووا انداكا. امين.","submittedArabic":"بِسْمِ اللّٰهِ الرَّحْمٰنِ الرَّحِيمِ. اَللّٰهُمَّ صَلِّ عَلَى الذَّاتِ الْكُنْهِي قِبْلَةِ وُجُوهِ تَجَلِّيَاتِ الْكُنْهِ عَيْنِ الْكُنْهِ فِي الْكُنْهِ الْجَامِعِ لِحَقَائِقِ كَمَالِ كُنْهِ الْكُنْهِ. صَلَاةً لَا غَايَةَ لِكُنْهِهَا دُونَ الْكُنْهِ وَعَلٰى اٰلِهِ وَسَلِّيمْ. اَللّٰهُمَّ اَسْاَلُكَ بِنُورِ الْاَنْوَارِ الَّذِي هُوَ عَيْنُكَ لَا غَيْرُكَ اَنْ تُرِيَنِي وَجْهَ نَبِيِّكَ سَيِّدِنَا مُحَمَّدٍ صَلَّى اللّٰهُ تَعَالٰى عَلَيْهِ وَسَلَّمَ كَمَا هُوَ عِنْدَكَ. اٰمِينَ.","source_note":"","displayNumber":81},{"id":"koleksiyon157","name":"Safvetü’l-Enbiyâ","aliases":"Orijinal liste: 157","arabic":"اَللّٰهُمَّ صَلِّ عَلٰى اَفْضَلِ عِبَادِكَ مِنْ خَلْقِكَ وَصَفْوَتِكَ مِنْ اَنْبِيَائِكَ الذَّاتِ الْمُكَمَّلَةِ وَالرَّحْمَةِ الْمُرْسَلَةِ الْمُفَضَّلَةِ، سَيِّدِنَا وَنَبِيِّنَا مُحَمَّدٍ وَعَلٰى اٰلِهِ وَصَحْبِهِ وَوَارِثِيهِ وَحِزْبِهِ اَجْمَعِينَ مِلْءَ السَّمَاوَاتِ وَمِلْءَ الْاَرَضِينَ كُلَّمَا ذَكَرَكَ الذَّاكِرُونَ وَكُلَّمَا غَفَلَ عَنْ ذِكْرِهِ الْغَافِلُونَ.","latin":"Allâhümme salli alâ efdali ibâdike min halkıke ve safvetike min enbiyâikez-zâtil-mükemmeleti ver-rahmetil-mürseletil-müfaddaleti seyyidinâ ve nebiyyinâ Muhammedin ve alâ âlihî ve sahbihî ve vârisîhi ve hizbihî ecmaîne mil’es-semâvâti ve mil’el-aradîne küllemâ zekerakez-zâkirûne ve küllemâ ğafele an zikrihil-ğâfilûn.","meaning":"Allah’ım! Yarattıkların içinden kullarının en üstününe, peygamberlerinden seçtiğine; kemale erdirilmiş zât ve üstün kılınmış gönderilmiş rahmet olan Efendimiz ve Peygamberimiz Muhammed’e (sallallahu aleyhi ve sellem), ailesine, ashabına, vârislerine ve bütün topluluğuna, gökleri ve yerleri dolduracak kadar; Seni ananlar her andığında ve gafiller onu anmaktan her gafil kaldığında salât eyle.","cat":"derleme","note":"Nebhânî, Saâdetü’d-Dâreyn eserinin 8. bölümünde, 27. salavat olarak bu metnin yakın nüshasını Abdülkadir Geylânî’ye nispet eder. Açıklamada bunun Hizb-i Süryânî ve Fütûh-i Rabbânî’nin sonunda yer aldığı belirtilir.","source":"Nebhânî, Saâdetü’d-Dâreyn, 8. bölüm, 27.","arabicDraft":false,"previousArabic":"اللهم صل على افدالي يباديكا من هالكاكا و سافواتيكا من انبييايكاز زاتيل موكاممالا وارراهماتيل مورسالاتيل موفاددالا, سيدنا و نابيينا محمد و على اليهي و واريسيهي و هازبيهي أجمعين ميلاسساماواتي و ميلال ارادين كوللاما زاكاراكاززاكيرون و كوللاما غافالا ان زيكريهيل غافيلون.","submittedArabic":"اَللّٰهُمَّ صَلِّ عَلٰى اَفْضَلِ عِبَادِكَ مِنْ خَلْقِكَ وَصَفْوَتِكَ مِنْ اَنْبِيَائِكَ الذَّاتِ الْمُكَمَّلَةِ وَالرَّحْمَةِ الْمُرْسَلَةِ الْمُفَضَّلَةِ، سَيِّدِنَا وَنَبِيِّنَا مُحَمَّدٍ وَعَلٰى اٰلِهِ وَوَارِثِهِ وَحِزْبِهِ اَجْمَعِينَ مِلْءَ السَّمَاوَاتِ وَمِلْءَ الْاَرَضِينَ كُلَّمَا ذَكَرَكَ الذَّاكِرُونَ وَكُلَّمَا غَفَلَ عَنْ ذِكْرِهِ الْغَافِلُونَ.","source_note":"","displayNumber":82},{"id":"koleksiyon200","name":"Abdülganî en-Nablusî’ye Nispet Edilen Salavat","aliases":"Orijinal liste: 200","arabic":"اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ صَلَاتَكَ الْقَدِيمَةَ الْأَزَلِيَّةَ، الدَّائِمَةَ الْبَاقِيَةَ الْأَبَدِيَّةَ، الَّتِي صَلَّيْتَهَا فِي حَضْرَةِ عِلْمِكَ الْقَدِيمِ، الَّذِي أَنْزَلْتَهُ بِمَلَائِكَتِكَ فِي حَضْرَةِ كَلَامِكَ الْقُرْآنِ الْعَظِيمِ، فَقُلْتَ بِاللِّسَانِ الْمُحَمَّدِيِّ الرَّحِيمِ:\nإِنَّ اللَّهَ وَمَلَائِكَتَهُ يُصَلُّونَ عَلَى النَّبِيِّ.\nوَخَاطَبْتَنَا بِهَا مَعَ السَّلَامِ، تَتْمِيمًا لِلْإِكْرَامِ مِنْكَ لَنَا وَالْإِنْعَامِ، فَقُلْتَ:\nيَا أَيُّهَا الَّذِينَ آمَنُوا صَلُّوا عَلَيْهِ وَسَلِّمُوا تَسْلِيمًا.\nفَقُلْتُ امْتِثَالًا لِأَمْرِكَ، وَرَغْبَةً فِيمَا عِنْدَكَ مِنْ أَجْرِكَ:\nاللَّهُمَّ صَلِّ وَسَلِّمْ عَلَى سَيِّدِنَا مُحَمَّدٍ وَعَلَى آلِهِ وَأَصْحَابِهِ أَجْمَعِينَ، صَلَاةً دَائِمَةً بَاقِيَةً إِلَى يَوْمِ الدِّينِ، حَتَّى نَجِدَهَا وِقَايَةً لَنَا مِنْ نَارِ الْجَحِيمِ، وَمُوَصِّلَةً لِأَوَّلِنَا وَآخِرِنَا مَعْشَرَ الْمُؤْمِنِينَ إِلَى دَارِ النَّعِيمِ وَرُؤْيَةِ وَجْهِكَ الْكَرِيمِ، يَا عَظِيمُ.","latin":"Allâhümme salli alâ seyyidinâ Muhammedin salâtekel-kadîmetel-ezeliyyeted-dâimetel-bâkiyetel-ebediyye. Elletî salleytehâ fî hadrati ilmikel-kadîm. Ellezî enzeltehû bi-melâiketike fî hadrati kelâmikel-Kur’ânil-azîm. Fe kulte bil-lisânil-Muhammediyyir-rahîm:\nİnnallâhe ve melâiketehû yüsallûne alen-nebiyy.\nVe hâtabtenâ bihâ meas-selâmi, tetmîmen lil-ikrâmi minke lenâ vel-in’âmi, fe kulte:\nYâ eyyühellezîne âmenû sallû aleyhi ve sellimû teslîmâ.\nFe kultümtisâlen li-emrike, ve rağbeten fîmâ indeke min ecrike:\nAllâhümme salli ve sellim alâ seyyidinâ Muhammedin ve alâ âlihî ve ashâbihî ecmaîn. Salâten dâimeten bâkiyeten ilâ yevmid-dîn. Hattâ necidahâ vikâyeten lenâ min nâril-cahîm. Ve müvassıleten li-evvelinâ ve âhirinâ ma’şerel-mü’minîne ilâ dârin-naîmi ve rü’yeti vechikel-kerîm. Yâ Azîm.","meaning":"Allah’ım! Efendimiz Muhammed’e (sallallahu aleyhi ve sellem), Senin kadîm, ezelî, sürekli, bâki ve ebedî salâtınla salât eyle. Kadîm ilminin huzurunda ona ihsan ettiğin o salâtla salât eyle. O ilmini meleklerin vasıtasıyla kelâmın olan yüce Kur’an’da indirdin ve merhametli Muhammedî dil ile şöyle buyurdun:\n“Şüphesiz Allah ve melekleri Peygamber’e salât ederler.”\nBize olan ikram ve nimetini tamamlamak üzere, selâmla birlikte bu salâtı bize de emrederek şöyle hitap ettin:\n“Ey iman edenler! Siz de ona salât edin ve tam bir teslimiyetle selâm verin.”\nBen de emrine uyarak ve Senin katındaki mükâfata rağbet ederek şöyle dedim:\nAllah’ım! Efendimiz Muhammed’e (sallallahu aleyhi ve sellem), onun ailesine ve ashabının tamamına, hesap gününe kadar sürekli devam eden ve bâki kalan bir salât ve selâm ihsan eyle. Öyle ki bu salâtı bizim için cehennem ateşinden bir korunma vesilesi olarak bulalım. Biz müminler topluluğunun, ilkimizden sonuncumuza kadar hepimizi nimetler yurduna ve Senin kerem sahibi vechini görmeye ulaştıran bir vesile olsun. Ey azamet sahibi olan Allah’ım!","cat":"derleme","note":"","source":"Nebhânî, Efdalü’s-Salavât, 60.","arabicDraft":false,"previousArabic":"اللهم صل و سلم على سيدنا محمد سالاتاكال كاديماتال ازالياتاد دايماتال باكيياتال ابادياتا. اللاتي ساللايتاها في هادراتي يلميكال كاديم. ي̇نناللاها و مالايكاتاهو يوساللونا الاننابيي. يا ايوهاللازينا امانو ساللو الايهي و سالليمو تاسليما. اللهم صل و سلم على سيدنا محمد و على اليهي و اسهابيهي أجمعين صلاة دايماتان باكيياتان إلى ياوميددين. حتى ناجيداها ويكاياتان لانا من ناريل جاهيم و موسيلاتان إلى داريننايم. يا ازيم يا الله.","submittedArabic":"اَللّٰهُمَّ صَلِّ وَسَلِّيمْ عَلٰى سَيِّدِنَا مُحَمَّدٍ صَلَاتَكَ الْقَدِيمَةَ الْاَزَلِيَّةَ الدَّائِمَةَ الْبَاقِيَةَ الْاَبَدِيَّةَ. اَلَّتِي صَلَّيْتَهَا فِي حَضْرَةِ عِلْمِكَ الْقَدِيمِ. اِنَّ اللّٰهَ وَمَلَائِكَتَهُ يُصَلُّونَ عَلَى النَّبِيِّ يَا اَيُّهَا الَّذِينَ اٰمَنُوا صَلُّوا عَلَيْهِ وَسَلِّمُوا تَسْلِيماً. اَللّٰهُمَّ صَلِّ وَسَلِّيمْ عَلٰى سَيِّدِنَا مُحَمَّدٍ وَعَلٰى اٰلِهِ وَاَصْحَابِهِ اَجْمَعِينَ صَلَاةً دَائِمَةً بَاقِيَةً اِلٰى يَوْمِ الدِّينِ. حَتّٰى نَجِدَهَا وِقَايَةً لَنَا مِنْ نَارِ الْجَحِيمِ وَمُوصِلَةً اِلٰى دَارِ النَّعِيمِ. يَا عَظِيمُ يَا اَللّٰهُ.","source_note":"","displayNumber":83},{"id":"koleksiyon12","name":"Salât, Bereket ve Rahmet","aliases":"","arabic":"اللَّهُمَّ صَلِّ وَسَلِّمْ عَلَى النَّبِيِّ مُحَمَّدٍ حَتَّى لَا يَبْقَى مِنْ صَلَاتِكَ شَيْءٌ، وَبَارِكْ عَلَى النَّبِيِّ مُحَمَّدٍ حَتَّى لَا يَبْقَى مِنْ بَرَكَاتِكَ شَيْءٌ، وَارْحَمِ النَّبِيَّ مُحَمَّدًا حَتَّى لَا يَبْقَى مِنْ رَحْمَتِكَ شَيْءٌ.","latin":"Allâhümme salli ve sellim alen-nebiyyi Muhammedin hattâ lâ yebkâ min salâtike şey’. Ve bârik alen-nebiyyi Muhammedin hattâ lâ yebkâ min berekâtike şey’. Verhamin-nebiyye Muhammeden hattâ lâ yebkâ min rahmetike şey’.","meaning":"Allah’ım! Salâtından hiçbir şey kalmayıncaya kadar Peygamber Efendimiz Muhammed’e (sallallahu aleyhi ve sellem) salât ve selâm eyle. Bereketinden hiçbir şey kalmayıncaya kadar Peygamber Efendimiz Muhammed’e bereket ihsan eyle. Rahmetinden hiçbir şey kalmayıncaya kadar Peygamber Efendimiz Muhammed’e merhamet eyle.","cat":"derleme","note":"","source":"","source_note":" Türkçe anlam, mevcut Latin okunuş üzerinden hazırlanmıştır; özgün nüsha karşılaştırması bekleniyor.","arabicDraft":false},{"id":"koleksiyon15","name":"Cezâhü Annâ","aliases":"","arabic":"اللَّهُمَّ اجْزِ مُحَمَّدًا عَنَّا مَا هُوَ أَهْلُهُ","latin":"Allâhümmeczi Muhammeden annâ mâ hüve ehlüh.","meaning":"Allah’ım! Peygamber Efendimiz Muhammed’i (sallallahu aleyhi ve sellem) bizim adımıza, kendisinin layık olduğu şekilde mükâfatlandır.","cat":"derleme","note":"","source":"","source_note":"| Editoryal çalışma: Latin harfli okunuş esas alınarak Arapça metin hizalandı; özgün Arapça nüshayla doğrulama bekleniyor.","arabicDraft":false},{"id":"koleksiyon16","name":"Hayrel Cezâ","aliases":"","arabic":"اللَّهُمَّ اجْزِ سَيِّدَنَا مُحَمَّدًا عَنَّا خَيْرَ مَا جَزَيْتَ نَبِيًّا عَنْ أُمَّتِهِ","latin":"Allâhümmeczi seyyidenâ Muhammeden annâ hayra mâ cezeyte nebiyyen an ümmetih.","meaning":"Allah’ım! Efendimiz Muhammed’i (sallallahu aleyhi ve sellem), bir peygamberi ümmeti adına mükâfatlandırdığın en hayırlı karşılıkla bizim adımıza mükâfatlandır.","cat":"derleme","note":"","source":"","source_note":"| Editoryal çalışma: Latin harfli okunuş esas alınarak Arapça metin hizalandı; özgün Arapça nüshayla doğrulama bekleniyor.","arabicDraft":false},{"id":"koleksiyon21","name":"Semâvât ve Arz","aliases":"","arabic":"اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ مِلْءَ السَّمَاوَاتِ وَالْأَرْضِ وَمِلْءَ الْعَرْشِ الْعَظِيمِ","latin":"Allâhümme salli alâ seyyidinâ Muhammedin mil’es-semâvâti vel-ardı ve mil’el-arşil-azîm.","meaning":"Allah’ım! Gökleri, yeri ve yüce arşı dolduracak kadar Efendimiz Muhammed’e salât eyle.","cat":"derleme","note":"","source":"","arabicDraft":false},{"id":"koleksiyon30","name":"Binlerce Zerre Adedince","aliases":"","arabic":"اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ بِعَدَدِ كُلِّ ذَرَّةٍ أَلْفَ أَلْفِ مَرَّةٍ","latin":"Allâhümme salli alâ seyyidinâ Muhammedin bi-adedi külli zerretin elfe elfi merrah.","meaning":"Allah’ım! Her zerre sayısınca, milyonlarca defa Efendimiz Muhammed’e salât eyle.","cat":"derleme","note":"","source":"","arabicDraft":false},{"id":"koleksiyon32","name":"Kelâmımızın Başında ve Sonunda","aliases":"","arabic":"اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ فِي أَوَّلِ كَلَامِنَا وَصَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ فِي أَوْسَطِ كَلَامِنَا وَصَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ فِي آخِرِ كَلَامِنَا","latin":"Allâhümme salli alâ seyyidinâ Muhammedin fî evveli kelâminâ ve salli alâ seyyidinâ Muhammedin fî evsatı kelâminâ ve salli alâ seyyidinâ Muhammedin fî âhiri kelâminâ.","meaning":"Allah’ım! Sözümüzün başında, ortasında ve sonunda Efendimiz Muhammed’e salât eyle.","cat":"derleme","note":"","source":"","arabicDraft":false},{"id":"koleksiyon33","name":"Adede Mâ Alimte","aliases":"","arabic":"اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ عَدَدَ مَا عَلِمْتَ","latin":"Allâhümme salli alâ seyyidinâ Muhammedin adede mâ alimte.","meaning":"Allah’ım! Bildiğin şeylerin sayısınca Efendimiz Muhammed’e (sallallahu aleyhi ve sellem) salât eyle.","cat":"derleme","note":"","source":"","source_note":"| Editoryal çalışma: Latin harfli okunuş esas alınarak Arapça metin hizalandı; özgün Arapça nüshayla doğrulama bekleniyor.","arabicDraft":false},{"id":"koleksiyon55","name":"Abdike ve Habîbike","aliases":"","arabic":"اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ عَبْدِكَ وَنَبِيِّكَ وَحَبِيبِكَ وَرَسُولِكَ النَّبِيِّ الْأُمِّيِّ وَعَلَى آلِهِ وَصَحْبِهِ وَسَلِّمْ","latin":"Allâhümme salli alâ seyyidinâ Muhammedin abdike ve nebiyyike ve habîbike ve resûliken-nebiyyil-ümmiyyi ve alâ âlihî ve sahbihî ve sellim.","meaning":"Allah’ım! Kulun, peygamberin, sevgilin, elçin ve ümmî peygamber Efendimiz Muhammed’e, ailesine ve ashabına salât ve selâm eyle.","cat":"derleme","note":"","source":"","arabicDraft":false},{"id":"koleksiyon56","name":"Essalâtü Vesselâmü Aleyke","aliases":"","arabic":"الصَّلَاةُ وَالسَّلَامُ عَلَيْكَ يَا سَيِّدِي يَا رَسُولَ اللَّهِ خُذْ بِيَدِي قَلَّتْ حِيلَتِي أَدْرِكْنِي","latin":"Es-salâtü ves-selâmü aleyke yâ seyyidî yâ Resûlallâh. Huz bi-yedî kallet hîletî edriknî.","meaning":"Ey efendim, ey Allah’ın Resulü! Sana salât ve selâm olsun. Elimden tut; çarem azaldı, imdadıma yetiş.","cat":"derleme","note":"","source":"","arabicDraft":false},{"id":"koleksiyon84","name":"Bütün Enbiyâya Salavat","aliases":"","arabic":"اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى جَمِيعِ الْأَنْبِيَاءِ وَالْمُرْسَلِينَ","latin":"Allahümme salli alâ Muhammedin ve alâ cemîil Enbiyâi velmürselîn.","meaning":"Allah’ım! Efendimiz Muhammed’e ve bütün peygamberlerle elçilere salât eyle.","cat":"derleme","note":"","source":"","arabicDraft":false},{"id":"koleksiyon93","name":"Daimî Salavat","aliases":"","arabic":"اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ مَا دَامَتِ الصَّلَوَاتُ، وَصَلِّ عَلَى مُحَمَّدٍ مَا دَامَتْ بَرَكَاتُهُ، وَصَلِّ عَلَى جَسَدِ مُحَمَّدٍ فِي الْأَجْسَادِ، وَصَلِّ عَلَى رُوحِ مُحَمَّدٍ فِي الْأَرْوَاحِ، وَصَلِّ عَلَى قَبْرِ مُحَمَّدٍ فِي الْقُبُورِ، وَصَلِّ عَلَى تُرَابِ مُحَمَّدٍ فِي الْأَتْرَابِ، وَصَلِّ عَلَى جَمِيعِ الْأَنْبِيَاءِ وَالْمُرْسَلِينَ، وَالْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ.","latin":"Allâhümme salli alâ Muhammedin mâ dâmetis-salavât. Ve salli alâ Muhammedin mâ dâmet berekâtüh. Ve salli alâ cesedi Muhammedin fil-ecsâd. Ve salli alâ rûhi Muhammedin fil-ervâh. Ve salli alâ kabri Muhammedin fil-kubûr. Ve salli alâ türâbi Muhammedin fil-etrâb. Ve salli alâ cemîil-enbiyâi vel-mürselîn. Vel-hamdü lillâhi Rabbil-âlemîn.","meaning":"Allah’ım! Salavatlar devam ettiği müddetçe Efendimiz Muhammed’e salât eyle. Onun bereketleri devam ettiği müddetçe Efendimiz Muhammed’e salât eyle. Bedenler arasında Efendimiz Muhammed’in bedenine salât eyle. Ruhlar arasında Efendimiz Muhammed’in ruhuna salât eyle. Kabirler arasında Efendimiz Muhammed’in kabrine salât eyle. Topraklar arasında Efendimiz Muhammed’in toprağına salât eyle. Bütün peygamberlere ve elçilere salât eyle. Hamd âlemlerin Rabbi Allah’a mahsustur.","cat":"derleme","note":"","source":"","source_note":" Türkçe anlam, mevcut Latin okunuş üzerinden hazırlanmıştır; özgün nüsha karşılaştırması bekleniyor.","arabicDraft":false},{"id":"koleksiyon109","name":"Nebiyyil Ümmî ve Ehl-i Beyt","aliases":"","arabic":"اللَّهُمَّ صَلِّ وَسَلِّمْ عَلَى سَيِّدِنَا وَمَوْلَانَا مُحَمَّدٍ عَبْدِكَ وَنَبِيِّكَ وَرَسُولِكَ النَّبِيِّ الْأُمِّيِّ، وَعَلَى آلِهِ وَصَحْبِهِ وَأَهْلِ بَيْتِهِ عَدَدَ مَا عَلِمْتَ وَزِنَةَ مَا عَلِمْتَ وَمِلْءَ مَا عَلِمْتَ، صَلَاةً أَنْتَ لَهَا أَهْلٌ وَهُوَ لَهَا أَهْلٌ.","latin":"Allâhümme salli ve sellim alâ seyyidinâ ve mevlânâ Muhammedin abdike ve nebiyyike ve resûliken-nebiyyil-ümmiyyi ve alâ âlihî ve sahbihî ve ehli beytihî adede mâ alimte ve zinete mâ alimte ve mil’e mâ alimte salâten ente lehâ ehlün ve hüve lehâ ehl.","meaning":"Allah’ım! Kulun, peygamberin, elçin ve ümmî peygamber Efendimiz Muhammed’e; ailesine, ashabına ve Ehl-i Beyt’ine bildiğin şeylerin sayısınca, ağırlığınca ve dolusunca, sana ve ona layık olacak şekilde salât ve selam eyle.","cat":"derleme","note":"","source":"","source_note":" Türkçe anlam, mevcut Latin okunuş üzerinden hazırlanmıştır; özgün nüsha karşılaştırması bekleniyor.","arabicDraft":false},{"id":"koleksiyon140","name":"İlim ve Kelâm Adedince","aliases":"","arabic":"اللَّهُمَّ صَلِّ وَسَلِّمْ عَلَى سَيِّدِنَا مُحَمَّدٍ عَدَدَ مَا أَحَاطَ بِهِ عِلْمُكَ وَمَا جَرَى بِهِ كَلَامُكَ","latin":"Allâhümme salli ve sellim alâ seyyidinâ Muhammedin adede mâ ehâta bihî ilmüke ve mâ cerâ bihî kelâmük.","meaning":"Allah’ım! İlminin kuşattığı ve kelâmının kapsadığı şeylerin sayısınca Efendimiz Muhammed’e salât ve selâm eyle.","cat":"derleme","note":"","source":"","arabicDraft":false},{"id":"koleksiyon182","name":"İlmin Adedince","aliases":"","arabic":"اللَّهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَى سَيِّدِنَا مُحَمَّدٍ وَعَلَى آلِ سَيِّدِنَا مُحَمَّدٍ بِعَدَدِ عِلْمِكَ","latin":"Allâhümme salli ve sellim ve bârik alâ seyyidinâ Muhammedin ve alâ âli seyyidinâ Muhammedin bi-adedi ilmik.","meaning":"Allah’ım! İlminin sayısınca Efendimiz Muhammed’e ve ailesine salât, selâm ve bereket ihsan eyle.","cat":"derleme","note":"","source":"","arabicDraft":false},{"id":"koleksiyon186","name":"Milyon Salât ve Selâm","aliases":"","arabic":"أَلْفُ أَلْفِ صَلَاةٍ وَأَلْفُ أَلْفِ سَلَامٍ عَلَيْكَ يَا رَسُولَ اللَّهِ","latin":"Elfü elfi salâtin ve elfü elfi selâmin aleyke yâ Resûlallâh.","meaning":"Ey Allah’ın Resulü! Sana bir milyon salât ve bir milyon selâm olsun.","cat":"derleme","note":"","source":"","arabicDraft":false},{"id":"koleksiyon189","name":"Vahyin Emînine Selâm","aliases":"","arabic":"أَلْفُ أَلْفِ صَلَاةٍ وَأَلْفُ أَلْفِ سَلَامٍ عَلَيْكَ يَا أَمِينَ وَحْيِ اللَّهِ","latin":"Elfü elfi salâtin ve elfü elfi selâmin aleyke yâ emîne vahyillâh.","meaning":"Ey Allah’ın vahyinin emini! Sana bir milyon salât ve bir milyon selâm olsun.","cat":"derleme","note":"","source":"","arabicDraft":false},{"id":"koleksiyon194","name":"Nebiyyil Ümmiyyil Arabî","aliases":"","arabic":"اللَّهُمَّ صَلِّ وَسَلِّمْ عَلَى سَيِّدِنَا مُحَمَّدٍ النَّبِيِّ الْأُمِّيِّ الْعَرَبِيِّ الْقُرَشِيِّ الْهَاشِمِيِّ الْمَكِّيِّ الْمَدَنِيِّ، صَاحِبِ التَّاجِ وَالْمِعْرَاجِ، صَاحِبِ الشَّرِيعَةِ وَالْعَطَايَا، صَاحِبِ الْمَقَامِ الْمَحْمُودِ وَالْحَوْضِ الْمَوْرُودِ، صَاحِبِ السُّجُودِ لِلرَّبِّ الْمَعْبُودِ.","latin":"Allâhümme salli ve sellim alâ seyyidinâ Muhammedinin-nebiyyil-ümmiyyil-arabiyyil-kuraşiyyil-hâşimiyyil-mekkiyyil-medeniyyi sâhibit-tâci vel-mi‘râci sâhibiş-şerîati vel-atâyâ sâhibil-makâmil-mahmûdi vel-havdil-mevrûdi sâhibis-sücûdi lir-Rabbil-ma‘bûd.","meaning":"Allah’ım! Ümmî, Arap, Kureyşli, Hâşimî, Mekkeli ve Medineli peygamber Efendimiz Muhammed’e; taç ve miraç sahibi, şeriat ve ihsan sahibi, Makâm-ı Mahmûd ve kendisine varılan havuz sahibi, Rabbine secde eden peygambere salât ve selam eyle.","cat":"derleme","note":"","source":"","source_note":" Türkçe anlam, mevcut Latin okunuş üzerinden hazırlanmıştır; özgün nüsha karşılaştırması bekleniyor.","arabicDraft":false},{"id":"koleksiyon85","name":"Seyyidü’l-Kevneyn","aliases":"Orijinal liste: 85","arabic":"اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ سَيِّدِ الْكَوْنَيْنِ وَالثَّقَلَيْنِ وَالْفَرِيقَيْنِ، جَدِّ الْحَسَنِ وَالْحُسَيْنِ، مَحْبُوبِ رَبِّ الْمَشْرِقَيْنِ وَالْمَغْرِبَيْنِ. صَلَّى اللَّهُ عَلَى سَيِّدِنَا مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ وَالْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ.","latin":"Allâhümme salli alâ Muhammedin seyyidil-kevneyni ves-sekaleyni vel-ferîkayni ceddil-Haseni vel-Hüseyni mahbûbi Rabbil-meşrikayni vel-mağribeyn. Sallallâhu alâ seyyidinâ Muhammedin ve alâ âli Muhammedin vel-hamdü lillâhi Rabbil-âlemîn.","meaning":"Allah’ım! İki âlemin, insanlarla cinlerin ve iki topluluğun efendisi; Hasan ile Hüseyin’in dedesi, doğuların ve batıların Rabbinin sevgilisi Efendimiz Muhammed’e salât eyle. Efendimiz Muhammed’e ve ailesine salât olsun. Hamd âlemlerin Rabbi Allah’adır.","cat":"derleme","note":"","source":"","arabicDraft":false},{"id":"koleksiyon173","name":"Semâvât ve Arz Adedince","aliases":"Orijinal liste: 173","arabic":"اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ النَّبِيِّ الْأُمِّيِّ وَعَلَى آلِهِ وَصَحْبِهِ وَسَلِّمْ عَدَدَ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَمَا بَيْنَهُمَا، وَأَجْرِ يَا رَبِّ لُطْفَكَ الْخَفِيَّ فِي أُمُورِنَا وَالْمُسْلِمِينَ أَجْمَعِينَ.","latin":"Allâhümme salli alâ seyyidinâ Muhammedinin nebiyyil ümmiyyi ve alâ âlihî ve sahbihî ve sellim adede mâ fis semâvâti ve mâ fil ardı ve mâ beynehümâ. Ve ecri yâ Rabbi lutfekel hafiyye fî umûrinâ vel müslimîne ecmaîn.","meaning":"Allah’ım! Göklerde, yerde ve ikisi arasında bulunanların sayısınca ümmî Peygamber Efendimiz Muhammed’e, ailesine ve ashabına salât ve selâm eyle. Ey Rabbim, gizli lütfunu işlerimizde ve bütün Müslümanların işlerinde göster.","cat":"derleme","note":"","source":"","arabicDraft":false},{"id":"koleksiyon181","name":"Habîballâh’a Selâm","aliases":"Orijinal liste: 181","arabic":"الصَّلَاةُ وَالسَّلَامُ عَلَيْكَ يَا حَبِيبَ اللَّهِ. الصَّلَاةُ وَالسَّلَامُ عَلَيْكَ يَا رَسُولَ اللَّهِ. الصَّلَاةُ وَالسَّلَامُ عَلَيْكَ يَا سَيِّدَ الْأَوَّلِينَ وَالْآخِرِينَ. اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ وَعَلَى آلِ سَيِّدِنَا مُحَمَّدٍ.","latin":"Essalâtü vesselâmü aleyke yâ Habîballâh. Essalâtü vesselâmü aleyke yâ Resûlallâh. Essalâtü vesselâmü aleyke yâ seyyidel evvelîne vel âhirîn. Allâhümme salli alâ seyyidinâ Muhammedin ve alâ âli seyyidinâ Muhammed.","meaning":"Ey Allah’ın sevgilisi, sana salât ve selâm olsun. Ey Allah’ın Resulü, sana salât ve selâm olsun. Ey öncekilerin ve sonrakilerin efendisi, sana salât ve selâm olsun. Allah’ım, Efendimiz Muhammed’e ve ailesine salât eyle.","cat":"derleme","note":"","source":"","arabicDraft":false},{"id":"koleksiyon27","name":"Furkân Salavatı","aliases":"","arabic":"اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ صَاحِبِ الْفَرْقِ وَالْفُرْقَانِ وَجَامِعِ الْوَرَقِ وَمُنْزِلِهِ مِنْ سَمَاءِ الْقُرْآنِ وَعَلَى آلِ مُحَمَّدٍ وَسَلِّمْ","latin":"Allâhümme salli alâ seyyidinâ Muhammedin sâhibil-farki vel-furkâni ve câmiil-varakı ve münzilihî min semâil-Kur’âni ve alâ âli Muhammedin ve sellim.","meaning":"Allah’ım! Ayırma ve Furkân sahibi, sayfaları bir araya getiren ve onu Kur’an semasından indiren olarak anılan Efendimiz Muhammed’e (sallallahu aleyhi ve sellem) ve ailesine salât ve selâm eyle.","cat":"derleme","note":"","source":"","source_note":" Türkçe anlam, mevcut Latin okunuş üzerinden hazırlanmıştır; özgün nüsha karşılaştırması bekleniyor.","arabicDraft":false},{"id":"koleksiyon160","name":"Mahlukatın Nefesleri Adedince","aliases":"","arabic":"اَللّٰهُمَّ صَلِّ وَسَلِّمْ عَلٰى سَيِّدِنَا وَنَبِيِّنَا مُحَمَّدٍ بِعَدَدِ اَنْفَاسِ الْمَخْلُوقَاتِ. اَللّٰهُمَّ صَلِّ وَسَلِّمْ عَلٰى سَيِّدِنَا وَنَبِيِّنَا مُحَمَّدٍ بِعَدَدِ اَشْعَارِ الْمَوْجُودَاتِ. اَللّٰهُمَّ صَلِّ وَسَلِّمْ عَلٰى سَيِّدِنَا وَنَبِيِّنَا مُحَمَّدٍ بِعَدَدِ اللَّوْحِ وَالدَّعَوَاتِ. اَللّٰهُمَّ صَلِّ وَسَلِّمْ عَلٰى سَيِّدِنَا وَنَبِيِّنَا مُحَمَّدٍ بِعَدَدِ سَبْعِ سَوَاكِنِ الْاَرْضِ وَالسَّمَاوَاتِ. اَللّٰهُمَّ صَلِّ وَسَلِّمْ عَلٰى سَيِّدِنَا وَنَبِيِّنَا مُحَمَّدٍ بِعَدَدِ مَا خَلَقَ الْبَدَايَا وَالنَّهَايَا اَبَدَ الْاَبَدِ. اَللّٰهُمَّ صَلِّ وَسَلِّمْ عَلٰى سَيِّدِنَا وَنَبِيِّنَا مُحَمَّدٍ بِعَدَدِ مَا خَلَقَ مِنْ حَشْرِهِ وَاٰخِرِ بَقَائِهِ وَسَلِّمْ تَسْلِيمًا كَثِيرًا كَثِيرًا.","latin":"Allahümme salli ve sellim ala seyyidina ve nebiyyina muhammedin bi adedi enfasil mahlukat. Allahümme salli ve sellim ala seyyidina ve nebiyyina muhammedin bi adedi eş’aril mevcudat. Allahümme salli ve sellim ala seyyidina ve nebiyyina muhammedin bi adedil levhı ved deavat. Allahümme salli ve sellim ala seyyidina ve nebiyyina muhammedin bi adedi seb’ı sevakinil erdı ves semavat. Allahümme salli ve sellim ala seyyidina ve nebiyyina muhammedin bi adedi ma halekal bedaya ven nehaya ebedil ebed. Allahümme salli ve sellim ala seyyidina ve nebiyyina muhammedin bi adedi ma haleka min haşrihi ve ahıri bekaihi ve sellim tesliymen kesiyran kesiyra.","meaning":"Allah’ım! Efendimiz Muhammed’e yaratılmışların nefesleri, varlıkların kılları, Levh ve dualar, yerler ve gökler, başlangıçtan sona yarattığın bütün şeyler sayısınca salât ve selam eyle; ona bol bol selam ihsan eyle.","cat":"derleme","note":"","source":"","source_note":"","arabicDraft":false,"previousArabic":"اللهم صل و سلم على سيدنا و نابيينا محمد ب ادادي انفاسيل ماهلوكات. اللهم صل و سلم على سيدنا و نابيينا محمد ب ادادي اشاريل ماوجودات. اللهم صل و سلم على سيدنا و نابيينا محمد ب اداديل لاوها واد دااوات. اللهم صل و سلم على سيدنا و نابيينا محمد ب ادادي سابا ساواكينيل اردا واس ساماوات. اللهم صل و سلم على سيدنا و نابيينا محمد ب ادادي ما هالاكال بادايا وان ناهايا اباديل اباد. اللهم صل و سلم على سيدنا و نابيينا محمد ب ادادي ما هالاكا من هاشريهي و اهاري باكايهي و سلم تاسلييمان كاسييران كاسييرا.","submittedArabic":"اَللّٰهُمَّ صَلِّ وَسَلِّمْ عَلٰى سَيِّدِنَا وَنَبِيِّنَا مُحَمَّدٍ بِعَدَدِ اَنْفَاسِ الْمَخْلُوقَاتِ. اَللّٰهُمَّ صَلِّ وَسَلِّمْ عَلٰى سَيِّدِنَا وَنَبِيِّنَا مُحَمَّدٍ بِعَدَدِ اَشْعَارِ الْمَوْجُودَاتِ. اَللّٰهُمَّ صَلِّ وَسَلِّمْ عَلٰى سَيِّدِنَا وَنَبِيِّنَا مُحَمَّدٍ بِعَدَدِ اللَّوْحِ وَالدَّعَوَاتِ. اَللّٰهُمَّ صَلِّ وَسَلِّمْ عَلٰى سَيِّدِنَا وَنَبِيِّنَا مُحَمَّدٍ بِعَدَدِ سَبْعِ سَوَاكِنِ الْاَرْضِ وَالسَّمَاوَاتِ. اَللّٰهُمَّ صَلِّ وَسَلِّمْ عَلٰى سَيِّدِنَا وَنَبِيِّنَا مُحَمَّدٍ بِعَدَدِ مَا خَلَقَ الْبَدَايَا وَالنَّهَايَا اَبَدَ الْاَبَدِ. اَللّٰهُمَّ صَلِّ وَسَلِّمْ عَلٰى سَيِّدِنَا وَنَبِيِّنَا مُحَمَّدٍ بِعَدَدِ مَا خَلَقَ مِنْ حَشْرِهِ وَاٰخِرِ بَقَائِهِ وَسَلِّمْ تَسْلِيمًا كَثِيرًا كَثِيرًا.","displayNumber":105},{"id":"koleksiyon190","name":"Nefesler ve Levh Adedince","aliases":"Orijinal liste: 190","arabic":"اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ بِعَدَدِ اَلْفِ اَنْفَاسِ الْمَخْلُوقَاتِ. وَصَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ بِعَدَدِ اَشْعَارِ الْمَوْجُودَاتِ. وَصَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ بِعَدَدِ سَوَاكِنِ الْاَرْضِ وَالسَّمَاوَاتِ. وَصَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ بِعَدَدِ حُرُوفِ اللَّوْحِ وَالدَّعَوَاتِ. وَصَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ بِعَدَدِ كُلِّ الْمَعْدُودَاتِ وَالْمَعْلُومَاتِ. مِنْ اَوَّلِ اَزَلِهِ وَاَوْسَطِ حَشْرِهِ وَاٰخِرِ بَقَائِهِ وَعَلٰى اٰلِهِ وَصَحْبِهِ الطَّيِّبِينَ الطَّاهِرِينَ اَجْمَعِينَ.","latin":"Allâhümme salli alâ seyyidinâ Muhammedin biadedi elfi enfâsil mahlûkât. Ve salli alâ seyyidinâ Muhammedin biadedi eş’âril mevcûdât. Ve salli alâ seyyidinâ Muhammedin biadedi sevâkinil-ardı ves-semâvât. Ve salli alâ seyyidinâ Muhammedin biadedi hurûfil levhi veddeavât. Ve salli alâ seyyidinâ Muhammedin biadedi küllil me’dûdâti vel ma’lûmât. Min evveli ezelihî ve evsetı haşrihî ve âhıri bekâihî ve alâ âlihî ve sahbihittayyibînettâhirîne ecmaîn.","meaning":"Allah'ım! Efendimiz Muhammed'e (sallallahu aleyhi ve sellem), yaratılmışların nefeslerinin bin katı sayısınca salât eyle. Var olanların kıllarının sayısınca ona salât eyle. Yerin ve göklerin hareketsiz varlıklarının sayısınca ona salât eyle. Levhin ve duaların harflerinin sayısınca ona salât eyle. Sayılan ve bilinen bütün şeylerin sayısınca ona salât eyle. Ezelin başlangıcından, haşrin ortasından ve bekânın sonuna kadar; tertemiz ve hayırlı ailesine ve ashabının hepsine de salât eyle.","cat":"derleme","note":"","source":"","arabicDraft":false,"previousArabic":"اللهم صل على سيدنا محمد بيادادي الفي انفاسيل ماهلوكات. و صل على سيدنا محمد بيادادي اشاريل ماوجودات. و صل على سيدنا محمد بيادادي ساواكينيلارزا واساوات. و صل على سيدنا محمد بيادادي هوروفيل لاوهي واددااوات. و صل على سيدنا محمد بيادادي كولليل مادوداتي وال مالومات. من اووالي ازاليهي و اوساتا هاشريهي و اهاري باكايهي و على اليهي و ساهبيهيتتاييبيناتتاهيرينا أجمعين.","submittedArabic":"اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ بِعَدَدِ اَلْفِ اَنْفَاسِ الْمَخْلُوقَاتِ. وَصَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ بِعَدَدِ اَشْعَارِ الْمَوْجُودَاتِ. وَصَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ بِعَدَدِ سَوَاكِنِ الْاَرْضِ وَالسَّمَاوَاتِ. وَصَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ بِعَدَدِ حُرُوفِ اللَّوْحِ وَالدَّعَوَاتِ. وَصَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ بِعَدَدِ كُلِّ الْمَعْدُودَاتِ وَالْمَعْلُومَاتِ. مِنْ اَوَّلِ اَزَلِهِ وَاَوْسَطِ حَشْرِهِ وَاٰخِرِ بَقَائِهِ وَعَلٰى اٰلِهِ وَصَحْبِهِ الطَّيِّبِينَ الطَّاهِرِينَ اَجْمَعِينَ.","source_note":"","displayNumber":106},{"id":"koleksiyon193","name":"Salât-ı Kutbiyye","aliases":"Orijinal liste: 193","arabic":"اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ وَعَلٰى اٰلِ سَيِّدِنَا مُحَمَّدٍ.\nاَللّٰهُمَّ صَلِّ عَلٰى قَائِدِنَا سَيِّدِنَا مُحَمَّدٍ وَعَلٰى اٰلِ سَيِّدِنَا مُحَمَّدٍ.\nاَللّٰهُمَّ صَلِّ عَلٰى رَائِدِنَا سَيِّدِنَا مُحَمَّدٍ وَعَلٰى اٰلِ سَيِّدِنَا مُحَمَّدٍ.\nاَللّٰهُمَّ صَلِّ عَلٰى بَدْرِ الدُّجٰى سَيِّدِنَا مُحَمَّدٍ وَعَلٰى اٰلِ سَيِّدِنَا مُحَمَّدٍ.\nاَللّٰهُمَّ صَلِّ عَلٰى شَمْسِ الضُّحٰى سَيِّدِنَا مُحَمَّدٍ وَعَلٰى اٰلِ سَيِّدِنَا مُحَمَّدٍ.\nاَللّٰهُمَّ صَلِّ عَلٰى نُورِ الْهُدٰى سَيِّدِنَا مُحَمَّدٍ وَعَلٰى اٰلِ سَيِّدِنَا مُحَمَّدٍ.\nاَللّٰهُمَّ صَلِّ عَلٰى نَبِيِّنَا وَرَسُولِنَا وَشَفِيعِنَا سَيِّدِنَا مُحَمَّدٍ وَعَلٰى اٰلِ سَيِّدِنَا مُحَمَّدٍ.\nبِعَدَدِ مَا فِي عِلْمِ اللّٰهِ صَلَاةً دَائِمَةً بِدَوَامِ مُلْكِ اللّٰهِ.","latin":"Allâhümme salli alâ seyyidinâ Muhammedin ve alâ âli seyyidinâ Muhammed.\nAllâhümme salli alâ kâidinâ seyyidinâ Muhammedin ve alâ âli seyyidinâ Muhammed.\nAllâhümme salli alâ râidinâ seyyidinâ Muhammedin ve alâ âli seyyidinâ Muhammed.\nAllâhümme salli alâ Bedri’d-dücâ seyyidinâ Muhammedin ve alâ âli seyyidinâ Muhammed.\nAllâhümme salli alâ Şemsi’d-duhâ seyyidinâ Muhammedin ve alâ âli seyyidinâ Muhammed.\nAllâhümme salli alâ Nûri’l-hüdâ seyyidinâ Muhammedin ve alâ âli seyyidinâ Muhammed.\nAllâhümme salli alâ nebiyyinâ ve resûlinâ ve şefîinâ seyyidinâ Muhammedin ve alâ âli seyyidinâ Muhammed.\nBiadedi mâ fî ilmillâhi salâten dâimeten bidevâmi mülkillâh.","meaning":"Allah'ım! Efendimiz Muhammed'e (sallallahu aleyhi ve sellem) ve ailesine salât eyle. Allah'ım! Önderimiz Efendimiz Muhammed'e ve ailesine salât eyle. Allah'ım! Rehberimiz Efendimiz Muhammed'e ve ailesine salât eyle. Allah'ım! Karanlığın dolunayı Efendimiz Muhammed'e ve ailesine salât eyle. Allah'ım! Kuşluk vaktinin güneşi Efendimiz Muhammed'e ve ailesine salât eyle. Allah'ım! Hidayetin nuru Efendimiz Muhammed'e ve ailesine salât eyle. Allah'ım! Peygamberimiz, elçimiz ve şefaatçimiz Efendimiz Muhammed'e ve ailesine salât eyle. Allah'ın ilminde bulunanlar sayısınca, mülkünün devamı boyunca sürekli bir salât eyle.","cat":"derleme","note":"","source":"","arabicDraft":false,"previousArabic":"اللهم صل على سيدنا محمد و على اليهي سيدنا محمد. اللهم صل على كايدينا سيدنا محمد و على اليهي. اللهم صل على رايدينا سيدنا محمد و على اليهي. اللهم صل على بادروددوجا سيدنا محمد و على اليهي. اللهم صل على شامسوددوها سيدنا محمد و على اليهي. اللهم صل على نورولهودا سيدنا محمد و على اليهي. اللهم صل على نابيينا و راسولينا و شافيينا سيدنا محمد و على اليهي. بيادادي ما في يلميللاهي صلاة دايماتان بيداوامي مولكيللاه.","submittedArabic":"اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ وَعَلٰى اٰلِ سَيِّدِنَا مُحَمَّدٍ.\nاَللّٰهُمَّ صَلِّ عَلٰى قَائِدِنَا سَيِّدِنَا مُحَمَّدٍ وَعَلٰى اٰلِ سَيِّدِنَا مُحَمَّدٍ.\nاَللّٰهُمَّ صَلِّ عَلٰى رَائِدِنَا سَيِّدِنَا مُحَمَّدٍ وَعَلٰى اٰلِ سَيِّدِنَا مُحَمَّدٍ.\nاَللّٰهُمَّ صَلِّ عَلٰى بَدْرِ الدُّجٰى سَيِّدِنَا مُحَمَّدٍ وَعَلٰى اٰلِ سَيِّدِنَا مُحَمَّدٍ.\nاَللّٰهُمَّ صَلِّ عَلٰى شَمْسِ الضُّحٰى سَيِّدِنَا مُحَمَّدٍ وَعَلٰى اٰلِ سَيِّدِنَا مُحَمَّدٍ.\nاَللّٰهُمَّ صَلِّ عَلٰى نُورِ الْهُدٰى سَيِّدِنَا مُحَمَّدٍ وَعَلٰى اٰلِ سَيِّدِنَا مُحَمَّدٍ.\nاَللّٰهُمَّ صَلِّ عَلٰى نَبِيِّنَا وَرَسُولِنَا وَشَفِيعِنَا سَيِّدِنَا مُحَمَّدٍ وَعَلٰى اٰلِ سَيِّدِنَا مُحَمَّدٍ.\nبِعَدَدِ مَا فِي عِلْمِ اللّٰهِ صَلَاةً دَائِمَةً بِدَوَامِ مُلْكِ اللّٰهِ.","source_note":"","displayNumber":107},{"id":"koleksiyon195","name":"Büyük Şan ve Şeref Salavatı","aliases":"Orijinal liste: 195","arabic":"اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ وَتَرَحَّمْ وَتَحَنَّنْ عَلٰى سَيِّدِنَا وَمَوْلَانَا مُحَمَّدٍ كَمَا يَلِيقُ بِعَظِيمِ شَأْنِ شَرَفِهِ وَكَمَالِهِ وَرِضَاكَ عَنْهُ وَمَا تُحِبُّ وَتَرْضٰى لَهُ دَائِماً اَبَداً بِعَدَدِ مَعْلُومَاتِكَ وَمِدَادَ كَلِمَاتِكَ وَرِضَاءَ نَفْسِكَ وَزِنَةَ عَرْشِكَ. وَعَلٰى جَمِيعِ الْاَنْبِيَاءِ وَالْمُرْسَلِينَ وَمَلَائِكَتِكَ الْمُقَرَّبِينَ وَعَلَيْنَا مَعَهُمْ وَالْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ وَالْمُسْلِمِينَ وَالْمُسْلِمَاتِ اَجْمَعِينَ.","latin":"Allâhümme salli ve sellim ve bârik ve terahham ve tehannen alâ seyyidinâ ve mevlânâ Muhammedin kemâ yelîku bi-azîmi şe'ni şerefihî ve kemâlihî ve rıdâke anhü ve mâ tuhibbü ve terdâ lehû dâimen ebeden bi-adedi ma'lûmâtike ve midâde kelimâtike ve rıdâe nefsike ve zinete arşike. Ve alâ cemî'il enbiyâi vel mürselîne ve melâiketikel mukarrabîne ve aleynâ meahüm vel mü'minîne vel mü'minât vel müslimîne vel müslimât ecmaîn.","meaning":"Allah'ım! Efendimiz ve Mevlâmız Muhammed'e (sallallahu aleyhi ve sellem), onun şanının, şerefinin ve kemâlinin büyüklüğüne yaraşır şekilde; ondan razı oluşuna ve onun için sevip razı olduğun şeylere uygun olarak daima ve ebediyen, bildiklerinin sayısınca, kelimelerinin mürekkebi miktarınca, rızanın ölçüsünce ve arşının ağırlığınca salât, selâm ve bereket ihsan eyle; ona merhamet ve şefkat göster. Bütün peygamberlere ve elçilere, Sana yakın meleklere, onlarla birlikte bize, bütün mümin erkek ve kadınlara ve bütün Müslüman erkek ve kadınlara da ihsan eyle.","cat":"derleme","note":"","source":"","arabicDraft":false,"previousArabic":"اللهم صل و سلم و بارك و تاراههام و تاهاننان على سيدنا و ماولانا محمد كاما ياليكو بيازيمي شانا شارافيهي و كاماليهي و رازاكا انهو و ما توهيببو و تاردا لاهو دايمان ابادان بيادادي مالوماتيكا و ميدادا كاليماتيكا و راداا نافسيكا و زيناتا ارشيكا. و على جامييل انبيياي وال مورسالين و مالايكاتيكال موكاررابين و الاينا مااهوم وال مومينينا وال مومينات وال موسليمينا وال موسليمات أجمعين.","submittedArabic":"اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ وَتَرَحَّمْ وَتَحَنَّنْ عَلٰى سَيِّدِنَا وَمَوْلَانَا مُحَمَّدٍ كَمَا يَلِيقُ بِعَظِيمِ شَأْنِ شَرَفِهِ وَكَمَالِهِ وَرِضَاكَ عَنْهُ وَمَا تُحِبُّ وَتَرْضٰى لَهُ دَائِماً اَبَداً بِعَدَدِ مَعْلُومَاتِكَ وَمِدَادَ كَلِمَاتِكَ وَرِضَاءَ نَفْسِكَ وَزِنَةَ عَرْشِكَ. وَعَلٰى جَمِيعِ الْاَنْبِيَاءِ وَالْمُرْسَلِينَ وَمَلَائِكَتِكَ الْمُقَرَّبِينَ وَعَلَيْنَا مَعَهُمْ وَالْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ وَالْمُسْلِمِينَ وَالْمُسْلِمَاتِ اَجْمَعِينَ.","source_note":"","displayNumber":108}];
const $=id=>document.getElementById(id),storeKey='salavat_bahcesi_v5',ledgerKey='salavat_bahcesi_omurluk_v1',fmt=n=>Number(n||0).toLocaleString('tr-TR');
const clean=n=>Math.min(Number.MAX_SAFE_INTEGER,Math.max(0,Math.floor(Number(n)||0)));
function readJSON(key,fallback){try{let o=JSON.parse(localStorage.getItem(key));return o&&typeof o==='object'?o:fallback}catch(e){return fallback}}
let state=readJSON(storeKey,{}),ledger=readJSON(ledgerKey,{counts:{},total:0});
state.counts=state.counts&&typeof state.counts==='object'&&!Array.isArray(state.counts)?state.counts:{};state.favorites=Array.isArray(state.favorites)?state.favorites:[];
ledger.counts=ledger.counts&&typeof ledger.counts==='object'&&!Array.isArray(ledger.counts)?ledger.counts:{};
// Preserve the old migration and the original salavat IDs.
if(!state.migratedIbrahimiyyeV12){const old=state.counts.s9;if(old){const r=state.counts.s8||{session:0,lifetime:0};r.session=clean(r.session)+clean(old.session);r.lifetime=clean(r.lifetime)+clean(old.lifetime);state.counts.s8=r;delete state.counts.s9}state.favorites=state.favorites.filter(id=>id!=='s9');state.migratedIbrahimiyyeV12=true}
function synchronizeLedger(){for(const [id,r] of Object.entries(state.counts)){if(!r||typeof r!=='object'){state.counts[id]={session:0,lifetime:0};continue}r.session=clean(r.session);r.lifetime=Math.max(clean(r.lifetime),clean(ledger.counts[id]));ledger.counts[id]=r.lifetime}for(const [id,n] of Object.entries(ledger.counts)){ledger.counts[id]=clean(n);if(!state.counts[id])state.counts[id]={session:0,lifetime:clean(n)}}ledger.total=Math.max(clean(ledger.total),Object.values(ledger.counts).reduce((a,n)=>a+clean(n),0));}
synchronizeLedger();
function save(){synchronizeLedger();window.persistNativeState?.({state,ledger});try{localStorage.setItem(ledgerKey,JSON.stringify(ledger));localStorage.setItem(storeKey,JSON.stringify(state));return true}catch(e){$('status').textContent='Kayıt yapılamadı. Lütfen okuma yedeğinizi indirin.';return false}}
function record(id){if(!state.counts[id])state.counts[id]={session:0,lifetime:clean(ledger.counts[id])};return state.counts[id]}
function grand(){return ledger.total}
function totals(){document.querySelectorAll('.grand').forEach(e=>e.textContent=fmt(grand()))}
let currentView='reader',startIndex=0,loadedThrough=0,restoring=false,favOnly=false,scrollTimer=null;
function el(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e}
function show(view){currentView=view;['catalog','reader','stats','devotional'].forEach(id=>$(id).classList.toggle('hidden',id!==view));totals()}
function addReading(id){const r=record(id);if(r.session>=1000)return;r.session++;r.lifetime++;ledger.counts[id]=r.lifetime;ledger.total=clean(ledger.total)+1;save();updateCounters();}
function resetReading(id){if(!confirm('Bu salavatın güncel sayacı sıfırlansın mı? Ömürlük okumalarınız korunacak.'))return;record(id).session=0;save();updateCounters()}
function updateCounters(){document.querySelectorAll('[data-counter]').forEach(e=>{const r=record(e.dataset.counter);e.querySelector('.session').textContent=fmt(r.session);e.querySelector('.lifetime').textContent='Ömürlük okuma: '+fmt(r.lifetime);e.querySelector('.increment').disabled=r.session>=1000});totals()}
function makeDetails(x){if(!x.note&&!x.source)return null;const d=el('details','details'),sum=el('summary','', 'Açıklama, rivayet ve kaynak');d.open=!!state.expanded?.[x.id];d.ontoggle=()=>{state.expanded=state.expanded||{};state.expanded[x.id]=d.open;save()};d.append(sum);if(x.note){const n=el('div','note');const chunks=x.note.split(/(https?:\/\/[^\s]+)/g);for(const c of chunks){if(/^https?:/.test(c)){const a=el('a','',c);a.href=c;a.target='_blank';a.rel='noopener noreferrer';n.append(a)}else n.append(document.createTextNode(c))}d.append(n)}if(x.source)d.append(el('p','source',x.source));if(x.reflection){const rf=el('div','reflection');rf.append(el('strong','', '🌿 Manevî tefekkür ve hayatımıza bakan yönü'),el('p','',x.reflection),el('small','','Bu bölüm, yukarıdaki rivayetten ayrı bir yorumdur; bir hadis veya belirli bir velîye ait söz olarak nakledilmez.'));d.append(rf)}return d}
function makeCard(x,i){const card=el('article','card readCard');card.dataset.id=x.id;card.id='salavat-'+x.id;card.append(el('div','eyebrow',(i+1)+' / '+items.length));card.append(el('h2','',x.name));const ar=el('div','arabic',x.arabicDraft?'Arapça asıl metin henüz doğrulanmadı.':(x.arabic||'Arapça metin bekleniyor.'));ar.lang='ar';ar.dir='rtl';card.append(ar,el('div','divider'),el('div','latin',x.latin||''),el('div','meaning',x.meaning||'Türkçe anlam henüz eklenmedi.'));const details=makeDetails(x);if(details)card.append(details);
 const counter=el('div','counter');counter.dataset.counter=x.id;const row=el('div','row'),values=el('div','');values.append(el('div','sub','Bu salavatın sayacı'),el('div','count session','0'),el('div','sub lifetime','Ömürlük okuma: 0'));const add=el('button','gold increment','＋ Okudum');add.onclick=()=>addReading(x.id);row.append(values,add);const reset=el('button','minor','↻ Sayacı sıfırla');reset.onclick=()=>resetReading(x.id);counter.append(row,el('p','sub','Hedef: 1000 · Sıfırlama ömürlük toplamı silmez.'),reset);card.append(counter);
 const controls=el('div','wrap controls');controls.style.marginTop='16px';const fav=el('button','minor',state.favorites.includes(x.id)?'♥ En Sevdiklerimden':'♡ En Sevdiğim');fav.onclick=()=>{state.favorites=state.favorites.includes(x.id)?state.favorites.filter(id=>id!==x.id):[...state.favorites,x.id];save();fav.textContent=state.favorites.includes(x.id)?'♥ En Sevdiklerimden':'♡ En Sevdiğim'};controls.append(fav);card.append(controls);addHumanAudioControls(card,x);return card;
}
function opening(){const c=el('section','card opening');c.setAttribute('aria-label','Açılış ayetleri');c.append(el('div','arabic','بِسْمِ اللّٰهِ الرَّحْمٰنِ الرَّحِيمِ'),el('div','latin','Bismillâhirrahmânirrahîm.'),el('p','meaning','Rahmân ve Rahîm olan Allah’ın adıyla.'));const verses=[{"ref": "33:56", "ar": "إِنَّ اللَّهَ وَمَلَائِكَتَهُ يُصَلُّونَ عَلَى النَّبِيِّ ۚ يَا أَيُّهَا الَّذِينَ آمَنُوا صَلُّوا عَلَيْهِ وَسَلِّمُوا تَسْلِيمًا", "latin": "İnnallâhe ve melâiketehû yüsallûne alen-nebiyyi yâ eyyühellezîne âmenû sallû aleyhi ve sellimû teslîmâ.", "tr": "Şüphesiz Allah ve melekleri Peygamber’e salât ederler. Ey iman edenler! Siz de ona salât edin ve tam bir teslimiyetle selâm verin."}, {"ref": "21:107", "ar": "وَمَا أَرْسَلْنَاكَ إِلَّا رَحْمَةً لِلْعَالَمِينَ", "latin": "Ve mâ erselnâke illâ rahmeten lil-âlemîn.", "tr": "Seni ancak âlemlere rahmet olarak gönderdik."}, {"ref": "68:4", "ar": "وَإِنَّكَ لَعَلَىٰ خُلُقٍ عَظِيمٍ", "latin": "Ve inneke lealâ hulukın azîm.", "tr": "Sen elbette yüce bir ahlâk üzeresin."}, {"ref": "36:1", "ar": "يسٓ", "latin": "Yâ Sîn.", "tr": "Yâ Sîn."}, {"ref": "20:1", "ar": "طٰهٰ", "latin": "Tâ Hâ.", "tr": "Tâ Hâ."}];for(const verse of verses){const block=el('div','opening-verse');block.dataset.verse=verse.ref;const arabic=el('div','arabic',verse.ar);arabic.lang='ar';arabic.dir='rtl';block.append(arabic,el('div','latin',verse.latin),el('p','meaning',verse.tr));c.append(block)}return c}
function appendBatch(){const end=Math.min(items.length,loadedThrough+6),fragment=document.createDocumentFragment();for(let k=loadedThrough;k<end;k++)fragment.append(makeCard(items[k],k));$('pages').append(fragment);loadedThrough=end;$('moreBtn').disabled=end===items.length;$('moreBtn').textContent=end===items.length?'Serinin sonu ✓':'Devamını göster ↓';updateCounters()}
function readerInset(){return Math.ceil(document.getElementById('appTop')?.getBoundingClientRect().height||82)+8}
function capturePlace(){if(restoring||currentView!=='reader')return;const cards=[...document.querySelectorAll('.readCard')];if(!cards.length)return;const card=cards.find(c=>c.getBoundingClientRect().bottom>readerInset())||cards[cards.length-1];state.lastRead={id:card.dataset.id,offset:Math.max(0,readerInset()-card.getBoundingClientRect().top)};$('position').textContent=(items.findIndex(x=>x.id===card.dataset.id)+1)+' / '+items.length;save()}
function openReader(id,offset=0,restore=false,landing=false){let index=items.findIndex(x=>x.id===id);if(index<0)index=0;clearTimeout(scrollTimer);restoring=true;startIndex=index;$('pages').replaceChildren();if(index===0)$('pages').append(opening());loadedThrough=index;appendBatch();show('reader');$('prevBtn').disabled=index===0;$('position').textContent=(index+1)+' / '+items.length;if(!landing)state.lastRead={id:items[index].id,offset:clean(offset)};save();
 requestAnimationFrame(()=>{const c=document.getElementById('salavat-'+items[index].id);window.scrollTo(0,landing?0:Math.max(0,window.scrollY+c.getBoundingClientRect().top-readerInset()+clean(offset)));requestAnimationFrame(()=>{restoring=false})});
}
function renderList(){const q=searchKey($('search').value);$('list').replaceChildren();items.forEach((x,i)=>{if(favOnly&&!state.favorites.includes(x.id))return;if(q&&!searchKey((i+1)+' '+x.name+' '+(x.aliases||'')).includes(q))return;const b=el('button','listItem'+(state.lastRead?.id===x.id?' active':''));b.append(el('small','',String(i+1)),document.createTextNode(x.name));b.onclick=()=>openReader(x.id);$('list').append(b)});if(!$('list').children.length)$('list').append(el('p','sub','Bu aramaya uygun salavat yok.'))}
function renderStats(){totals();$('breakdown').replaceChildren();items.forEach((x,i)=>{const r=record(x.id);if(!r.lifetime)return;const row=el('div','row statsRow');row.append(el('span','',(i+1)+'. '+x.name),el('strong','',fmt(r.lifetime)));$('breakdown').append(row)});if(!$('breakdown').children.length)$('breakdown').textContent='Henüz okuma kaydı yok.'}
function filterDrawer(){const q=searchKey($('drawerSearch').value);let found=0;document.querySelectorAll('.drawerLink').forEach(a=>{const match=searchKey(a.textContent+' '+(items.find(x=>x.id===a.dataset.jump)?.aliases||'')).includes(q);a.classList.toggle('hidden',!match);if(match)found++});$('drawerEmpty').classList.toggle('hidden',found>0)}
function closeDrawer(){$('sideMenu').open=false;document.body.classList.remove('menuOpen');$('listBtn').focus()}
$('listBtn').onclick=()=>{capturePlace();document.querySelectorAll('.drawerLink').forEach(a=>a.setAttribute('aria-current',String(a.dataset.jump===state.lastRead?.id)))};
$('sideMenu').ontoggle=()=>document.body.classList.toggle('menuOpen',$('sideMenu').open);
$('closeDrawer').onclick=closeDrawer;document.querySelector('.drawerShade').onclick=closeDrawer;
$('drawerSearch').oninput=filterDrawer;
document.querySelectorAll('.drawerLink').forEach(a=>a.onclick=e=>{e.preventDefault();closeDrawer();openReader(a.dataset.jump)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('sideMenu').open)closeDrawer()});
$('resumeBtn').onclick=()=>{const last=state.lastRead;openReader(last?.id||items[0].id,last?.offset||0,true)};
$('statsBtn').onclick=()=>{capturePlace();renderStats();show('stats');window.scrollTo(0,0)};
$('prevBtn').onclick=()=>{capturePlace();const i=items.findIndex(x=>x.id===state.lastRead?.id);openReader(items[Math.max(0,i-1)].id)};
$('moreBtn').onclick=appendBatch;$('search').oninput=renderList;$('favoritesBtn').onclick=()=>{favOnly=true;renderList()};$('allBtn').onclick=()=>{favOnly=false;renderList()};
$('resetAll').onclick=()=>{if(!confirm('Bütün salavatların güncel sayaçları sıfırlansın mı? Ömürlük toplamlar ve kaldığınız yer korunacak.'))return;Object.values(state.counts).forEach(r=>r.session=0);save();updateCounters();renderStats();$('status').textContent='Güncel sayaçlar sıfırlandı. Ömürlük okumalarınız korundu.'};
$('export').onclick=()=>{capturePlace();const blob=new Blob([JSON.stringify({app:'salavat-bahcesi',version:26,exportedAt:new Date().toISOString(),data:state,lifetimeLedger:ledger},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=el('a');a.href=url;a.download='salavat-bahcesi-yedek.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)};
$('importFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const o=JSON.parse(await f.text());if(o.app!=='salavat-bahcesi'||!o.data||!o.data.counts||Array.isArray(o.data.counts)||typeof o.data.counts!=='object'||!Array.isArray(o.data.favorites))throw Error('Geçersiz yedek');if(!confirm('Yedekteki güncel sayaçlar ve favoriler yüklensin mi? Mevcut ömürlük okumalarınız azaltılmaz.'))return;const incoming=o.lifetimeLedger;if(incoming&&incoming.counts&&typeof incoming.counts==='object'){for(const [id,n] of Object.entries(incoming.counts))ledger.counts[id]=Math.max(clean(ledger.counts[id]),clean(n));ledger.total=Math.max(clean(ledger.total),clean(incoming.total))}state={...state,...o.data};synchronizeLedger();save();renderStats();$('status').textContent='Yedek yüklendi. Ömürlük okumalarınız korundu.'}catch(err){alert('Yedek açılamadı: '+err.message)}finally{e.target.value=''}};
window.addEventListener('scroll',()=>{if(restoring||currentView!=='reader')return;if(window.innerHeight+window.scrollY>=document.documentElement.scrollHeight-1000&&loadedThrough<items.length)appendBatch();clearTimeout(scrollTimer);scrollTimer=setTimeout(capturePlace,180)},{passive:true});
